.github/scripts/checks/check_lockfiles_p:
"""Run lockfile checks only for packages touched by changed paths."""

from __future__ import annotations

import shlex
import subprocess
import sys
import tomllib
from collections.abc import Collection, Mapping
from pathlib import Path, PurePosixPath

REPO_ROOT = Path(__file__).resolve().parents[3]
LIBS_ROOT = REPO_ROOT / "libs"
EXAMPLES_ROOT = REPO_ROOT / "examples"


def package_dirs() -> list[Path]:
    """Return every package directory that owns a `uv.lock`, in repo-path order."""
    libs = [path.parent for path in LIBS_ROOT.glob("*/Makefile")]
    partners = [path.parent for path in (LIBS_ROOT / "partners").glob("*/Makefile")]
    examples = [path.parent for path in EXAMPLES_ROOT.glob("*/pyproject.toml")]
    return sorted([*libs, *partners, *examples], key=_repo_path)


def _repo_path(path: Path) -> str:
    return path.relative_to(REPO_ROOT).as_posix()


def python_version(package: Path) -> str:
    """Return the interpreter version `package`'s lockfile must be resolved with."""
    if package.name in {"acp", "code", "evals", "talon"} and package.parent == LIBS_ROOT:
        return "3.14"
    return "3.12"


def _path_source_dirs(manifest_dir: Path, manifest: Mapping[str, object]) -> set[str]:
    """Return repo-relative dirs `manifest` consumes via `[tool.uv.sources]` paths."""
    tool = manifest.get("tool")
    uv = tool.get("uv") if isinstance(tool, Mapping) else None
    sources = uv.get("sources") if isinstance(uv, Mapping) else None
    if not isinstance(sources, Mapping):
        return set()

    dirs: set[str] = set()
    for spec in sources.values():
        if not isinstance(spec, Mapping):
            continue
        raw = spec.get("path")
        if not isinstance(raw, str):
            continue
        resolved = (manifest_dir / raw).resolve()
        try:
            dirs.add(resolved.relative_to(REPO_ROOT).as_posix())
        except ValueError:
            continue
    return dirs


def stale_lock_dirs(changed_manifests: Collection[str]) -> list[str]:
    """Return changed package directories and their transitive local consumers."""
    consumes: dict[str, set[str]] = {}
    for package in package_dirs():
        manifest_file = package / "pyproject.toml"
        if not manifest_file.is_file():
            continue
        repo_path = package.relative_to(REPO_ROOT).as_posix()
        manifest = tomllib.loads(manifest_file.read_text(encoding="utf-8"))
        consumes[repo_path] = _path_source_dirs(package, manifest)

    stale = {PurePosixPath(path).parent.as_posix() for path in changed_manifests}
    while True:
        dependents = {
            package
            for package, sources in consumes.items()
            if sources & stale and package not in stale
        }
        if not dependents:
            return sorted(stale)
        stale |= dependents


def _label(package: Path) -> str:
    try:
        return package.relative_to(LIBS_ROOT).as_posix()
    except ValueError:
        return f"../{package.relative_to(REPO_ROOT).as_posix()}"


def _touches_package(path: str, package: Path) -> bool:
    package_path = _repo_path(package)
    return path == package_path or path.startswith(f"{package_path}/")


def _packages_for_paths(paths: list[str]) -> list[Path]:
    packages = package_dirs()
    if not paths:
        return packages
    return [
        package
        for package in packages
        if any(_touches_package(path, package) for path in paths)
    ]


def _lock_command(package: Path, *, check: bool) -> list[str]:
    command = ["uv", "lock"]
    if check:
        command.append("--check")
    return [
        *command,
        "--directory",
        package.relative_to(REPO_ROOT).as_posix(),
        "--python",
        python_version(package),
    ]


def _lockfile_error(package: Path) -> str:
    package_path = package.relative_to(REPO_ROOT).as_posix()
    lockfile = f"{package_path}/uv.lock"
    command = shlex.join(_lock_command(package, check=False))
    return (
        f"::error file={lockfile},title=Out-of-date uv.lock::"
        f"{lockfile} is out of sync with {package_path}/pyproject.toml. "
        f"From the repository root, run `{command}` and commit the updated lockfile."
    )


def main(paths: list[str]) -> int:
    """Check lockfiles for packages touched by `paths`, or every package if empty."""
    packages = _packages_for_paths(paths)
    if not packages:
        print("✅ No package lockfiles need checking.")
        return 0
    for package in packages:
        print(f"🔍 Checking {_label(package)}")
        result = subprocess.run(
            _lock_command(package, check=True),
            check=False,
            cwd=REPO_ROOT,
        )
        if result.returncode != 0:
            print(_lockfile_error(package), file=sys.stderr)
            return result.returncode
    print("✅ All applicable lockfiles are up-to-date!")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

.github/scripts/checks/markdown_file_che:
"use strict";

// Detector for the "new Markdown files need acknowledgment" gate.
//
// The workflow (.github/workflows/markdown_file_check.yml) is a thin shim that
// requires `run` from this file, matching the repo pattern established by
// .github/scripts/labeling/close-old-prs.js. Everything the gate decides lives
// here so it can be executed against a fake octokit in
// .github/scripts/tests/checks/markdown_file_check.test.js — a decision that
// only appears inside the workflow's YAML `script:` string can be asserted on
// as text but never actually run, which lets an inverted condition ship green.

const STICKY_MARKER = "<!-- markdown-file-check -->";
const ACKNOWLEDGMENT_LABEL = "ci:ack-markdown";

// Who authors this workflow's own sticky comments. Matched on when finding the
// comment to update so a PR author cannot pre-post the marker and capture the
// slot; see findStickyComment.
const WORKFLOW_BOT_LOGIN = "github-actions[bot]";

// Distinct identity from WORKFLOW_BOT_LOGIN despite the same value today:
// this is "who opens release PRs" (release-please runs on GITHUB_TOKEN).
// Kept in step with RELEASE_PLEASE_AUTHOR in close-old-prs.js.
const RELEASE_PLEASE_AUTHOR = "github-actions[bot]";

// Mirrors the branch shape `separate-pull-requests: true` produces in
// release-please-config.json. The same literal is independently hardcoded in
// close-old-prs.js, release-notes.js, check_sdk_pin.yml, check_partner_bounds.yml,
// release_please_fanout_watch.yml, and release-please.yml — keep them in
// lockstep. A test pins this against release-please-config.json.
const RELEASE_PLEASE_BRANCH_PREFIX =
  "release-please--branches--main--components--";

// How many file paths the sticky comment lists before collapsing the rest into
// a count. Bounds an author-controlled list against GitHub's 65536-character
// comment limit.
const FILE_LIST_LIMIT = 50;

function isDocsTitle(title) {
  // Lowercase-only on purpose: this mirrors `_TITLE_RE` in
  // .github/scripts/labeling/check_pr_scope_files.py, and pr_lint.yml enforces
  // the Conventional Commit type list case-sensitively. "Docs: ..." is not a
  // valid title in this repo, so it must not earn the bypass either.
  return /^docs(?:\([^)]*\))?!?:\s/.test(title || "");
}

function isMarkdown(filename) {
  return typeof filename === "string" && filename.toLowerCase().endsWith(".md");
}

// Files this PR causes to exist as Markdown when they did not before.
//
// `status === "added"` alone is not enough: GitHub reports a `git mv
// notes.txt notes.md` as `renamed` and a copy as `copied`, both of which land
// a brand new Markdown document at a path the repo did not have. Keying on
// "the destination is Markdown and the source was not" closes that bypass
// while still ignoring a pure move of an existing `.md` file, which adds no
// new document to review.
function addedMarkdownFiles(files) {
  return files
    .filter((file) => {
      if (!isMarkdown(file.filename)) {
        return false;
      }
      if (file.status === "added" || file.status === "copied") {
        return true;
      }
      if (file.status === "renamed") {
        return !isMarkdown(file.previous_filename ?? "");
      }
      return false;
    })
    .map((file) => file.filename);
}

function escapeHtml(value) {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;");
}

function fileLines(files, limit = FILE_LIST_LIMIT) {
  const lines = files
    .slice(0, limit)
    .map((file) => `- <code>${escapeHtml(file)}</code>`);
  if (files.length > limit) {
    lines.push(`- _and ${files.length - limit} more_`);
  }
  return lines;
}

// Release PRs add a package's first CHANGELOG.md when a new component is
// onboarded, under a `release(<pkg>): ...` title that this gate would
// otherwise block — and a bot PR cannot apply the acknowledgment label to
// unblock itself, so the release pipeline would stall until a human noticed.
//
// Provenance, not the title, drives the exemption: author identity, branch
// prefix, and same-repo head must all match. An outside contributor can name
// a branch anything, but cannot push it to this repository nor author a PR as
// the bot, so no single spoofable signal carries the bypass. This mirrors
// isReleasePr in close-old-prs.js.
function isReleasePleasePr(
  { authorLogin, authorType, headRef, headRepo },
  { owner, repo },
) {
  if (authorLogin !== RELEASE_PLEASE_AUTHOR || authorType !== "Bot") {
    return false;
  }
  if (
    typeof headRef !== "string" ||
    !headRef.startsWith(RELEASE_PLEASE_BRANCH_PREFIX) ||
    headRef.length <= RELEASE_PLEASE_BRANCH_PREFIX.length
  ) {
    return false;
  }
  return (
    typeof headRepo === "string" &&
    headRepo.toLowerCase() === `${owner}/${repo}`.toLowerCase()
  );
}

// A thrown non-Error (or an octokit error without `.status`) otherwise logs as
// "undefined", which is worse than no message at all — it reads as a transient
// blip when it may be a permanent misconfiguration.
function describeError(error) {
  const status = error?.status ?? "n/a";
  const message = error?.message ?? String(error);
  return `[status=${status}] ${message}`;
}

// Matched on the marker AND the bot login: matching the marker alone lets a PR
// author pre-post a comment starting with the marker and capture the sticky
// slot. The subsequent update/delete then 403s, so the genuine explanation is
// never posted while an author-authored — and author-editable — notice sits on
// the PR looking official. Same reasoning as ripgrep_timeout_comment.yml.
// If the posting identity ever changes, update WORKFLOW_BOT_LOGIN; a missed
// match only costs one extra comment, a hijacked slot costs the explanation.
async function findStickyComment({ github, owner, repo, number }) {
  const comments = await github.paginate(github.rest.issues.listComments, {
    owner,
    repo,
    issue_number: number,
    per_page: 100,
  });
  return comments.find(
    (comment) =>
      comment.user?.login === WORKFLOW_BOT_LOGIN &&
      (comment.body ?? "").startsWith(STICKY_MARKER),
  );
}

// Called when the PR no longer needs the gate (retitled to `docs:`, or the
// Markdown file dropped). Failure here cannot turn a clean result red, but it
// does leave a stale block notice on a now-passing PR, so the warning goes out
// as core.notice: a warning inside a *successful* step is log-only, and nobody
// opens the log of a green check.
async function clearStickyComment({ github, owner, repo, number, core }) {
  try {
    const existing = await findStickyComment({ github, owner, repo, number });
    if (existing) {
      await github.rest.issues.deleteComment({
        owner,
        repo,
        comment_id: existing.id,
      });
    }
  } catch (error) {
    core.notice(
      "Could not remove the prior Markdown-file comment; a stale block notice " +
        `may still be shown on this now-passing PR: ${describeError(error)}`,
    );
  }
}

async function upsertStickyComment({ github, owner, repo, number, core, body }) {
  try {
    const existing = await findStickyComment({ github, owner, repo, number });
    if (existing) {
      // Skip a no-op edit so re-runs (a label toggle, a rebase) do not
      // re-notify every subscriber with identical content.
      if (existing.body !== body) {
        await github.rest.issues.updateComment({
          owner,
          repo,
          comment_id: existing.id,
          body,
        });
      }
    } else {
      await github.rest.issues.createComment({
        owner,
        repo,
        issue_number: number,
        body,
      });
    }
    return;
  } catch (error) {
    // 403 is not a blip. It means either the sticky slot was captured by
    // another author, or `pull-requests: write` was dropped from the workflow
    // — a permanent regression that silently degrades every future run to
    // log-only. core.error surfaces it as a Checks annotation; anything else
    // is plausibly transient (rate limit, 5xx) and stays a warning.
    const report = error?.status === 403 ? core.error : core.warning;
    report.call(
      core,
      `Could not post the Markdown-file comment: ${describeError(error)}`,
    );
  }

  // The comment was the user-facing channel and it failed, so fall back —
  // unconditionally first, because core.info cannot throw and the file list is
  // the only actionable part of this check. The job summary is nicer to read
  // but is itself failable (unwritable summary, size limit), so it comes
  // second and its failure costs nothing.
  core.info(`Markdown-file check details:\n${body}`);
  try {
    await core.summary
      .addHeading("New Markdown files require acknowledgment")
      .addRaw(body)
      .write();
  } catch (summaryError) {
    core.warning(
      `Could not write the job summary fallback: ${describeError(summaryError)}`,
    );
  }
}

function buildBody({ acknowledged, markdownFiles }) {
  const shownFiles = fileLines(markdownFiles);
  if (acknowledged) {
    return [
      STICKY_MARKER,
      `ℹ️ **New Markdown files acknowledged** via the \`${ACKNOWLEDGMENT_LABEL}\` label.`,
      "",
      ...shownFiles,
      "",
      "Remove the label to re-enable the block.",
    ].join("\n");
  }
  return [
    STICKY_MARKER,
    "⛔ **This non-docs PR adds new Markdown files.**",
    "",
    ...shownFiles,
    "",
    "Change the PR type to `docs` if it only contains documentation changes. Otherwise, review the new files and apply the acknowledgment label:",
    "",
    `\`${ACKNOWLEDGMENT_LABEL}\``,
  ].join("\n");
}

async function run({ github, context, core }) {
  const { owner, repo } = context.repo;
  const pullRequest = context.payload.pull_request;
  if (!pullRequest) {
    core.setFailed(
      "No pull_request payload; this workflow only supports pull_request_target events.",
    );
    return;
  }

  const { number } = pullRequest;

  // Every input to the decision is read live, never from the event payload.
  // The payload is a snapshot taken at delivery, and two rapid title edits
  // produce two runs against the same head SHA and the same check name.
  // `cancel-in-progress: false` lets both finish and GitHub does not promise
  // FIFO ordering, so the older event can land last: a payload still reading
  // `docs:` would clear the sticky comment and publish a green required check
  // over a PR whose title is now `feat:`. Re-running the check cannot repair
  // that, because the stale run is the most recent result. One `pulls.get`
  // removes the race for the title and, at no extra cost, for the
  // release-please provenance and changed-file total alongside it.
  let livePullRequest;
  try {
    ({ data: livePullRequest } = await github.rest.pulls.get({
      owner,
      repo,
      pull_number: number,
    }));
  } catch (error) {
    // A gate input, so it fails closed like listFiles and listLabelsOnIssue.
    // Falling back to the payload would reinstate exactly the race above, and
    // silently — the run would look like any other pass.
    core.setFailed(`Could not read the pull request: ${describeError(error)}`);
    return;
  }

  const title = livePullRequest.title;

  if (isDocsTitle(title)) {
    await clearStickyComment({ github, owner, repo, number, core });
    core.info("PR type is docs; no acknowledgment required.");
    return;
  }

  if (isReleasePleasePr(
    {
      authorLogin: livePullRequest.user?.login,
      authorType: livePullRequest.user?.type,
      headRef: livePullRequest.head?.ref,
      headRepo: livePullRequest.head?.repo?.full_name,
    },
    { owner, repo },
  )) {
    await clearStickyComment({ github, owner, repo, number, core });
    core.info(
      "Release-please PR (verified by author, branch, and head repo); " +
        "a new component's first CHANGELOG.md needs no acknowledgment.",
    );
    return;
  }

  let files;
  try {
    files = await github.paginate(github.rest.pulls.listFiles, {
      owner,
      repo,
      pull_number: number,
      per_page: 100,
    });
  } catch (error) {
    core.setFailed(`Could not list PR files: ${describeError(error)}`);
    return;
  }

  // listFiles is hard-capped by GitHub at 3000 files regardless of pagination.
  // A truncated list would hide newly added Markdown, so verify the collected
  // count against the PR's own total and fail closed otherwise. Split into two
  // checks with distinct messages — as pr_scope_file_check.yml does — because
  // a missing payload field and a truncated list are different root causes and
  // a maintainer needs to tell them apart.
  const expected = livePullRequest.changed_files;
  if (typeof expected !== "number") {
    core.setFailed(
      `PR payload missing numeric changed_files (got ${JSON.stringify(expected)}); ` +
        "cannot verify the changed-file list is complete. Failing closed.",
    );
    return;
  }
  if (files.length !== expected) {
    core.setFailed(
      `Changed-file list is incomplete (${files.length} of ${expected}); cannot ` +
        "determine whether this PR adds Markdown files. Failing closed. A PR " +
        "over GitHub's 3000-file listing cap cannot pass this check — split it.",
    );
    return;
  }

  const markdownFiles = addedMarkdownFiles(files);
  if (markdownFiles.length === 0) {
    await clearStickyComment({ github, owner, repo, number, core });
    core.info("No newly added Markdown files.");
    return;
  }

  let labels;
  try {
    // per_page: 100 is the whole story, not a page size — GitHub caps an issue
    // at 100 labels, so one request always sees every label. The REST default
    // of 30 would drop the acknowledgment label on a heavily labeled PR and
    // fail it while telling the maintainer to apply a label they can see is
    // already there.
    ({ data: labels } = await github.rest.issues.listLabelsOnIssue({
      owner,
      repo,
      issue_number: number,
      per_page: 100,
    }));
  } catch (error) {
    core.setFailed(`Could not read PR labels: ${describeError(error)}`);
    return;
  }

  const acknowledged = labels.some(
    (label) => label.name === ACKNOWLEDGMENT_LABEL,
  );
  const body = buildBody({ acknowledged, markdownFiles });

  // setFailed before the comment write: upsertStickyComment swallows its own
  // errors so the red check is the load-bearing signal and must be set first.
  if (!acknowledged) {
    core.setFailed(
      `Non-docs PR adds ${markdownFiles.length} Markdown file(s); apply ` +
        `'${ACKNOWLEDGMENT_LABEL}' to acknowledge.`,
    );
  }
  await upsertStickyComment({ github, owner, repo, number, core, body });
}

module.exports = {
  ACKNOWLEDGMENT_LABEL,
  FILE_LIST_LIMIT,
  RELEASE_PLEASE_BRANCH_PREFIX,
  STICKY_MARKER,
  WORKFLOW_BOT_LOGIN,
  addedMarkdownFiles,
  buildBody,
  fileLines,
  isDocsTitle,
  isReleasePleasePr,
  run,
};

.github/scripts/checks/readme-gate.js:
// Enforcement half of the project README gate. See
// .github/workflows/project_readme_check.yml for the policy this implements
// and .github/scripts/checks/check_project_readmes.py for the detector.
//
// This logic lives in a module rather than inline in the workflow's
// `github-script` blocks so it can be unit-tested against a fake octokit
// (.github/scripts/tests/checks/readme-gate.test.js). Inline workflow JS is
// only reachable by string-matching the YAML, which cannot tell a working
// gate from one whose `core.setFailed` was changed to `core.warning` — the
// exact mutation that silently disables the check. Same pattern as
// .github/scripts/labeling/close-old-prs.js.

const STICKY_MARKER = '<!-- project-readme-check -->';
const ACKNOWLEDGMENT_LABEL = 'ci:ack-readme';

// `GET /repos/{owner}/{repo}/pulls/{number}/files` is hard-capped at 3000
// files no matter how the caller paginates, while `pull_request.changed_files`
// reports the true total. Past the cap the two legitimately disagree, so the
// completeness check below cannot distinguish "truncated by the documented
// cap" from "pagination dropped pages". They are separated here because they
// need opposite handling: a truncated-by-cap list is a known API limit a
// maintainer can acknowledge past, while a short read of any other size is an
// unexplained failure that must stay hard-blocked.
const LISTFILES_CAP = 3000;

/**
 * Collect every path a PR touches, including the pre-rename path.
 *
 * `previous_filename` matters because renaming a protected README away is
 * itself an edit to that README — without it, `git mv README.md README.rst`
 * is a one-line bypass of the whole gate.
 *
 * Fails closed rather than guessing: an incomplete file list could hide a
 * README edit, so a short read blocks instead of passing.
 *
 * @returns {Promise<{paths: string[], truncated: boolean} | null>} `null` when
 *   the run has been failed and the caller should stop.
 */
async function collectChangedPaths({ github, context, core }) {
  const pr = context.payload.pull_request;
  if (!pr || typeof pr.changed_files !== 'number') {
    // Without a reported total there is nothing to check completeness
    // against, so the list could be silently short. Fail closed.
    core.setFailed(
      'PR payload is missing a numeric changed_files total; failing closed.',
    );
    return null;
  }

  const files = await github.paginate(github.rest.pulls.listFiles, {
    ...context.repo,
    pull_number: pr.number,
    per_page: 100,
  });

  let truncated = false;
  if (files.length !== pr.changed_files) {
    if (files.length >= LISTFILES_CAP && pr.changed_files > LISTFILES_CAP) {
      // Documented API cap, not a fault. Report it as unknown-but-blocking so
      // `ci:ack-readme` can still clear the PR; hard-failing here would
      // run before both bypasses and leave the PR permanently unmergeable.
      truncated = true;
      core.warning(
        `PR changes ${pr.changed_files} files; the API caps the list at ` +
          `${LISTFILES_CAP}, so protected README edits cannot be detected. ` +
          `Apply the '${ACKNOWLEDGMENT_LABEL}' label to proceed.`,
      );
    } else {
      core.setFailed(
        `Changed-file list is incomplete (${files.length} of ` +
          `${pr.changed_files}). Either the PR was updated mid-run or the ` +
          'listing was truncated; failing closed. Re-run if the PR changed.',
      );
      return null;
    }
  }

  const paths = new Set();
  for (const file of files) {
    paths.add(file.filename);
    if (file.previous_filename) paths.add(file.previous_filename);
  }
  return { paths: [...paths], truncated };
}

/** Whether the PR originates from a fork, where GITHUB_TOKEN is read-only. */
function isForkPr(context) {
  const headRepo = context.payload.pull_request.head?.repo;
  if (!headRepo || typeof headRepo.full_name !== 'string') return true;
  return headRepo.full_name !== `${context.repo.owner}/${context.repo.repo}`;
}

async function findSticky({ github, context }) {
  const comments = await github.paginate(github.rest.issues.listComments, {
    ...context.repo,
    issue_number: context.payload.pull_request.number,
    per_page: 100,
  });
  return comments.find(
    comment => comment.body && comment.body.startsWith(STICKY_MARKER),
  );
}

/**
 * Publish the gate's verdict to the PR, or to the job summary on forks.
 *
 * Fork PRs get a read-only GITHUB_TOKEN regardless of this job's
 * `permissions:` block, so every write 403s. Rather than create a comment
 * that can never be cleaned up later — leaving a stale block notice on a PR
 * that has since gone green — forks skip commenting entirely and get the job
 * summary as their only channel. The check's own failure message carries the
 * same information into the Checks UI either way.
 */
async function publish({ github, context, core, body }) {
  if (isForkPr(context)) {
    try {
      await core.summary.addHeading('Project README check').addRaw(body).write();
    } catch (error) {
      core.warning(`Could not write README gate job summary: ${error.message}`);
    }
    return;
  }
  try {
    const existing = await findSticky({ github, context });
    if (existing && existing.body !== body) {
      await github.rest.issues.updateComment({
        ...context.repo,
        comment_id: existing.id,
        body,
      });
    } else if (!existing) {
      await github.rest.issues.createComment({
        ...context.repo,
        issue_number: context.payload.pull_request.number,
        body,
      });
    }
  } catch (error) {
    core.warning(`Could not post README gate comment: ${error.message}`);
    try {
      await core.summary.addHeading('Project README check').addRaw(body).write();
    } catch (summaryError) {
      core.warning(
        `Could not write README gate job summary: ${summaryError.message}`,
      );
    }
  }
}

/** Remove the sticky note once a PR no longer trips the gate. */
async function clearSticky({ github, context, core }) {
  if (isForkPr(context)) return;
  try {
    const existing = await findSticky({ github, context });
    if (existing) {
      await github.rest.issues.deleteComment({
        ...context.repo,
        comment_id: existing.id,
      });
    }
  } catch (error) {
    core.warning(`Could not remove stale README gate comment: ${error.message}`);
  }
}

/**
 * Apply the gate.
 *
 * @param {object} args.result Parsed detector output: `{pr_type, readmes}`.
 * @param {boolean} args.truncated Whether the changed-file list hit the API
 *   cap, making `result.readmes` unreliable.
 */
async function enforce({ github, context, core, result, truncated = false }) {
  if (
    !result ||
    !Array.isArray(result.readmes) ||
    result.readmes.some(path => typeof path !== 'string')
  ) {
    core.setFailed(
      `README detector returned an invalid result: ${JSON.stringify(result)}`,
    );
    return;
  }

  if (!truncated && result.readmes.length === 0) {
    await clearSticky({ github, context, core });
    return;
  }

  // Read labels from the API, not the event payload: a re-run replays the
  // original payload, so a label applied after the first run would be
  // invisible and the PR would stay red with no way to clear it. Paginated
  // because a wide PR in this repo routinely carries 20+ auto-applied labels
  // (see .github/scripts/labeling/pr-labeler-config.json) and the unpaginated
  // default of 30 would drop the acknowledgment label off page one.
  let labels;
  try {
    labels = await github.paginate(github.rest.issues.listLabelsOnIssue, {
      ...context.repo,
      issue_number: context.payload.pull_request.number,
      per_page: 100,
    });
  } catch (error) {
    core.setFailed(`Could not read live PR labels; failing closed: ${error.message}`);
    return;
  }
  const acknowledged = labels.some(label => label.name === ACKNOWLEDGMENT_LABEL);

  const detail = truncated
    ? `This PR changes more than ${LISTFILES_CAP} files, so the API cannot ` +
      'report a complete file list and protected README edits cannot be ruled out.'
    : result.readmes.map(path => `- \`${path}\``).join('\n');

  if (acknowledged) {
    await publish({
      github,
      context,
      core,
      body: [
        STICKY_MARKER,
        `ℹ️ **Project README edits acknowledged** via the \`${ACKNOWLEDGMENT_LABEL}\` label.`,
        '',
        detail,
        '',
        'Remove the label to re-enable the block.',
      ].join('\n'),
    });
    return;
  }

  const body = [
    STICKY_MARKER,
    truncated
      ? '⛔ **This PR is too large to check for project README edits.**'
      : '⛔ **This PR edits a project README but is not a `docs` PR.**',
    '',
    detail,
    '',
    truncated
      ? `Apply the \`${ACKNOWLEDGMENT_LABEL}\` label to confirm any landing-page changes are intentional.`
      : `Change the PR title type to \`docs\` if the PR is documentation-only. Otherwise, apply the \`${ACKNOWLEDGMENT_LABEL}\` label to confirm these landing-page changes are intentional.`,
  ].join('\n');

  // Fail before publishing: `publish` swallows API errors by design, and the
  // gate's verdict must not depend on whether the comment landed.
  core.setFailed(
    truncated
      ? `PR exceeds the ${LISTFILES_CAP}-file listing cap; ` +
          `requires the '${ACKNOWLEDGMENT_LABEL}' label.`
      : `Project README edits require a docs PR or the ` +
          `'${ACKNOWLEDGMENT_LABEL}' label: ${result.readmes.join(', ')}`,
  );
  await publish({ github, context, core, body });
}

module.exports = {
  collectChangedPaths,
  enforce,
  isForkPr,
  STICKY_MARKER,
  ACKNOWLEDGMENT_LABEL,
  LISTFILES_CAP,
};

.github/scripts/evals/aggregate_unified_:
"""Compare Unified Eval results across branches and active agent configs."""

from __future__ import annotations

import argparse
import json
import math
import os
from itertools import combinations
from pathlib import Path
from typing import NamedTuple, cast

import aggregate_unified as unified
from unified_types import LeafKey


METRICS = ("pass_at_k", "avg_at_k")


class SubjectKey(NamedTuple):
    """Identity of one branch, model, and active agent config."""

    branch: str
    model: str
    config: str


class LeafData(NamedTuple):
    """Validated aggregate leaf plus its per-task pass results."""

    leaf: dict
    tasks: dict[str, float]
    has_tasks: bool


def _json_list(raw: str, label: str) -> list[object]:
    """Decode a JSON list argument with a consistent error."""
    value = json.loads(raw)
    if not isinstance(value, list):
        msg = f"{label} must be a JSON list"
        raise ValueError(msg)
    return cast(list[object], value)


def parse_sources(raw: str) -> list[dict[str, str]]:
    """Parse ordered branch and immutable-SHA identities from prep output."""
    sources: list[dict[str, str]] = []
    seen: set[str] = set()
    for value in _json_list(raw, "--sources-json"):
        if not isinstance(value, dict):
            msg = "--sources-json entries must be objects"
            raise ValueError(msg)
        source = cast(dict[str, object], value)
        branch = source.get("branch")
        sha = source.get("sha")
        if not isinstance(branch, str) or not branch or not isinstance(sha, str):
            msg = "--sources-json entries require a branch and string sha"
            raise ValueError(msg)
        if branch in seen:
            msg = f"duplicate source branch: {branch!r}"
            raise ValueError(msg)
        seen.add(branch)
        sources.append({"branch": branch, "sha": sha})
    if not sources:
        msg = "--sources-json must contain at least one source"
        raise ValueError(msg)
    return sources


def parse_expected_leaves(raw: str) -> list[dict[str, str]]:
    """Parse the authoritative branch/model/config/category allocation table."""
    fields = {"model", "branch", "source_sha", "config", "category"}
    leaves: list[dict[str, str]] = []
    seen: set[LeafKey] = set()
    for value in _json_list(raw, "--expected-leaves-json"):
        if not isinstance(value, dict) or not fields <= set(value):
            msg = (
                "--expected-leaves-json entries require model, branch, "
                "source_sha, config, and category"
            )
            raise ValueError(msg)
        raw_leaf = cast(dict[str, object], value)
        leaf = {field: raw_leaf[field] for field in fields}
        if not all(isinstance(item, str) for item in leaf.values()):
            msg = "--expected-leaves-json fields must be strings"
            raise ValueError(msg)
        typed = cast(dict[str, str], leaf)
        key = LeafKey(
            typed["model"], typed["branch"], typed["config"], typed["category"]
        )
        if key in seen:
            msg = f"duplicate expected leaf: {key!r}"
            raise ValueError(msg)
        seen.add(key)
        leaves.append(typed)
    if not leaves:
        msg = "--expected-leaves-json must contain at least one leaf"
        raise ValueError(msg)
    return leaves


def parse_categories(raw: str) -> list[str]:
    """Parse the ordered category list from prep output."""
    values = _json_list(raw, "--categories-json")
    if not all(isinstance(value, str) and value for value in values):
        msg = "--categories-json must contain non-empty strings"
        raise ValueError(msg)
    return list(dict.fromkeys(cast(list[str], values)))


def _read_tasks(path: Path, rollouts: int) -> tuple[dict[str, float], bool]:
    """Read per-task scores; a missing file is incomplete, not malformed.

    Graded categories emit `mean_reward@K` alongside `pass@K` and are preferred when
    present: their per-task `pass@K` is 0.0 for every task (nothing scores a perfect
    1.0), so ranking on it would make every task a tie and erase the comparison. The
    key's presence is the signal, so no scoring mode has to be threaded in here.
    """
    if not path.is_file():
        return {}, False
    tasks: dict[str, float] = {}
    pass_field = f"pass@{rollouts}"
    graded_field = f"mean_reward@{rollouts}"
    for number, line in enumerate(
        path.read_text(encoding="utf-8").splitlines(), start=1
    ):
        if not line.strip():
            continue
        try:
            value: object = json.loads(line)
        except ValueError as exc:
            msg = f"invalid per-task JSON at {path}:{number}"
            raise ValueError(msg) from exc
        if not isinstance(value, dict):
            msg = f"per-task row must be an object at {path}:{number}"
            raise ValueError(msg)
        row = cast(dict[str, object], value)
        task = row.get("task")
        field = graded_field if graded_field in row else pass_field
        score = row.get(field)
        if not isinstance(task, str) or not task:
            msg = f"per-task row requires a task at {path}:{number}"
            raise ValueError(msg)
        if task in tasks:
            msg = f"duplicate task {task!r} in {path}"
            raise ValueError(msg)
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            msg = f"{field} must be numeric at {path}:{number}"
            raise ValueError(msg)
        numeric = float(score)
        if not math.isfinite(numeric) or not 0 <= numeric <= 1:
            msg = f"{field} must be in [0, 1] at {path}:{number}"
            raise ValueError(msg)
        tasks[task] = numeric
    return tasks, True


def _actual_leaves(
    root: Path, rollouts: int
) -> tuple[dict[LeafKey, LeafData], list[dict[str, object]]]:
    """Index validated result leaves by their complete evaluation identity."""
    output: dict[LeafKey, LeafData] = {}
    issues = unified.read_download_issues(root, "comparison")
    quarantined: set[LeafKey] = set()
    for record in unified.discover_leaf_records(
        root, expected_rollouts=rollouts, issues=issues
    ):
        leaf = record.leaf
        key = LeafKey(
            cast(str, leaf["model"]),
            cast(str, leaf["branch"]),
            cast(str, leaf["config"]),
            cast(str, leaf["category"]),
        )
        issues.extend(cast(list[dict[str, object]], leaf.get("issues", [])))
        if key in quarantined:
            continue
        if key in output:
            output.pop(key)
            quarantined.add(key)
            msg = f"duplicate actual leaf: {key!r}; all copies were quarantined"
            print(f"::warning::{msg}")
            issues.append(
                unified.analysis_issue(
                    "comparison",
                    "duplicate_leaf",
                    msg,
                    leaf={
                        "model": key.model,
                        "branch": key.branch,
                        "config": key.config,
                        "category": key.category,
                    },
                )
            )
            continue
        task_path = record.path / "per_task.jsonl"
        try:
            tasks, has_tasks = _read_tasks(task_path, rollouts)
        except (OSError, UnicodeError, ValueError) as exc:
            tasks, has_tasks = {}, False
            msg = f"Could not trust task-level results: {exc}"
            print(f"::warning::{msg}")
            issues.append(
                unified.analysis_issue(
                    "comparison",
                    "malformed_per_task_data",
                    msg,
                    leaf={
                        "model": key.model,
                        "branch": key.branch,
                        "config": key.config,
                        "category": key.category,
                    },
                    path=task_path.relative_to(root),
                )
            )
        if not has_tasks and not any(
            issue.get("path") == str(task_path.relative_to(root)) for issue in issues
        ):
            msg = f"Task-level result file is missing: {task_path.relative_to(root)}"
            issues.append(
                unified.analysis_issue(
                    "comparison",
                    "missing_per_task_data",
                    msg,
                    leaf={
                        "model": key.model,
                        "branch": key.branch,
                        "config": key.config,
                        "category": key.category,
                    },
                    path=task_path.relative_to(root),
                )
            )
        output[key] = LeafData(leaf, tasks, has_tasks)
    return output, issues


def _source_index(sources: list[dict[str, str]]) -> dict[str, str]:
    """Return branch-to-SHA lookup preserving validation in one place."""
    return {source["branch"]: source["sha"] for source in sources}


def _allocation(
    expected_leaves: list[dict[str, str]], sources: list[dict[str, str]]
) -> tuple[list[SubjectKey], dict[SubjectKey, list[str]]]:
    """Build ordered subjects and their assigned categories from expected leaves."""
    source_shas = _source_index(sources)
    order: list[SubjectKey] = []
    categories: dict[SubjectKey, list[str]] = {}
    for leaf in expected_leaves:
        branch = leaf["branch"]
        if branch not in source_shas:
            msg = f"expected leaf references unknown source branch {branch!r}"
            raise ValueError(msg)
        if leaf["source_sha"] != source_shas[branch]:
            msg = f"expected source SHA mismatch for branch {branch!r}"
            raise ValueError(msg)
        key = SubjectKey(branch, leaf["model"], leaf["config"])
        if key not in categories:
            order.append(key)
            categories[key] = []
        categories[key].append(leaf["category"])
    return order, categories


def _subject_identity(subject: dict[str, object]) -> dict[str, str]:
    """Return the stable identity fields used in comparison records."""
    return {
        "branch": cast(str, subject["branch"]),
        "source_sha": cast(str, subject["source_sha"]),
        "model": cast(str, subject["model"]),
        "config": cast(str, subject["config"]),
    }


def _build_subjects(
    actual: dict[LeafKey, LeafData],
    expected_leaves: list[dict[str, str]],
    sources: list[dict[str, str]],
) -> tuple[
    list[dict[str, object]],
    dict[SubjectKey, dict[str, dict[str, float]]],
    dict[SubjectKey, dict[str, bool]],
]:
    """Materialize scorecard subjects plus per-category task data."""
    order, allocation = _allocation(expected_leaves, sources)
    expected_by_subject: dict[SubjectKey, list[dict[str, str]]] = {
        key: [] for key in order
    }
    for leaf in expected_leaves:
        key = SubjectKey(leaf["branch"], leaf["model"], leaf["config"])
        expected_by_subject[key].append(leaf)

    source_shas = _source_index(sources)
    subjects: list[dict[str, object]] = []
    tasks_by_subject: dict[SubjectKey, dict[str, dict[str, float]]] = {}
    task_files_by_subject: dict[SubjectKey, dict[str, bool]] = {}
    for key in order:
        leaf_data: list[dict] = []
        task_data: dict[str, dict[str, float]] = {}
        task_files: dict[str, bool] = {}
        for category in allocation[key]:
            leaf_key = LeafKey(key.model, key.branch, key.config, category)
            record = actual.get(leaf_key)
            if record is None:
                task_data[category] = {}
                task_files[category] = False
                continue
            actual_sha = cast(str, record.leaf.get("source_sha", ""))
            if actual_sha != source_shas[key.branch]:
                msg = (
                    f"actual source SHA mismatch for {key.branch!r}, "
                    f"{key.model!r}, {key.config!r}, {category!r}"
                )
                raise ValueError(msg)
            leaf_data.append(record.leaf)
            task_data[category] = record.tasks
            task_files[category] = record.has_tasks

        combined = unified.combine(
            leaf_data,
            cast(list[LeafKey | dict[str, str]], expected_by_subject[key]),
            allocation[key],
        )
        row = cast(dict[str, object], combined["rows"][0])
        subjects.append(
            {
                **row,
                "assigned_categories": allocation[key],
                "task_data_complete": all(
                    task_files.get(category, False) for category in allocation[key]
                ),
            }
        )
        tasks_by_subject[key] = task_data
        task_files_by_subject[key] = task_files
    return subjects, tasks_by_subject, task_files_by_subject


def _metric_value(
    subject: dict[str, object], category: str, metric: str
) -> float | None:
    categories = cast(dict[str, dict[str, object]], subject["categories"])
    value = categories.get(category, {}).get(metric)
    return (
        float(value)
        if isinstance(value, (int, float)) and not isinstance(value, bool)
        else None
    )


def _aggregate_metric(
    subject: dict[str, object], categories: list[str], metric: str, *, micro: bool
) -> float | None:
    """Compute a macro or task-weighted metric over exactly the shared categories."""
    blocks = cast(dict[str, dict[str, object]], subject["categories"])
    values: list[tuple[float, int]] = []
    for category in categories:
        block = blocks.get(category)
        if block is None:
            return None
        value = block.get(metric)
        tasks = block.get("tasks")
        if (
            isinstance(value, bool)
            or not isinstance(value, (int, float))
            or isinstance(tasks, bool)
            or not isinstance(tasks, int)
            or tasks < 1
        ):
            return None
        values.append((float(value), tasks))
    if not values:
        return None
    if micro:
        total = sum(tasks for _value, tasks in values)
        return sum(value * tasks for value, tasks in values) / total
    return sum(value for value, _tasks in values) / len(values)


def _metric_delta(
    baseline: float | None, candidate: float | None
) -> dict[str, float | None]:
    """Return both absolute values and candidate-minus-baseline delta."""
    return {
        "baseline": baseline,
        "candidate": candidate,
        "delta": (
            candidate - baseline
            if baseline is not None and candidate is not None
            else None
        ),
    }


def _comparison_metrics(
    baseline: dict[str, object],
    candidate: dict[str, object],
    categories: list[str],
) -> dict[str, object]:
    """Compute category, macro, and micro metrics over the shared allocation."""
    category_metrics = {
        category: {
            metric: _metric_delta(
                _metric_value(baseline, category, metric),
                _metric_value(candidate, category, metric),
            )
            for metric in METRICS
        }
        for category in categories
    }
    return {
        "categories": category_metrics,
        "macro": {
            metric: _metric_delta(
                _aggregate_metric(baseline, categories, metric, micro=False),
                _aggregate_metric(candidate, categories, metric, micro=False),
            )
            for metric in METRICS
        },
        "micro": {
            metric: _metric_delta(
                _aggregate_metric(baseline, categories, metric, micro=True),
                _aggregate_metric(candidate, categories, metric, micro=True),
            )
            for metric in METRICS
        },
    }


def _task_outcomes(
    baseline: dict[str, dict[str, float]],
    candidate: dict[str, dict[str, float]],
    categories: list[str],
) -> dict[str, dict[str, int]]:
    """Count candidate wins, losses, ties, and unmatched tasks by category."""
    output: dict[str, dict[str, int]] = {}
    for category in categories:
        first = baseline.get(category, {})
        second = candidate.get(category, {})
        counts = {"wins": 0, "losses": 0, "ties": 0, "missing": 0}
        for task in sorted(set(first) | set(second)):
            if task not in first or task not in second:
                counts["missing"] += 1
            elif second[task] > first[task]:
                counts["wins"] += 1
            elif second[task] < first[task]:
                counts["losses"] += 1
            else:
                counts["ties"] += 1
        output[category] = counts
    return output


def _not_comparable(
    kind: str,
    baseline: dict[str, str],
    candidate: dict[str, str],
    reason: str,
) -> dict[str, object]:
    """Describe an intentionally omitted pair without treating it as an error."""
    return {
        "kind": kind,
        "baseline": baseline,
        "candidate": candidate,
        "reason": reason,
    }


def _make_comparison(
    kind: str,
    baseline: dict[str, object],
    candidate: dict[str, object],
    baseline_tasks: dict[str, dict[str, float]],
    candidate_tasks: dict[str, dict[str, float]],
    baseline_task_files: dict[str, bool],
    candidate_task_files: dict[str, bool],
    category_order: list[str],
) -> tuple[dict[str, object] | None, dict[str, object] | None]:
    """Build one fair comparison or a no-shared-category audit record."""
    baseline_categories = set(cast(list[str], baseline["assigned_categories"]))
    candidate_categories = set(cast(list[str], candidate["assigned_categories"]))
    shared = [
        category
        for category in category_order
        if category in baseline_categories and category in candidate_categories
    ]
    first_identity = _subject_identity(baseline)
    second_identity = _subject_identity(candidate)
    if not shared:
        return None, _not_comparable(
            kind, first_identity, second_identity, "no_shared_categories"
        )
    outcomes = _task_outcomes(baseline_tasks, candidate_tasks, shared)
    incomplete = (
        bool(baseline["incomplete"])
        or bool(candidate["incomplete"])
        or any(not baseline_task_files.get(category, False) for category in shared)
        or any(not candidate_task_files.get(category, False) for category in shared)
        or any(counts["missing"] for counts in outcomes.values())
    )
    return (
        {
            "kind": kind,
            "baseline": first_identity,
            "candidate": second_identity,
            "shared_categories": shared,
            "status": "incomplete" if incomplete else "complete",
            "metrics": _comparison_metrics(baseline, candidate, shared),
            "task_outcomes": outcomes,
        },
        None,
    )


def compare(
    root: Path,
    *,
    sources: list[dict[str, str]],
    expected_leaves: list[dict[str, str]],
    categories: list[str],
    rollouts: int,
) -> dict[str, object]:
    """Build every controlled branch and config comparison from the run allocation."""
    actual, issues = _actual_leaves(root, rollouts)
    subjects, tasks, task_files = _build_subjects(actual, expected_leaves, sources)
    for subject in subjects:
        missing = cast(list[str], subject["missing_categories"])
        if not missing:
            continue
        identity = _subject_identity(subject)
        issues.append(
            unified.analysis_issue(
                "comparison",
                "missing_leaf_summaries",
                f"Missing leaf summaries for categories: {', '.join(missing)}",
                leaf={
                    "model": identity["model"],
                    "branch": identity["branch"],
                    "config": identity["config"],
                    "category": ",".join(missing),
                },
            )
        )
    by_key = {
        SubjectKey(
            cast(str, subject["branch"]),
            cast(str, subject["model"]),
            cast(str, subject["config"]),
        ): subject
        for subject in subjects
    }
    model_order = list(
        dict.fromkeys(cast(str, subject["model"]) for subject in subjects)
    )
    comparisons_out: list[dict[str, object]] = []
    not_comparable: list[dict[str, object]] = []

    # Change only the branch: model and config remain fixed.
    for first_source, second_source in combinations(sources, 2):
        first_branch = first_source["branch"]
        second_branch = second_source["branch"]
        for model in model_order:
            configs = list(
                dict.fromkeys(
                    key.config
                    for key in by_key
                    if key.model == model
                    and key.branch in {first_branch, second_branch}
                )
            )
            for config in configs:
                first_key = SubjectKey(first_branch, model, config)
                second_key = SubjectKey(second_branch, model, config)
                if first_key not in by_key or second_key not in by_key:
                    baseline = {
                        "branch": first_branch,
                        "source_sha": first_source["sha"],
                        "model": model,
                        "config": config,
                    }
                    candidate = {
                        "branch": second_branch,
                        "source_sha": second_source["sha"],
                        "model": model,
                        "config": config,
                    }
                    not_comparable.append(
                        _not_comparable(
                            "cross_branch",
                            baseline,
                            candidate,
                            "config_not_active_on_both_branches",
                        )
                    )
                    continue
                comparison, omitted = _make_comparison(
                    "cross_branch",
                    by_key[first_key],
                    by_key[second_key],
                    tasks[first_key],
                    tasks[second_key],
                    task_files[first_key],
                    task_files[second_key],
                    categories,
                )
                if comparison is not None:
                    comparisons_out.append(comparison)
                if omitted is not None:
                    not_comparable.append(omitted)

    # Change only the config: branch and model remain fixed.
    for source in sources:
        branch = source["branch"]
        for model in model_order:
            keys = [
                key for key in by_key if key.branch == branch and key.model == model
            ]
            for first_key, second_key in combinations(keys, 2):
                comparison, omitted = _make_comparison(
                    "within_branch",
                    by_key[first_key],
                    by_key[second_key],
                    tasks[first_key],
                    tasks[second_key],
                    task_files[first_key],
                    task_files[second_key],
                    categories,
                )
                if comparison is not None:
                    comparisons_out.append(comparison)
                if omitted is not None:
                    not_comparable.append(omitted)

    for comparison in comparisons_out:
        outcomes = cast(dict[str, dict[str, int]], comparison["task_outcomes"])
        missing = {
            category: counts["missing"]
            for category, counts in outcomes.items()
            if counts["missing"]
        }
        if missing:
            baseline = cast(dict[str, str], comparison["baseline"])
            candidate = cast(dict[str, str], comparison["candidate"])
            issues.append(
                unified.analysis_issue(
                    "comparison",
                    "task_coverage_mismatch",
                    f"Task coverage differs for {baseline['branch']}/{baseline['config']} "
                    f"and {candidate['branch']}/{candidate['config']}: {missing}",
                )
            )

    return {
        "schema_version": 1,
        "rollouts_per_task": rollouts,
        "sources": sources,
        "subjects": subjects,
        "comparisons": comparisons_out,
        "not_comparable": not_comparable,
        "issues": issues,
    }


def _fmt(value: float | None, *, signed: bool = False) -> str:
    """Format one comparison metric for Markdown."""
    if value is None:
        return "—"
    return f"{value:+.3f}" if signed else f"{value:.3f}"


def _md(value: object) -> str:
    """Escape a scalar for a Markdown table cell."""
    return (
        str(value)
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace("|", "\\|")
        .replace("\r", " ")
        .replace("\n", " ")
    )


def _identity_label(identity: dict[str, str]) -> str:
    """Render a compact branch/config identity."""
    return f"{identity['branch']}/{identity['config']}"


def render_markdown(result: dict[str, object]) -> str:
    """Render absolute scores, controlled deltas, and per-task outcomes."""
    sources = cast(list[dict[str, str]], result["sources"])
    subjects = cast(list[dict[str, object]], result["subjects"])
    comparisons_out = cast(list[dict[str, object]], result["comparisons"])
    omitted = cast(list[dict[str, object]], result["not_comparable"])
    lines = [
        "## Unified evals — deterministic comparisons",
        "",
        "### Sources",
        "",
        "| Branch | Commit |",
        "|---|---|",
    ]
    for source in sources:
        sha = source["sha"] or "workflow checkout"
        lines.append(f"| {_md(source['branch'])} | `{_md(sha)}` |")

    lines.extend(
        [
            "",
            "### Active subjects",
            "",
            "| Branch | Model | Config | Assigned categories | Macro pass/avg | Micro pass/avg | Status |",
            "|---|---|---|---|---:|---:|---|",
        ]
    )
    for subject in subjects:
        macro = cast(dict[str, float | None], subject["macro"])
        micro = cast(dict[str, float | None], subject["micro"])
        status = "incomplete" if subject["incomplete"] else "complete"
        assigned = ", ".join(cast(list[str], subject["assigned_categories"]))
        lines.append(
            f"| {_md(subject['branch'])} | {_md(subject['model'])} | "
            f"{_md(subject['config'])} | {_md(assigned)} | "
            f"{_fmt(macro['pass_at_k'])}/{_fmt(macro['avg_at_k'])} | "
            f"{_fmt(micro['pass_at_k'])}/{_fmt(micro['avg_at_k'])} | {status} |"
        )

    lines.extend(
        [
            "",
            "### Pairwise deltas",
            "",
            "Delta is candidate minus baseline. Different models are never compared.",
            "",
            "| Kind | Comparison | Model | Scope | Δ pass@k | Δ avg@k | Status |",
            "|---|---|---|---|---:|---:|---|",
        ]
    )
    for comparison in comparisons_out:
        baseline = cast(dict[str, str], comparison["baseline"])
        candidate = cast(dict[str, str], comparison["candidate"])
        metrics = cast(dict[str, object], comparison["metrics"])
        category_metrics = cast(
            dict[str, dict[str, dict[str, float | None]]], metrics["categories"]
        )
        scopes = [
            *(
                (category, category_metrics[category])
                for category in cast(list[str], comparison["shared_categories"])
            ),
            ("macro", cast(dict[str, dict[str, float | None]], metrics["macro"])),
            ("micro", cast(dict[str, dict[str, float | None]], metrics["micro"])),
        ]
        label = f"{_identity_label(baseline)} → {_identity_label(candidate)}"
        for scope, values in scopes:
            lines.append(
                f"| {_md(comparison['kind'])} | {_md(label)} | "
                f"{_md(baseline['model'])} | {_md(scope)} | "
                f"{_fmt(values['pass_at_k']['delta'], signed=True)} | "
                f"{_fmt(values['avg_at_k']['delta'], signed=True)} | "
                f"{_md(comparison['status'])} |"
            )

    lines.extend(
        [
            "",
            "### Per-task outcomes",
            "",
            "Wins and losses are from the candidate's perspective.",
            "",
            "| Kind | Comparison | Model | Category | Wins | Losses | Ties | Missing |",
            "|---|---|---|---|---:|---:|---:|---:|",
        ]
    )
    for comparison in comparisons_out:
        baseline = cast(dict[str, str], comparison["baseline"])
        candidate = cast(dict[str, str], comparison["candidate"])
        outcomes = cast(dict[str, dict[str, int]], comparison["task_outcomes"])
        label = f"{_identity_label(baseline)} → {_identity_label(candidate)}"
        for category, counts in outcomes.items():
            lines.append(
                f"| {_md(comparison['kind'])} | {_md(label)} | "
                f"{_md(baseline['model'])} | {_md(category)} | {counts['wins']} | "
                f"{counts['losses']} | {counts['ties']} | {counts['missing']} |"
            )

    if omitted:
        lines.extend(
            [
                "",
                "### Not comparable",
                "",
                "These pairs were intentionally omitted; they are not evaluation failures.",
                "",
                "| Kind | Pair | Model | Reason |",
                "|---|---|---|---|",
            ]
        )
        for item in omitted:
            baseline = cast(dict[str, str], item["baseline"])
            candidate = cast(dict[str, str], item["candidate"])
            label = f"{_identity_label(baseline)} ↔ {_identity_label(candidate)}"
            lines.append(
                f"| {_md(item['kind'])} | {_md(label)} | {_md(baseline['model'])} | "
                f"{_md(item['reason'])} |"
            )
    issues = cast(list[dict[str, object]], result.get("issues", []))
    if issues:
        lines.extend(["", "## Analysis warnings", ""])
        for issue in issues:
            lines.append(f"- `{_md(issue['code'])}`: {_md(issue['message'])}")
    return "\n".join(lines) + "\n"


def write_outputs(result: dict[str, object], out_dir: Path) -> bool:
    """Write comparison outputs, including diagnostic-only reports."""
    if not result["comparisons"]:
        print("No comparable Unified Eval subjects; writing a diagnostic report.")
    out_dir.mkdir(parents=True, exist_ok=True)
    (out_dir / "comparison_summary.json").write_text(
        json.dumps(result, indent=2) + "\n", encoding="utf-8"
    )
    markdown = render_markdown(result)
    (out_dir / "comparison.md").write_text(markdown, encoding="utf-8")
    if summary := os.environ.get("GITHUB_STEP_SUMMARY"):
        with open(summary, "a", encoding="utf-8") as handle:
            handle.write("\n" + markdown)
    return True


def _diagnostic_result(rollouts: int, exc: BaseException) -> dict[str, object]:
    """Build a comparison report when allocation or input parsing cannot proceed."""
    return {
        "schema_version": 1,
        "rollouts_per_task": rollouts,
        "sources": [],
        "subjects": [],
        "comparisons": [],
        "not_comparable": [],
        "issues": [
            unified.analysis_issue(
                "comparison",
                "comparison_input_error",
                str(exc),
            )
        ],
    }


def main(argv: list[str] | None = None) -> int:
    """Run deterministic comparison reporting for one Unified Evals dispatch."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("root", type=Path)
    parser.add_argument("--sources-json", required=True)
    parser.add_argument("--expected-leaves-json", required=True)
    parser.add_argument("--categories-json", required=True)
    parser.add_argument("--rollouts", type=int, required=True)
    parser.add_argument("--out-dir", type=Path, required=True)
    args = parser.parse_args(argv)
    if args.rollouts < 1:
        parser.error("--rollouts must be >= 1")
    try:
        result = compare(
            args.root,
            sources=parse_sources(args.sources_json),
            expected_leaves=parse_expected_leaves(args.expected_leaves_json),
            categories=parse_categories(args.categories_json),
            rollouts=args.rollouts,
        )
    except (OSError, UnicodeError, ValueError) as exc:
        print(f"::warning::Comparison could not use its inputs: {exc}")
        result = _diagnostic_result(args.rollouts, exc)
    try:
        write_outputs(result, args.out_dir)
    except (OSError, UnicodeError) as exc:
        print(f"::warning::Could not write comparison outputs: {exc}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

