"""Contracts for the release workflow's Python matrix."""

from __future__ import annotations

import json
import tomllib
from pathlib import Path

import pytest
import yaml
from resolve_python_matrix import (
    SUPPORTED_PYTHON_VERSIONS,
    resolve_from_pyproject,
    resolve_python_versions,
)


ROOT = Path(__file__).resolve().parents[4]
CI_WORKFLOW = ROOT / ".github/workflows/ci.yml"
RELEASE_WORKFLOW = ROOT / ".github/workflows/release.yml"
TEST_WORKFLOW_REF = "./.github/workflows/_test.yml"


def _ci_test_jobs() -> dict[str, dict]:
    """Return every CI job using the reusable test workflow."""
    workflow = yaml.safe_load(CI_WORKFLOW.read_text())
    return {
        name: job
        for name, job in workflow["jobs"].items()
        if job.get("uses") == TEST_WORKFLOW_REF
    }


def test_ci_matrices_match_requires_python() -> None:
    """Keep PR and release test matrices aligned."""
    for name, job in _ci_test_jobs().items():
        working_directory = job["with"]["working-directory"]
        pyproject = ROOT / working_directory / "pyproject.toml"
        expected = resolve_from_pyproject(pyproject.read_text())
        declared = json.loads(job["with"]["python-versions"])
        assert declared == expected, (
            f"{name} tests {declared}, but {working_directory} supports {expected}"
        )


def test_release_uses_resolved_matrix() -> None:
    """Fan out release checks over the versions resolved by `build`."""
    workflow = yaml.safe_load(RELEASE_WORKFLOW.read_text())
    jobs = workflow["jobs"]

    assert jobs["build"]["outputs"]["python-versions"] == (
        "${{ steps.python-matrix.outputs.python-versions }}"
    )
    strategy = jobs["pre-release-checks"]["strategy"]
    assert strategy["fail-fast"] is False
    assert strategy["matrix"]["python-version"] == (
        "${{ fromJSON(needs.build.outputs.python-versions) }}"
    )


@pytest.mark.parametrize(
    ("requires_python", "expected"),
    [
        (">=3.11", ["3.11", "3.12", "3.13", "3.14"]),
        (">=3.11,<4.0", ["3.11", "3.12", "3.13", "3.14"]),
        (">=3.12,<3.14", ["3.12", "3.13"]),
        (">=3.11,!=3.12", ["3.11", "3.13", "3.14"]),
        ("==3.13", ["3.13"]),
        (">3.11,<=3.13", ["3.12", "3.13"]),
    ],
)
def test_resolve_python_versions(requires_python: str, expected: list[str]) -> None:
    assert resolve_python_versions(requires_python) == expected


@pytest.mark.parametrize(
    "requires_python",
    ["", "~=3.11", "==3.12.*", ">=3.15", ">=3.11,<3.11"],
)
def test_resolve_python_versions_rejects_unusable_specifiers(
    requires_python: str,
) -> None:
    """Unknown syntax and empty matrices must fail closed."""
    with pytest.raises(ValueError):
        resolve_python_versions(requires_python)


def test_supported_versions_are_ordered_and_unique() -> None:
    versions = list(SUPPORTED_PYTHON_VERSIONS)
    expected = sorted(
        set(versions), key=lambda value: tuple(map(int, value.split(".")))
    )
    assert versions == expected


def test_every_release_package_resolves_a_matrix() -> None:
    """Each release option must yield at least one test interpreter."""
    workflow = yaml.safe_load(RELEASE_WORKFLOW.read_text())
    options = workflow[True]["workflow_dispatch"]["inputs"]["package"]["options"]

    pyprojects: dict[str, Path] = {}
    for pyproject in (ROOT / "libs").rglob("pyproject.toml"):
        relative = pyproject.parent.relative_to(ROOT / "libs").parts
        if len(relative) == 1 or (len(relative) == 2 and relative[0] == "partners"):
            with open(pyproject, "rb") as file:
                name = tomllib.load(file).get("project", {}).get("name")
            if name:
                pyprojects[name] = pyproject

    for option in options:
        assert resolve_from_pyproject(pyprojects[option].read_text())

# Applies `package:*` / `integration:*` labels from the issue form's
# "Area" section, `topic:*` from a small open model, and a default
# `priority:triage` on every new issue.
# Taxonomy: .github/LABELS.md.

name: Auto Label Issues by Package

on:
  issues:
    types: [opened, edited]

permissions:
  contents: read

jobs:
  label-by-package:
    environment: labeling
    permissions:
      contents: read
      issues: write
    runs-on: ubuntu-latest

    steps:
      # Checks out the default branch so
      # `require('./.github/scripts/labeling/pr-labeler.js')` resolves. This
      # workflow runs on `issues` events, which carry no PR code.
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1

      # Mark new issues for triage before the Area sync, including issues
      # opened without the form (API, blank issue). Skip issues that already
      # carry a priority so re-runs do not overwrite maintainer decisions.
      - name: Apply default priority
        if: github.event.action == 'opened'
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const { owner, repo } = context.repo;
            const issue_number = context.payload.issue.number;
            const DEFAULT_PRIORITY = 'priority:triage';

            const { data: issue } = await github.rest.issues.get({
              owner, repo, issue_number,
            });
            const current = (issue.labels ?? []).map(l => l.name ?? l);
            if (current.some(name => name.startsWith('priority:'))) {
              console.log(`Issue #${issue_number} already has a priority; leaving it alone.`);
              return;
            }

            const { h } = require('./.github/scripts/labeling/pr-labeler.js')
              .loadAndInit(github, owner, repo, core);
            await h.ensureLabel(DEFAULT_PRIORITY);

            await github.rest.issues.addLabels({
              owner, repo, issue_number, labels: [DEFAULT_PRIORITY],
            });
            console.log(`Applied '${DEFAULT_PRIORITY}' to issue #${issue_number}`);

      # `topic:*` from a small open model. Classify on `opened` only. The step
      # never removes a topic, so re-running on `edited` would re-add one a
      # maintainer had deliberately removed, with no way to make the removal
      # stick — and would spend a model call per edit for the same answer.
      # Matches the priority step above.
      - name: Apply topic labels
        if: github.event.action == 'opened'
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          TOPIC_CLASSIFIER_PROVIDER: ${{ vars.TOPIC_CLASSIFIER_PROVIDER }}
          GROQ_API_KEY: ${{ secrets.GROQ_API_KEY }}
          LANGSMITH_API_KEY: ${{ secrets.LANGSMITH_API_KEY }}
          LANGSMITH_WORKSPACE_ID: ${{ vars.LANGSMITH_WORKSPACE_ID }}
        with:
          script: |
            const { owner, repo } = context.repo;
            const issue = context.payload.issue;
            const { h } = require('./.github/scripts/labeling/pr-labeler.js')
              .loadAndInit(github, owner, repo, core);
            const { classifyTopicLabels, loadTopicLabels } = require('./.github/scripts/labeling/topic-classifier.js');

            let topics;
            try {
              const allowed = new Set(loadTopicLabels());
              const labels = await github.paginate(github.rest.issues.listLabelsForRepo, {
                owner, repo, per_page: 100,
              });
              const descriptions = Object.fromEntries(labels
                .filter(label => allowed.has(label.name) && typeof label.description === 'string' && label.description.trim())
                .map(label => [label.name, label.description]));
              const missing = [...allowed].filter(name => !Object.hasOwn(descriptions, name));
              if (missing.length) core.warning(`Skipping topics without descriptions: ${missing.join(', ')}`);
              if (!Object.keys(descriptions).length) return;
              topics = await classifyTopicLabels(
                `${issue.title ?? ''}\n\n${issue.body ?? ''}`, Object.keys(descriptions),
                { descriptions, debug: core.debug, info: core.info },
              );
            } catch (error) {
              core.warning(`Topic classification failed: ${error.message}`);
              return;
            }
            // Safe to trust the payload here, unlike the priority step: this
            // runs on `opened`, so no earlier run can have set a topic.
            const current = new Set((issue.labels ?? []).map(l => l.name ?? l));
            const toAdd = [...topics].filter(name => !current.has(name));
            if (!toAdd.length) {
              console.log(`No new topic labels for issue #${issue.number}.`);
              return;
            }

            for (const name of toAdd) await h.ensureLabel(name);
            await github.rest.issues.addLabels({
              owner, repo, issue_number: issue.number, labels: toAdd,
            });
            console.log(`Applied [${toAdd.join(', ')}] to issue #${issue.number}`);

      - name: Sync package labels
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const body = context.payload.issue.body || "";

            // Extract text under "## Area" or "### Area" (handles " (Required)" suffix and being last section)
            const match = body.match(/#{2,3} Area[^\n]*\n([\s\S]*?)(?:\n#{2,3} |$)/i);
            if (!match) {
              console.log(`Issue #${context.issue.number} has no Area section; skipping package labels.`);
              return;
            }

            const packageSection = match[1].trim();

            // Maps the issue form's "Area" option labels to `package:*` /
            // `integration:*` labels.
            // Keys must match the `options:` in .github/ISSUE_TEMPLATE/*.yml
            // verbatim; the labels must match `scopeToLabel` in
            // .github/scripts/labeling/pr-labeler-config.json so issues and
            // PRs for the same package land on the same label.
            // "Other / not sure / general" is intentionally unmapped.
            const mapping = {
              "deepagents (SDK)": "package:deepagents",
              "acp": "package:acp",
              "dcode": "package:dcode",
              "talon": "package:talon",
              "evals": "package:evals",
              "daytona": "integration:daytona",
              "modal": "integration:modal",
              "quickjs": "integration:quickjs",
              "runloop": "integration:runloop",
              "vercel": "integration:vercel",
              "langsmith-sandbox": "integration:langsmith",
            };

            // All package labels we manage. Only these are removed when a
            // selection is cleared — a label outside this set (applied by
            // hand) is left alone.
            const allPackageLabels = [...new Set(Object.values(mapping))];
            const selectedLabels = [];

            // Check if this is checkbox format (multiple selection)
            const checkboxMatches = packageSection.match(/- \[x\]\s+([^\n\r]+)/gi);
            if (checkboxMatches) {
              // Handle checkbox format
              for (const match of checkboxMatches) {
                const packageName = match.replace(/- \[x\]\s+/i, '').trim();
                const label = mapping[packageName];
                if (label && !selectedLabels.includes(label)) {
                  selectedLabels.push(label);
                }
              }
            } else {
              // Handle dropdown format (single selection)
              const label = mapping[packageSection];
              if (label) {
                selectedLabels.push(label);
              }
            }

            // Get current issue labels
            const issue = await github.rest.issues.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number
            });

            const currentLabels = issue.data.labels.map(label => label.name);
            const currentPackageLabels = currentLabels.filter(label => allPackageLabels.includes(label));

            // Determine labels to add and remove
            const labelsToAdd = selectedLabels.filter(label => !currentPackageLabels.includes(label));
            const labelsToRemove = currentPackageLabels.filter(label => !selectedLabels.includes(label));

            // Add new labels
            if (labelsToAdd.length > 0) {
              await github.rest.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.issue.number,
                labels: labelsToAdd
              });
            }

            // Remove old labels
            for (const label of labelsToRemove) {
              await github.rest.issues.removeLabel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.issue.number,
                name: label
              });
            }

.github/workflows/block_fork_main_prs.ym:
# Block PRs whose head ref is `main` (or `master`) from a fork. This topology
# (`<fork>:main -> langchain-ai/deepagents:main`) lets contributors click
# "Update branch" on the PR, producing a `Merge branch 'main' into main`
# commit on the source side that — under admin merge override — can land
# directly on `main` as a 2-parent merge commit, bypassing the repo's
# squash-only policy and polluting the changelog.
#
# `pull_request_target` is required so the job receives a token scoped to
# write PR labels/comments on fork PRs (the standard `pull_request` token is
# read-only for forks). This also means the job MUST NOT check out PR code —
# see the inline warning in the trigger block below.
#
# Maintainer bypass: add the `ci:bypass-fork-main` label to the PR.

name: Block fork main PRs

on:
  pull_request_target:
    # NEVER CHECK OUT UNTRUSTED CODE FROM A PR's HEAD IN A pull_request_target JOB.
    # Doing so would allow attackers to execute arbitrary code in the context of your repository.
    types: [opened, reopened, synchronize, labeled, unlabeled]

permissions:
  contents: read

jobs:
  guard:
    if: >-
      github.event.pull_request.head.repo.fork == true &&
      (github.event.pull_request.head.ref == 'main' || github.event.pull_request.head.ref == 'master') &&
      !contains(github.event.pull_request.labels.*.name, 'ci:bypass-fork-main')
    runs-on: ubuntu-latest
    permissions:
      pull-requests: write
    steps:
      - name: Close PR and post guidance
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request.number;
            const headRef = context.payload.pull_request.head.ref;
            const marker = '<!-- block-fork-main -->';

            const lines = [
              marker,
              `**This PR has been automatically closed** because its head branch is \`${headRef}\` on a fork.`,
              '',
              'PRs opened from a fork\'s `main` (or `master`) branch can produce a `Merge branch \'main\' into main` commit on the source side. Under an admin merge override that commit can land directly on this repo\'s `main`, bypassing the squash-only policy and polluting the changelog.',
              '',
              'To fix:',
              '1. Sync your fork\'s `main` first (`git fetch upstream && git switch main && git merge --ff-only upstream/main`)',
              '2. Create a feature branch: `git switch -c feat/my-change`',
              '3. Push it: `git push -u origin feat/my-change`',
              '4. Open a new PR from `feat/my-change` → `langchain-ai/deepagents:main`',
              '',
              '*Maintainers: add the `ci:bypass-fork-main` label to override.*',
            ];
            const body = lines.join('\n');

            // Dedup: update existing marker comment instead of stacking.
            const comments = await github.paginate(
              github.rest.issues.listComments,
              { owner, repo, issue_number: prNumber, per_page: 100 },
            );
            const existing = comments.find(c => c.body && c.body.includes(marker));

            if (!existing) {
              await github.rest.issues.createComment({
                owner, repo, issue_number: prNumber, body,
              });
            } else if (existing.body !== body) {
              await github.rest.issues.updateComment({
                owner, repo, comment_id: existing.id, body,
              });
            }

            if (context.payload.pull_request.state === 'open') {
              await github.rest.pulls.update({
                owner, repo, pull_number: prNumber, state: 'closed',
              });
            }

            // Cancel still-queued/in-progress checks on this PR head.
            // Best-effort: new runs may still queue after this loop (e.g., other
            // pull_request triggers fanning out). The PR is already closed above,
            // so leftover runs are wasted compute, not a correctness issue.
            // We track the cancel ratio so a wholesale failure (token-scope
            // regression making EVERY cancel return 403) is surfaced rather
            // than silently producing N warnings + green job.
            const headSha = context.payload.pull_request.head.sha;
            let attempted = 0;
            let cancelled = 0;
            for (const status of ['in_progress', 'queued']) {
              const runs = await github.paginate(
                github.rest.actions.listWorkflowRunsForRepo,
                { owner, repo, head_sha: headSha, status, per_page: 100 },
              );
              for (const run of runs) {
                if (run.id === context.runId) continue;
                attempted++;
                try {
                  await github.rest.actions.cancelWorkflowRun({
                    owner, repo, run_id: run.id,
                  });
                  cancelled++;
                } catch (err) {
                  core.warning(`Could not cancel run ${run.id}: ${err.message}`);
                }
              }
            }
            if (attempted > 0 && cancelled === 0) {
              core.warning(`Attempted to cancel ${attempted} run(s) on head ${headSha} but none succeeded — check token scope.`);
            }

            core.setFailed(`PR head ref is \`${headRef}\` on a fork — open from a feature branch instead.`);

.github/workflows/branch_name_check.yml:
# PR head-branch naming check.
#
# Why this exists:
#   AGENTS.md requires internal branches to follow
#   `<github-username>/<scope>/<short-description>` (e.g. `mdrxy/cli/startup-cmd-flag`).
#   The local pre-push hook in .githooks/ catches this before push, but it is
#   client-side and can be skipped with `--no-verify` or never installed. This
#   check is the server-side reminder for PRs opened from branches in this repo.
#   It is advisory only — it posts a sticky PR comment and a workflow warning
#   but always passes, so it never blocks a merge.
#
# Scope:
#   - Only runs for same-repo (non-fork) PRs. Fork PRs have head branches in
#     the contributor's fork, where this repo's naming convention does not apply.
#   - Skips protected branches (`main`, `master`, `vX.Y...`), automation branches
#     (release-please, dependabot, copilot) and the release branches mandated by
#     RELEASING.md (`alpha/`, `beta/`, `rc/`, `dev/`) — none carry a username
#     prefix.
#   - Validates the `<scope>` segment against the same scope list enforced by
#     pr_lint.yml (plus `docs`, which AGENTS.md lists as a branch scope), so
#     branch scopes and PR title scopes stay aligned. The `branch-scopes-sync`
#     pre-commit hook enforces that this list, pr_lint.yml and .githooks/pre-push
#     agree.
#   - Does NOT enforce that the username segment equals the PR author's login —
#     branches are sometimes pushed by automation or another maintainer on the
#     author's behalf.
#
# Trust model:
#   - Runs under `pull_request` (not `pull_request_target`); the only input is
#     the head branch name from the event payload. Same-repo PRs only, so the
#     `issues: write` token used for the sticky comment is never exposed to
#     fork-controlled code.

name: "🌿 Branch name check"

permissions:
  contents: read
  issues: write

on:
  pull_request:
    # No `edited`: a PR's head ref cannot be changed after opening, so a title
    # or body edit can never change this check's outcome. `synchronize` and
    # `reopened` already cover re-running after the allowed-branch rules change.
    types: [opened, synchronize, reopened]

concurrency:
  # Serialize per-PR so rapid pushes can't race the sticky comment's
  # find-then-create logic into posting duplicates.
  group: branch-name-check-${{ github.event.pull_request.number }}
  cancel-in-progress: true

jobs:
  branch-name-check:
    name: "validate head branch name"
    runs-on: ubuntu-latest
    timeout-minutes: 3
    # Fork PRs: head branch lives in the fork; repo conventions don't apply.
    if: github.event.pull_request.head.repo.full_name == github.repository
    steps:
      - name: "✅ Validate branch name"
        id: check
        env:
          HEAD_REF: ${{ github.event.pull_request.head.ref }}
        run: |
          set -euo pipefail

          # These three patterns are duplicated in .githooks/pre-push; the
          # `branch-scopes-sync` pre-commit hook fails the commit if they drift.
          ALLOWED_RE='^(main|master|v[0-9]+\.[0-9]+.*)$'
          ALLOWED_PREFIX_RE='^(release-please--|dependabot/|copilot/|alpha/|beta/|rc/|dev/)'
          SCOPES_RE='(acp|ci|code|dcode-gha|daytona|deepagents|deepagents-acp|deepagents-code|deepagents-talon|deps|deps-dev|docs|evals|examples|harbor|infra|langchain-daytona|langchain-modal|langchain-quickjs|langchain-runloop|langchain-vercel-sandbox|langsmith-sandbox|modal|quickjs|repo|runloop|sdk|talon|vercel)'

          if [[ "$HEAD_REF" =~ $ALLOWED_RE ]] || [[ "$HEAD_REF" =~ $ALLOWED_PREFIX_RE ]]; then
            echo "::notice::Branch '$HEAD_REF' is protected or automation-owned; skipping name check."
            echo "nonconformant=false" >> "$GITHUB_OUTPUT"
            exit 0
          fi

          # <github-username>: a GitHub login segment; not compared to the PR
          # author (see workflow header). The class accepts uppercase, because
          # logins may contain it and refs preserve case — a lowercase-only
          # class here would warn on names the local hook accepts. Advisory
          # only: warn, don't fail.
          # Kebab-case description: the final group is optional so
          # one-character descriptions are valid; still no trailing hyphen.
          if [[ ! "$HEAD_REF" =~ ^[A-Za-z0-9](-?[A-Za-z0-9])*/${SCOPES_RE}/[a-z0-9]([a-z0-9-]*[a-z0-9])?$ ]]; then
            echo "::warning::Branch '$HEAD_REF' does not follow the repo naming convention '<github-username>/<scope>/<short-description>'."
            echo "nonconformant=true" >> "$GITHUB_OUTPUT"
          else
            echo "Branch '$HEAD_REF' follows the naming convention."
            echo "nonconformant=false" >> "$GITHUB_OUTPUT"
          fi

      - name: "💬 Post or remove sticky comment"
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          HEAD_REF: ${{ github.event.pull_request.head.ref }}
          NONCONFORMANT: ${{ steps.check.outputs.nonconformant }}
        with:
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request?.number;
            // Defensive guard — every supported trigger type carries a PR
            // payload, but a future trigger expansion should fail with an
            // actionable message rather than a raw TypeError.
            if (!prNumber) {
              core.setFailed('No PR number in payload — workflow may have triggered on an unexpected event type.');
              return;
            }
            const STICKY_MARKER = '<!-- branch-name-check -->';
            const headRef = process.env.HEAD_REF;

            // The verdict must be an explicit `true`/`false` from the validate
            // step. Treating anything else as "conformant" would let a renamed
            // step id, a renamed output key, or an early `exit 0` that forgets
            // to write `$GITHUB_OUTPUT` pass silently — and worse, delete an
            // existing warning comment. That is indistinguishable from "every
            // branch is conformant", so it fails loudly. Unlike the comment API
            // errors below, this can only come from a wiring bug in this file;
            // it will not fix itself on a re-run.
            const verdict = process.env.NONCONFORMANT;
            if (verdict !== 'true' && verdict !== 'false') {
              core.setFailed(
                `The validate step reported no verdict (nonconformant='${verdict}') — ` +
                `the check ran but validated nothing. Check the 'check' step's outputs ` +
                `in branch_name_check.yml.`,
              );
              return;
            }
            const nonconformant = verdict === 'true';

            // Only this workflow's own comments are eligible: the marker alone
            // would also match a human's comment that happens to quote it,
            // which this job may go on to edit or delete.
            async function findStickyComment() {
              const comments = await github.paginate(github.rest.issues.listComments, {
                owner, repo, issue_number: prNumber, per_page: 100,
              });
              return comments.find(
                c => c.body && c.body.startsWith(STICKY_MARKER) && c.user?.type === 'Bot',
              );
            }

            // Comment API failures must not make this explicitly advisory
            // workflow fail. In particular, GitHub uses 403 for both missing
            // permissions and temporary secondary-rate-limit/abuse responses,
            // and a comment can disappear between the lookup and update/delete.
            function reportApiError(err, context) {
              const status = err.status ? `HTTP ${err.status}` : 'an unknown error';
              core.warning(`${context} failed with ${status}: ${err.message}`);
            }

            // Conformant branch: clean up any stale warning and pass. Rarely
            // reached in practice — a PR's head ref cannot be renamed in place,
            // so this mostly serves re-runs after the allowed-branch rules
            // change. On a delete failure, edit the comment instead so a
            // now-conformant PR never keeps a bare ⚠️ with no explanation.
            if (!nonconformant) {
              try {
                const existing = await findStickyComment();
                if (existing) {
                  try {
                    await github.rest.issues.deleteComment({
                      owner, repo, comment_id: existing.id,
                    });
                    console.log('Branch name is conformant — deleted sticky warning comment');
                  } catch (deleteErr) {
                    await github.rest.issues.updateComment({
                      owner, repo, comment_id: existing.id,
                      body: `${STICKY_MARKER}\n✅ Branch \`${headRef}\` now follows the repo naming convention. This warning is stale.`,
                    });
                    console.log('Could not delete sticky comment — marked it resolved instead');
                  }
                }
              } catch (e) {
                reportApiError(e, `Sticky comment cleanup for PR #${prNumber}`);
              }
              return;
            }

            const body = [
              STICKY_MARKER,
              `⚠️ **Branch \`${headRef}\` doesn't follow the repo naming convention.**`,
              '',
              'Internal branches are expected to be named `<github-username>/<scope>/<short-description>` — see the "Branch naming" section of AGENTS.md. Example: `mdrxy/cli/startup-cmd-flag`. Valid scopes are the ones in `pr_lint.yml`, plus `docs`.',
              '',
              'This is advisory only and does not block merge.',
              '',
              'GitHub does not allow an open PR\'s head branch to be changed, so renaming means opening a new PR from the renamed branch:',
              '',
              '```bash',
              `git branch -m ${headRef} <new-name>`,
              'git push origin <new-name>',
              '```',
              '',
              `Then open a PR from \`<new-name>\` and close this one. (Deleting \`${headRef}\` before that will close this PR automatically.)`,
            ].join('\n');

            // Fall back to the job summary if any comment operation fails so
            // the warning stays visible without turning this advisory check red.
            try {
              const existing = await findStickyComment();
              if (existing) {
                if (existing.body !== body) {
                  await github.rest.issues.updateComment({
                    owner, repo, comment_id: existing.id, body,
                  });
                  console.log('Updated sticky warning comment');
                } else {
                  console.log('Sticky warning comment already up to date');
                }
              } else {
                await github.rest.issues.createComment({
                  owner, repo, issue_number: prNumber, body,
                });
                console.log('Posted sticky warning comment');
              }
            } catch (commentErr) {
              reportApiError(commentErr, 'Posting the sticky branch-name comment');
              await core.summary
                .addHeading('Branch name warning; comment could not be posted')
                .addRaw('Paste the following into the PR as a comment:')
                .addCodeBlock(body, 'markdown')
                .write();
            }

.github/workflows/check_dep_freshness.ym:
# Release PR gate: reports stale dependency minimums, validates built-wheel
# metadata, and installs the wheel with dependencies resolved only from PyPI.

name: "📦 Check Dependency Freshness"

on:
  pull_request:
    types: [opened, edited, synchronize, reopened, labeled, unlabeled]

concurrency:
  group: ${{ github.workflow }}-${{ github.ref }}
  cancel-in-progress: true

permissions:
  contents: read

jobs:
  check-dependency-freshness:
    name: "validate release dependencies against PyPI"
    runs-on: ubuntu-latest
    timeout-minutes: 20
    outputs:
      stale: ${{ steps.check.outputs.stale || steps.skip.outputs.stale }}
      indeterminate: ${{ steps.check.outputs.indeterminate || steps.skip.outputs.indeterminate }}
      comment_body: ${{ steps.check.outputs.comment_body || steps.skip.outputs.comment_body }}
    steps:
      - name: "🔎 Detect release PR"
        id: release-pr
        env:
          PR_TITLE: ${{ github.event.pull_request.title }}
        run: |
          if [[ "$PR_TITLE" == release\(* ]]; then
            echo "is_release=true" >> "$GITHUB_OUTPUT"
          else
            echo "is_release=false" >> "$GITHUB_OUTPUT"
            echo "This is not a release-please PR; no release artifact needs validation."
          fi

      - name: "✅ Report non-release PR"
        id: skip
        if: steps.release-pr.outputs.is_release != 'true'
        run: |
          echo "stale=false" >> "$GITHUB_OUTPUT"
          echo "indeterminate=false" >> "$GITHUB_OUTPUT"
          echo "comment_body=" >> "$GITHUB_OUTPUT"

      - name: "📋 Checkout Code"
        if: steps.release-pr.outputs.is_release == 'true'
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 0

      - name: "🐍 Set up Python and uv"
        if: steps.release-pr.outputs.is_release == 'true'
        uses: "./.github/actions/uv_setup"
        with:
          python-version: "3.14"
          enable-cache: "false"

      - name: "🧭 Resolve release package"
        id: target
        if: steps.release-pr.outputs.is_release == 'true'
        env:
          PR_TITLE: ${{ github.event.pull_request.title }}
        run: >-
          uv run --no-project --with packaging python
          .github/scripts/release/check_wheel_dep_freshness.py
          target --title "$PR_TITLE"

      - name: "🔍 Compare dependency minimums with PyPI"
        id: check
        if: steps.release-pr.outputs.is_release == 'true'
        env:
          BASE_SHA: ${{ github.event.pull_request.base.sha }}
          HEAD_SHA: ${{ github.event.pull_request.head.sha }}
          DEP_FRESHNESS_PRERELEASE_POLICY: "bound"
        run: uv run --no-project --with packaging python .github/scripts/release/check_dep_freshness.py

      - name: "📦 Build release wheel"
        if: steps.release-pr.outputs.is_release == 'true'
        env:
          DEEPAGENTS_CODE_BUILD_COMMIT: ${{ github.event.pull_request.head.sha }}
          DIST_DIR: ${{ runner.temp }}/release-dist
          PACKAGE_PATH: ${{ steps.target.outputs.package_path }}
          PYTHON_VERSION: ${{ steps.target.outputs.python_version }}
        run: uv build --python "$PYTHON_VERSION" "$PACKAGE_PATH" --out-dir "$DIST_DIR"

      - name: "🔎 Find built wheel"
        id: wheel
        if: steps.release-pr.outputs.is_release == 'true'
        env:
          DIST_DIR: ${{ runner.temp }}/release-dist
        run: |
          shopt -s nullglob
          wheels=("$DIST_DIR"/*.whl)
          if [ "${#wheels[@]}" -ne 1 ]; then
            echo "::error::Expected one built wheel in $DIST_DIR, found ${#wheels[@]}"
            exit 1
          fi
          echo "path=${wheels[0]}" >> "$GITHUB_OUTPUT"

      - name: "🧾 Validate wheel dependency metadata"
        if: steps.release-pr.outputs.is_release == 'true'
        env:
          WHEEL_PATH: ${{ steps.wheel.outputs.path }}
        run: >-
          uv run --no-project --with packaging python
          .github/scripts/release/check_wheel_dep_freshness.py
          validate --wheel "$WHEEL_PATH" --repo-root "$GITHUB_WORKSPACE"

      - name: "🌐 Install wheel with dependencies from PyPI"
        if: steps.release-pr.outputs.is_release == 'true'
        env:
          PACKAGE_NAME: ${{ steps.target.outputs.package_name }}
          PYTHON_VERSION: ${{ steps.target.outputs.python_version }}
          VENV_PATH: ${{ runner.temp }}/release-install-venv
          WHEEL_PATH: ${{ steps.wheel.outputs.path }}
        run: |
          uv venv --python "$PYTHON_VERSION" "$VENV_PATH"
          INSTALL_ARGS=(--index-url "https://pypi.org/simple" "$WHEEL_PATH")
          if [ "$PACKAGE_NAME" = "deepagents-talon" ]; then
            INSTALL_ARGS=(--prerelease allow "${INSTALL_ARGS[@]}")
          fi
          # setup-uv exports UV_PYTHON for the version it installed (3.14),
          # which overrides VIRTUAL_ENV and makes `uv pip` demand a 3.14 venv
          # even though the release package targets $PYTHON_VERSION.
          env -u UV_PYTHON VIRTUAL_ENV="$VENV_PATH" uv pip install "${INSTALL_ARGS[@]}"

  manage-dependency-freshness-comment:
    name: "manage dependency freshness PR comment"
    needs: check-dependency-freshness
    # Run for bypassed and renamed PRs too, so an obsolete comment is removed.
    if: always()
    runs-on: ubuntu-latest
    permissions:
      issues: write
    steps:
      - name: "💬 Manage PR comment"
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          COMMENT_BODY: ${{ needs.check-dependency-freshness.outputs.comment_body }}
          INDETERMINATE: ${{ needs.check-dependency-freshness.outputs.indeterminate }}
          STALE: ${{ needs.check-dependency-freshness.outputs.stale }}
        with:
          script: |
            const marker = '<!-- dep-freshness-check -->';
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request.number;
            const body = process.env.COMMENT_BODY || '';
            const staleRaw = process.env.STALE || '';
            const stale = staleRaw === 'true';
            const indeterminate = process.env.INDETERMINATE === 'true';

            // Non-release PRs explicitly emit `stale=false`; empty output means
            // the gate crashed before it could report a result. Preserve the last
            // advisory comment while the failed job explains the infrastructure error.
            const crashed = staleRaw === '';

            try {
              if (crashed) {
                core.info('Dependency freshness check produced no result; leaving any existing comment in place.');
                return;
              }

              const comments = await github.paginate(
                github.rest.issues.listComments,
                { owner, repo, issue_number: prNumber, per_page: 100 },
              );
              const existing = comments.find(
                c => c.user?.login === 'github-actions[bot]' &&
                  (c.body ?? '').startsWith(marker),
              );

              if (indeterminate && existing) {
                core.warning('Some PyPI queries were indeterminate; leaving the existing dependency freshness comment in place.');
                return;
              }

              if (stale) {
                if (!body.trim()) {
                  core.warning('Dependency freshness check found stale bounds but produced no comment body; keeping any existing comment.');
                  return;
                }
                if (existing) {
                  await github.rest.issues.updateComment({ owner, repo, comment_id: existing.id, body });
                  core.info('Updated dependency freshness warning comment.');
                } else {
                  await github.rest.issues.createComment({ owner, repo, issue_number: prNumber, body });
                  core.info('Created dependency freshness warning comment.');
                }
                return;
              }

              if (indeterminate) {
                core.warning('Some PyPI queries were indeterminate; leaving any existing dependency freshness comment in place.');
                return;
              }

              if (existing) {
                await github.rest.issues.deleteComment({ owner, repo, comment_id: existing.id });
                core.info('Dependency minimums are current or acknowledged — removed stale warning comment.');
              } else {
                core.info('No dependency freshness warning comment needed.');
              }
            } catch (err) {
              // 403 covers both missing comment permissions and rate/abuse
              // limits. Commenting is advisory, so degrade to a warning (with
              // the original message for diagnosis) instead of failing the job.
              if (err.status === 403) {
                core.warning(`Skipping dependency freshness PR comment (403 — token lacks comment permission or is rate limited): ${err.message}`);
                return;
              }
              throw err;
            }

.github/workflows/check_partner_bounds.y:
# Advisory check: posts a comment on SDK release PRs when the new SDK version
# would fall outside a partner package's upper-bound constraint on `deepagents`.
# Does not block merge — it's a reminder to bump partner bounds in a follow-up.
# Updates or removes the comment on subsequent runs.

name: "📦 Check Partner Bounds"

on:
  pull_request:
    paths:
      # Also trigger on partner toml changes so re-runs pick up bound bumps
      # within the same PR.
      - "libs/deepagents/pyproject.toml"
      - "libs/partners/*/pyproject.toml"

concurrency:
  group: ${{ github.workflow }}-${{ github.ref }}
  cancel-in-progress: true

permissions:
  contents: read

jobs:
  check-partner-bounds:
    if: github.head_ref == 'release-please--branches--main--components--deepagents'
    runs-on: ubuntu-latest
    timeout-minutes: 2
    permissions:
      contents: read
      pull-requests: write
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1

      - name: Check partner upper bounds
        id: check
        run: |
          set -euo pipefail

          SDK_VERSION=$(sed -nE 's/^version = "([0-9]+\.[0-9]+\.[0-9]+)".*/\1/p' libs/deepagents/pyproject.toml | head -1)
          if [[ -z "$SDK_VERSION" ]]; then
            echo "::error file=libs/deepagents/pyproject.toml::Failed to extract SDK version"
            exit 1
          fi
          echo "sdk_version=$SDK_VERSION" >> "$GITHUB_OUTPUT"

          # Normalize a semver triple to a comparable integer (e.g. 0.6.1 → 000006001).
          version_num() {
            echo "$1" | awk -F. '{ printf "%d%03d%03d", $1, $2, $3 }'
          }
          sdk_num=$(version_num "$SDK_VERSION")

          shopt -s nullglob
          toml_files=(libs/partners/*/pyproject.toml)
          if [[ ${#toml_files[@]} -eq 0 ]]; then
            echo "::warning::No partner pyproject.toml files found — nothing to check."
            echo "stale=false" >> "$GITHUB_OUTPUT"
            exit 0
          fi

          stale=""
          for toml in "${toml_files[@]}"; do
            partner=$(echo "$toml" | sed 's|libs/partners/\(.*\)/pyproject.toml|\1|')

            # Extract upper bound: deepagents>=X.Y.Z,<A.B.C → A.B.C
            upper=$(sed -nE 's/.*"deepagents[^"]*<([0-9]+\.[0-9]+\.[0-9]+)".*/\1/p' "$toml" | head -1)
            if [[ -z "$upper" ]]; then
              # No upper bound constraint — skip.
              continue
            fi

            upper_num=$(version_num "$upper")

            # SDK version is excluded when upper bound <= SDK version.
            # e.g. SDK=0.6.0, upper=<0.6.0 → 0.6.0 is NOT < 0.6.0 → excluded.
            if [[ "$upper_num" -le "$sdk_num" ]]; then
              stale+="${partner}|<${upper}|${toml}"$'\n'
            fi
          done

          if [[ -n "$stale" ]]; then
            echo "stale=true" >> "$GITHUB_OUTPUT"
            {
              echo "partners<<STALE_EOF"
              printf '%s' "$stale"
              echo "STALE_EOF"
            } >> "$GITHUB_OUTPUT"
          else
            echo "stale=false" >> "$GITHUB_OUTPUT"
          fi

      - name: Manage PR comment
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          SDK_VERSION: ${{ steps.check.outputs.sdk_version }}
          STALE: ${{ steps.check.outputs.stale }}
          PARTNERS: ${{ steps.check.outputs.partners }}
        with:
          script: |
            const marker = '<!-- partner-bounds-check -->';
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request.number;

            const sdkVersion = process.env.SDK_VERSION;
            if (!sdkVersion || !/^\d+\.\d+\.\d+$/.test(sdkVersion)) {
              core.setFailed(
                `SDK version extraction returned invalid value: "${sdkVersion}". ` +
                'Check that libs/deepagents/pyproject.toml has the expected format.'
              );
              return;
            }

            let comments;
            try {
              comments = await github.paginate(
                github.rest.issues.listComments,
                { owner, repo, issue_number: prNumber, per_page: 100 },
              );
            } catch (error) {
              core.setFailed(
                `Failed to list PR comments (status ${error.status}): ${error.message}`
              );
              return;
            }
            const existing = comments.find(c => c.body?.includes(marker));

            const stale = process.env.STALE === 'true';

            if (!stale && existing) {
              try {
                await github.rest.issues.deleteComment({
                  owner, repo,
                  comment_id: existing.id,
                });
                core.info('Bounds resolved — removed stale warning comment.');
              } catch (error) {
                if (error.status === 404) {
                  core.info('Stale comment already deleted.');
                } else {
                  core.warning(
                    `Failed to delete stale comment #${existing.id} (${error.status}): ${error.message}. ` +
                    'Please delete it manually.'
                  );
                }
              }
            } else if (!stale) {
              core.info('All partner upper bounds accommodate the new SDK version.');
            } else {
              if (!process.env.PARTNERS || !process.env.PARTNERS.trim()) {
                core.setFailed('STALE is true but PARTNERS output is empty — this is a bug in the check step.');
                return;
              }

              const rows = process.env.PARTNERS.trim().split('\n')
                .filter(line => line.trim().length > 0)
                .map(line => {
                  const parts = line.split('|');
                  if (parts.length !== 3) {
                    core.warning(`Malformed partner line (expected 3 pipe-delimited fields): "${line}"`);
                    return null;
                  }
                  const [name, bound, path] = parts;
                  return `> | \`${name}\` | \`${bound}\` | \`${path}\` |`;
                })
                .filter(row => row !== null)
                .join('\n');

              const [major, minor] = sdkVersion.split('.').map(n => parseInt(n, 10));
              const suggestedUpper = `${major}.${minor + 1}.0`;

              const body = [
                marker,
                '> [!WARNING]',
                `> **Partner upper-bound mismatch** — this release bumps \`deepagents\` to \`${sdkVersion}\`, but the following partner packages have an upper bound that would exclude it:`,
                '>',
                '> | Partner | Current bound | File |',
                '> |---|---|---|',
                rows,
                '>',
                `> **To fix:** update each partner's \`pyproject.toml\` to \`deepagents>=${sdkVersion},<${suggestedUpper}\`, run \`uv lock\` in each directory, and open follow-up PRs (or include the bumps in this release).`,
                '>',
                '> **If intentional:** no action needed — existing published partner versions will continue to work with the older SDK range. New partner releases will need the bump.',
              ].join('\n');

              try {
                if (existing) {
                  await github.rest.issues.updateComment({
                    owner, repo,
                    comment_id: existing.id,
                    body,
                  });
                  core.info('Updated existing warning comment.');
                } else {
                  await github.rest.issues.createComment({
                    owner, repo,
                    issue_number: prNumber,
                    body,
                  });
                }
              } catch (error) {
                core.warning(
                  `Could not post/update PR comment (status ${error.status}): ${error.message}.`
                );
              }
              core.warning(
                `Partner packages have upper bounds that exclude deepagents==${sdkVersion}`
              );
            }

.github/workflows/check_release_deps.yml:
# Resolve release PR runtime dependencies against real PyPI.
#
# Local development installs sibling packages as editable path dependencies via
# `[tool.uv.sources]`, which hides whether a package's published dependencies
# actually resolve. The helper strips those local sources and resolves each
# changed release manifest against the real index with
# `uv pip compile --no-sources --universal --prerelease allow --all-extras`.

name: "📦 Check Release Dependencies"

on:
  pull_request:
    types: [opened, edited, synchronize, reopened, labeled, unlabeled]
    paths:
      - "libs/**/pyproject.toml"
      - "release-please-config.json"
      - ".github/scripts/release/check_release_deps.py"
      - ".github/workflows/check_release_deps.yml"

concurrency:
  group: ${{ github.workflow }}-${{ github.ref }}
  cancel-in-progress: true

permissions:
  contents: read

jobs:
  check-release-deps:
    name: "resolve release dependencies"
    # Runs on every release PR, including ones carrying the
    # `ci:ack-release-deps` bypass label. Under the label the script
    # soft-runs: it resolves and posts the follow-up-release sticky but
    # exits 0, so the remaining release debt stays visible instead of
    # disappearing behind a skipped job.
    if: >-
      startsWith(github.event.pull_request.title, 'release(')
    runs-on: ubuntu-latest
    timeout-minutes: 10
    outputs:
      failed: ${{ steps.resolve.outputs.failed }}
      comment_body: ${{ steps.resolve.outputs.comment_body }}
    steps:
      - name: "📋 Checkout Code"
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 0

      - name: "🐍 Set up Python and uv"
        uses: "./.github/actions/uv_setup"
        with:
          python-version: "3.14"
          enable-cache: "false"

      - name: "🔍 Resolve changed release package dependencies"
        id: resolve
        env:
          BASE_SHA: ${{ github.event.pull_request.base.sha }}
          HEAD_SHA: ${{ github.event.pull_request.head.sha }}
          RELEASE_DEPS_ACKED: "${{ contains(github.event.pull_request.labels.*.name, 'ci:ack-release-deps') }}"
        run: uv run --no-project --with packaging python .github/scripts/release/check_release_deps.py

  manage-release-deps-comment:
    name: "manage release dependency PR comment"
    needs: check-release-deps
    if: >-
      always() && startsWith(github.event.pull_request.title, 'release(')
    runs-on: ubuntu-latest
    permissions:
      issues: write
    steps:
      - name: "💬 Manage PR comment"
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          COMMENT_BODY: ${{ needs.check-release-deps.outputs.comment_body }}
          FAILED: ${{ needs.check-release-deps.outputs.failed }}
          RESULT: ${{ needs.check-release-deps.result }}
        with:
          script: |
            const marker = '<!-- release-deps-check -->';
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request.number;
            const body = process.env.COMMENT_BODY || '';
            const failedRaw = process.env.FAILED || '';
            const result = process.env.RESULT || '';
            const failed = failedRaw === 'true';

            // The check job writes `failed=true|false` only when it runs to
            // completion. An empty value means it never produced outputs at
            // all: it crashed, was cancelled by the concurrency group, or died
            // during setup. A skip is no longer one of the causes — the bypass
            // label soft-runs the job instead of skipping it, and this job
            // gates on the same `release(` predicate the check job does. In
            // every remaining case, leave any existing comment so the red
            // check keeps its explanation.
            const crashed = failedRaw === '';

            try {
              if (crashed) {
                core.info(`Release dependency check produced no result (job result: ${result}); leaving any existing comment in place.`);
                return;
              }

              const comments = await github.paginate(
                github.rest.issues.listComments,
                { owner, repo, issue_number: prNumber, per_page: 100 },
              );
              const existing = comments.find(c => (c.body ?? '').includes(marker));

              // A non-empty body always wins. The script emits one whenever it
              // has something to say: an unacknowledged resolution failure, or
              // any run — acknowledged or not — that still owes follow-up
              // releases. It emits an empty body only when there is nothing
              // left to report (nothing changed, or a clean resolve with no
              // outstanding follow-ups), which is the signal to clear the
              // sticky below.
              if (body.trim()) {
                if (existing) {
                  await github.rest.issues.updateComment({ owner, repo, comment_id: existing.id, body });
                  core.info('Updated release dependency comment.');
                } else {
                  await github.rest.issues.createComment({ owner, repo, issue_number: prNumber, body });
                  core.info('Created release dependency comment.');
                }
                return;
              }

              if (failed) {
                core.info('Release dependency check is still failing but produced no comment body; keeping any existing comment.');
                return;
              }

              if (existing) {
                await github.rest.issues.deleteComment({ owner, repo, comment_id: existing.id });
                core.info('Release dependencies resolved — removed stale comment.');
              } else {
                core.info('No release dependency comment needed.');
              }
            } catch (err) {
              // Commenting is best-effort cosmetics on top of the real gate
              // (the check-release-deps job). If the token cannot write comments,
              // degrade to a warning rather than failing this job. Surface anything
              // else.
              if (err.status === 403) {
                core.warning(`Skipping release-deps PR comment (token cannot write comments): ${err.message}`);
                return;
              }
              throw err;
            }

.github/workflows/check_sdk_pin.yml:
# SDK pin check for Code release PRs.
#
# - Stale pin: posts an advisory comment/warning only. The release workflow
#   enforces the pin at publish time.
# - Prerelease pin: posts a warning and fails until the PR carries the
#   `ci:ack-release-deps` label (re-runs on labeled/unlabeled).
# Removes the comment once the pin no longer needs attention.
# See also: release.yml "Verify package pins SDK at or ahead of workspace
# version" step (hard gate for stale pins at publish).

name: "🔗 Check SDK Pin"

on:
  pull_request:
    types: [opened, synchronize, reopened, labeled, unlabeled]
    paths:
      - "libs/deepagents/pyproject.toml"
      - "libs/code/pyproject.toml"

concurrency:
  group: ${{ github.workflow }}-${{ github.ref }}
  cancel-in-progress: true

permissions:
  contents: read
  pull-requests: write

jobs:
  check-sdk-pin:
    if: startsWith(github.head_ref, 'release-please--branches--main--components--deepagents-code')
    runs-on: ubuntu-latest
    timeout-minutes: 2
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1

      - name: Resolve target package from release-please branch
        id: pkg
        env:
          HEAD_REF: ${{ github.head_ref }}
        run: |
          case "$HEAD_REF" in
            release-please--branches--main--components--deepagents-code*)
              echo "name=deepagents-code" >> "$GITHUB_OUTPUT"
              echo "label=Code" >> "$GITHUB_OUTPUT"
              echo "pyproject=libs/code/pyproject.toml" >> "$GITHUB_OUTPUT"
              echo "lockdir=libs/code" >> "$GITHUB_OUTPUT"
              ;;
            *)
              echo "::error::Unexpected head_ref: $HEAD_REF"
              exit 1
              ;;
          esac

      - name: Compare SDK version to package pin
        id: check
        run: |
          # stdout is redirected to GITHUB_OUTPUT, so diagnostics go to stderr.
          python - <<'PY' >> "$GITHUB_OUTPUT"
          import importlib.util
          import sys
          from pathlib import Path

          root = Path.cwd()
          script = root / ".github" / "scripts" / "release" / "check_sdk_pin.py"
          spec = importlib.util.spec_from_file_location("check_sdk_pin", script)
          if spec is None or spec.loader is None:
              print(f"::error::Could not load {script}", file=sys.stderr)
              raise SystemExit(1)
          module = importlib.util.module_from_spec(spec)
          spec.loader.exec_module(module)

          try:
              sdk_version = module._sdk_version(root)
              pkg_pin = module._code_pin(root)
              stale = module.compare_versions(pkg_pin, sdk_version) < 0
              prerelease = module.is_prerelease(pkg_pin)
          except ValueError as e:
              print(
                  "::error file=.github/scripts/release/check_sdk_pin.py::"
                  f"Could not determine SDK pin status: {e}",
                  file=sys.stderr,
              )
              raise SystemExit(1) from None

          print(f"sdk_version={sdk_version}")
          print(f"pkg_pin={pkg_pin}")
          print(f"stale={'true' if stale else 'false'}")
          print(f"prerelease={'true' if prerelease else 'false'}")
          PY

      - name: Manage PR comment
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          SDK_PIN_BYPASS_LABEL: "ci:dcode-skip-sdk-pin"
          RELEASE_DEPS_BYPASS_LABEL: "ci:ack-release-deps"
          SDK_VERSION: ${{ steps.check.outputs.sdk_version }}
          PKG_PIN: ${{ steps.check.outputs.pkg_pin }}
          PIN_STALE: ${{ steps.check.outputs.stale }}
          PIN_PRERELEASE: ${{ steps.check.outputs.prerelease }}
          PKG_NAME: ${{ steps.pkg.outputs.name }}
          PKG_LABEL: ${{ steps.pkg.outputs.label }}
          PKG_PYPROJECT: ${{ steps.pkg.outputs.pyproject }}
          PKG_LOCKDIR: ${{ steps.pkg.outputs.lockdir }}
        with:
          script: |
            // Hidden HTML marker to identify comments posted by this workflow.
            // Scoped per-package so each release PR gets its own comment if
            // additional packages are added to this check.
            const pkgName = process.env.PKG_NAME;
            const pkgLabel = process.env.PKG_LABEL;
            const pkgPyproject = process.env.PKG_PYPROJECT;
            const pkgLockdir = process.env.PKG_LOCKDIR;
            const sdkPinBypassLabel = process.env.SDK_PIN_BYPASS_LABEL;
            const releaseDepsBypassLabel = process.env.RELEASE_DEPS_BYPASS_LABEL;
            const marker = `<!-- sdk-pin-check:${pkgName} -->`;
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request.number;

            const comments = await github.paginate(
              github.rest.issues.listComments,
              { owner, repo, issue_number: prNumber, per_page: 100 },
            );
            const existing = comments.find(c => (c.body ?? '').includes(marker));

            const stale = process.env.PIN_STALE === 'true';
            const prerelease = process.env.PIN_PRERELEASE === 'true';
            const sdkVersion = process.env.SDK_VERSION;
            const pkgPin = process.env.PKG_PIN;
            const pkgPinReleaseUrl = `https://github.com/${owner}/${repo}/releases/tag/${encodeURIComponent(`deepagents==${pkgPin}`)}`;
            const pkgPinLink = `[deepagents==${pkgPin}](${pkgPinReleaseUrl})`;

            if (!sdkVersion || !pkgPin) {
              core.setFailed(
                `Version extraction returned empty values. SDK: "${sdkVersion}", ${pkgLabel} pin: "${pkgPin}". ` +
                `Check that libs/deepagents/pyproject.toml and ${pkgPyproject} have the expected format.`
              );
              return;
            }

            const labels = (context.payload.pull_request.labels ?? [])
              .map(label => (typeof label === 'string' ? label : label.name))
              .filter(Boolean);
            const prereleaseAcknowledged = labels.includes(releaseDepsBypassLabel);

            let body = null;
            let warning = null;
            let fail = false;
            if (stale) {
              body = [
                marker,
                '> [!WARNING]',
                `> **Stale SDK pin** — the ${pkgLabel} release workflow will fail at the "Verify package pins SDK at or ahead of workspace version" step until this is resolved.`,
                '>',
                '> | | Version |',
                '> |---|---|',
                `> | SDK (\`libs/deepagents/pyproject.toml\`) | \`${sdkVersion}\` |`,
                `> | ${pkgLabel} pin (\`${pkgPyproject}\`) | ${pkgPinLink} |`,
                '>',
                `> **To fix:** update \`${pkgPyproject}\` to pin \`deepagents==${sdkVersion}\`, then run \`cd ${pkgLockdir} && uv lock\` and commit the lockfile update.`,
                '>',
                `> **To bypass:** if you intentionally need to pin an older SDK version, add the \`${sdkPinBypassLabel}\` label before merging so the auto-dispatched release skips this check, or re-run the release workflow with \`dangerous-skip-sdk-pin-check\` enabled after a failure. Ensure the ${pkgLabel} package does not contain any code that depends on functionality introduced after ${pkgPinLink} — otherwise the published package will fail at runtime.`,
                '>',
                '> See [`.github/RELEASING.md`](https://github.com/langchain-ai/deepagents/blob/main/.github/RELEASING.md#release-failed-code-sdk-pin-is-older-than-sdk) for the full recovery procedure.',
              ].join('\n');
              warning = `${pkgLabel} has a stale SDK pin: deepagents==${pkgPin} but SDK is ${sdkVersion}`;
            } else if (prerelease && !prereleaseAcknowledged) {
              body = [
                marker,
                '> [!WARNING]',
                `> **Prerelease SDK pin** — ${pkgLabel} currently pins ${pkgPinLink}, which is a prerelease.`,
                '>',
                '> A prerelease pin is valid only when it is not older than the workspace SDK, but it still needs an explicit merge acknowledgement.',
                '>',
                `> 🚨 **Required:** add the \`${releaseDepsBypassLabel}\` label before merging to acknowledge this pin. That label records the review decision and stops the release dependency check from blocking on a pin that is not on PyPI yet (for example during an intentional cross-package release sequence). It does not silence those checks: the release dependency check still resolves and reports any follow-up releases the public install graph needs, and the freshness advisory stays on the PR. Treat their output as outstanding work, not noise.`,
              ].join('\n');
              warning = `${pkgLabel} pins prerelease SDK deepagents==${pkgPin}; add ${releaseDepsBypassLabel} to acknowledge before merging.`;
              fail = true;
            } else if (prerelease) {
              core.info(
                `${pkgLabel} pins prerelease SDK deepagents==${pkgPin}; ` +
                `\`${releaseDepsBypassLabel}\` is present so the pin is acknowledged.`
              );
            }

            if (body === null && existing) {
              try {
                await github.rest.issues.deleteComment({
                  owner, repo,
                  comment_id: existing.id,
                });
                core.info('Pin needs no warning — removed existing warning comment.');
              } catch (error) {
                // 404 = comment was already deleted (concurrent run or manual removal)
                if (error.status === 404) {
                  core.info('Stale comment already deleted.');
                } else {
                  core.warning(
                    `Failed to delete stale SDK pin warning comment (${error.status}): ${error.message}. ` +
                    'The outdated warning may still be visible on the PR.'
                  );
                }
              }
            } else if (body === null) {
              if (!prerelease) {
                core.info(`${pkgLabel} SDK pin is stable and at or ahead of workspace SDK (${pkgPin} >= ${sdkVersion}). No action needed.`);
              }
            } else {
              try {
                // Update silently (no workflow annotation) to avoid repeated warnings on re-pushes.
                if (existing) {
                  await github.rest.issues.updateComment({
                    owner, repo,
                    comment_id: existing.id,
                    body,
                  });
                  core.info('Updated existing warning comment.');
                } else {
                  await github.rest.issues.createComment({
                    owner, repo,
                    issue_number: prNumber,
                    body,
                  });
                }
              } catch (error) {
                core.warning(
                  `Could not post/update PR comment (status ${error.status}): ${error.message}. ` +
                  warning
                );
              }
              // Fail unacknowledged prerelease pins; stale pins stay advisory.
              if (fail) {
                core.setFailed(warning);
              } else {
                core.warning(warning);
              }
            }

.github/workflows/close_unchecked_issues:
# Auto-close issues that bypass or ignore the issue template checkboxes.
#
# GitHub issue forms enforce `required: true` checkboxes in the web UI,
# but the API bypasses form validation entirely — bots/scripts can open
# issues with every box unchecked or skip the template altogether.
#
# Rules:
#   0. No issue type or form label -> close unless author is an org member
#   1. No checkboxes at all -> close unless author is an org member or bot
#   2. Checkboxes present but none checked -> close (skipped for org members)
#   3. "Submission checklist" section incomplete -> close (skipped for org members)
#   4. "Area" section missing or has no selection -> close (skipped for org members)
#
# Org membership check reuses the shared helper from pr-labeler.js and
# the same GitHub App used by tag-external-issues.yml.

name: Close Unchecked Issues

on:
  issues:
    types: [opened]

permissions:
  contents: read

concurrency:
  group: ${{ github.workflow }}-${{ github.event.issue.number }}
  cancel-in-progress: true

jobs:
  check-boxes:
    runs-on: ubuntu-latest
    permissions:
      contents: read
      issues: write

    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1

      - name: Generate GitHub App token
        id: app-token
        uses: actions/create-github-app-token@64ab729a6294000f5aa4a4bc0b73d1f32bc45510 # v3
        with:
          client-id: ${{ vars.ORG_MEMBERSHIP_APP_CLIENT_ID }}
          private-key: ${{ secrets.ORG_MEMBERSHIP_APP_PRIVATE_KEY }}

      - name: Validate issue checkboxes
        if: steps.app-token.outcome == 'success'
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          script: |
            const { owner, repo } = context.repo;
            const issue_number = context.payload.issue.number;
            const body = context.payload.issue.body ?? '';
            const allChecked = (body.match(/- \[x\]/gi) || []).length;
            const allUnchecked = (body.match(/- \[ \]/g) || []).length;
            const total = allChecked + allUnchecked;

            // ── Helpers ─────────────────────────────────────────────────
            // Extract checkboxes under a markdown H2/H3 heading.
            // Returns { checked, unchecked } counts, or null if the
            // section heading is not found in the body.
            function parseSection(heading) {
              const escaped = heading.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
              // Match the heading with or without a trailing " (Required)"
              // suffix — GitHub forms render the label verbatim, but
              // maintainers sometimes edit it out when polishing the body.
              const headingRe = new RegExp(
                `^#{2,3}\\s+${escaped}(?:\\s+\\(Required\\))?\\s*$`, 'm');
              const headingMatch = headingRe.exec(body);
              if (!headingMatch) return null;
              // Slice from after the heading to the next heading or end
              const rest = body.slice(headingMatch.index + headingMatch[0].length);
              const nextHeading = rest.search(/\n#{2,3}\s/);
              const block = nextHeading === -1 ? rest : rest.slice(0, nextHeading);
              return {
                checked: (block.match(/- \[x\]/gi) || []).length,
                unchecked: (block.match(/- \[ \]/g) || []).length,
              };
            }

            let _cachedMember;
            async function isOrgMember() {
              if (_cachedMember) return _cachedMember;
              const { h } = require('./.github/scripts/labeling/pr-labeler.js')
                .loadAndInit(github, owner, repo, core);
              const author = context.payload.sender.login;
              const { isExternal } = await h.checkMembership(
                author, context.payload.sender.type,
              );
              _cachedMember = { internal: !isExternal, author };
              return _cachedMember;
            }

            async function closeWithComment(lines) {
              const templateUrl = `https://github.com/${owner}/${repo}/issues/new/choose`;
              lines.push(
                '',
                `Please use one of the [issue templates](${templateUrl}).`,
              );

              // Post comment first so the author sees the reason even if
              // the subsequent close call fails.
              await github.rest.issues.createComment({
                owner, repo, issue_number,
                body: lines.join('\n'),
              });

              await github.rest.issues.update({
                owner, repo, issue_number,
                state: 'closed',
                state_reason: 'not_planned',
              });
            }

            // ── Rule 0: no issue type or form label (API/CLI bypass) ────
            // Web UI templates set either an issue type or a type label.
            // External users cannot set either via the API (requires
            // write/triage permissions), so missing both reliably indicates
            // programmatic submission.
            const formLabels = new Set(['type:bug', 'type:feature']);
            const hasFormLabel = context.payload.issue.labels?.some(
              (label) => formLabels.has(typeof label === 'string' ? label : label.name),
            );
            if (!context.payload.issue.type && !hasFormLabel) {
              // Transferred issues fire an "opened" event in this repo but
              // carry no issue type here, so check the timeline for a
              // `transferred` event instead of assuming programmatic
              // submission.
              let transferred = false;
              try {
                const events = await github.paginate(
                  github.rest.issues.listEventsForTimeline,
                  { owner, repo, issue_number, per_page: 100 },
                );
                transferred = events.some((e) => e.event === 'transferred');
              } catch (e) {
                core.warning(`Rule 0: timeline lookup failed, treating as not transferred: ${e.message}`);
              }
              if (transferred) {
                console.log('No issue type or form label, but issue has a `transferred` timeline event — skipping Rule 0');
              } else {
                let membership;
                try {
                  membership = await isOrgMember();
                } catch (e) {
                  // Org membership check failed — skip Rule 0 and let
                  // Rules 1-4 handle validation via checkboxes.
                  core.warning(`Rule 0: org membership check failed, skipping: ${e.message}`);
                }
                if (membership?.internal) {
                  console.log(`No issue type or form label, but ${membership.author} is internal — OK`);
                } else if (membership) {
                  console.log(`No issue type or form label and ${membership.author} is external — closing`);
                  await closeWithComment([
                    'This issue was automatically closed because it appears to have been submitted programmatically — the GitHub web interface applies an issue type or form label, and this issue has neither.',
                    '',
                    'We do not allow automated issue submission at this time.',
                  ]);
                  return;
                }
              }
            }

            // ── Rule 1: no checkboxes at all ────────────────────────────
            if (total === 0) {
              const { internal, author } = await isOrgMember();
              if (internal) {
                console.log(`No checkboxes, but ${author} is internal — OK`);
                return;
              }
              console.log(`No checkboxes and ${author} is external — closing`);
              await closeWithComment([
                'This issue was automatically closed because no issue template was used.',
              ]);
              return;
            }

            // ── Trust internal users for the remaining rules ───────────
            // Maintainers may edit headings or skip a checkbox; earlier
            // rules already short-circuit on membership, so mirror that
            // here instead of auto-closing their issues.
            try {
              const { internal, author } = await isOrgMember();
              if (internal) {
                console.log(`${author} is internal — skipping remaining rules`);
                return;
              }
            } catch (e) {
              core.warning(`Org membership check failed before section rules, continuing: ${e.message}`);
            }

            // ── Rule 2: checkboxes present but none checked ─────────────
            if (allChecked === 0) {
              console.log(`${allUnchecked} checkbox(es) present, none checked — closing`);
              await closeWithComment([
                'This issue was automatically closed because none of the required checkboxes were checked. Please re-file using an issue template and complete the checklist.',
              ]);
              return;
            }

            // ── Rules 3–4: parse sections for targeted feedback ─────────
            const checklist = parseSection('Submission checklist');
            const area = parseSection('Area');
            console.log(`Section parse — checklist: ${JSON.stringify(checklist)}, area: ${JSON.stringify(area)}`);

            const problems = [];

            if (checklist && checklist.unchecked > 0) {
              problems.push(
                'the submission checklist is incomplete — please confirm you searched for duplicates, included a reproduction, etc.'
              );
            }
            if (area !== null && area.checked === 0) {
              problems.push(
                'no package/area was selected (e.g. SDK, CLI, evals) — this helps us route the issue to the right team'
              );
            } else if (area === null) {
              problems.push(
                'the package/area selection is missing (e.g. SDK, CLI, evals) — this helps us route the issue to the right team'
              );
            }

            if (problems.length === 0) {
              console.log(`All section checks passed (${allChecked} checked) — OK`);
              return;
            }

            console.log(`Closing — problems: ${problems.join('; ')}`);
            await closeWithComment([
              'Thanks for opening an issue! It was automatically closed because:',
              '',
              ...problems.map(p => `- ${p}`),
            ]);

.github/workflows/pr_labeler.yml:
# Unified PR labeler — applies size, change-type, package/integration, and
# contributor classification labels in a single sequential workflow.
# Taxonomy: .github/LABELS.md.
#
# Consolidates pr_size_labeler.yml, pr_labeler_file.yml,
# pr_labeler_title.yml, and PR-handling from tag-external-issues.yml
# into one workflow to eliminate race conditions from concurrent label
# mutations. tag-external-issues.yml remains active for issue-only
# labeling. Backfill lives in pr_labeler_backfill.yml.
#
# Config and shared logic live in .github/scripts/labeling/pr-labeler-config.json
# and .github/scripts/labeling/pr-labeler.js — update those when adding
# partners. Nothing in this file hardcodes a scope, label, or threshold.
#
# Setup Requirements:
# 1. Create a GitHub App with permissions:
#    - Repository: Pull requests (write)
#    - Repository: Issues (write)
#    - Organization: Members (read)
# 2. Install the app on your organization and this repository
# 3. Add the repository credentials:
#    - Variable ORG_MEMBERSHIP_APP_CLIENT_ID: Your app's Client ID
#    - Secret ORG_MEMBERSHIP_APP_PRIVATE_KEY: Your app's private key
#
# The GitHub App token is required to check private organization membership
# and to propagate label events to downstream workflows.

name: "🏷️ PR Labeler"

on:
  # Safe since we only check out the base branch, not the PR's code.
  # NEVER CHECK OUT UNTRUSTED CODE FROM A PR's HEAD IN A pull_request_target JOB.
  # Doing so would allow attackers to execute arbitrary code in the context of your repository.
  pull_request_target:
    types: [opened, synchronize, reopened, edited]

permissions:
  contents: read

concurrency:
  # Separate opened events so external/tier labels are never lost to cancellation
  group: ${{ github.workflow }}-${{ github.event.pull_request.number || github.run_id }}-${{ github.event.action == 'opened' && 'opened' || 'update' }}
  cancel-in-progress: ${{ github.event.action != 'opened' }}

jobs:
  label:
    environment:
      name: labeling
      deployment: false
    runs-on: ubuntu-latest
    permissions:
      contents: read
      pull-requests: write
      issues: write

    steps:
      # Checks out the base branch (NOT the PR head) so that
      # require('./.github/scripts/labeling/pr-labeler.js') resolves.
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1

      - name: Generate GitHub App token
        if: github.event.action == 'opened'
        id: app-token
        uses: actions/create-github-app-token@64ab729a6294000f5aa4a4bc0b73d1f32bc45510 # v3
        with:
          client-id: ${{ vars.ORG_MEMBERSHIP_APP_CLIENT_ID }}
          private-key: ${{ secrets.ORG_MEMBERSHIP_APP_PRIVATE_KEY }}

      - name: Verify App token
        if: github.event.action == 'opened'
        run: |
          if [ -z "${{ steps.app-token.outputs.token }}" ]; then
            echo "::error::GitHub App token generation failed — cannot classify contributor"
            exit 1
          fi

      - name: Check org membership
        if: github.event.action == 'opened'
        id: check-membership
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          script: |
            const { owner, repo } = context.repo;
            const { h } = require('./.github/scripts/labeling/pr-labeler.js').loadAndInit(github, owner, repo, core);

            const author = context.payload.sender.login;
            const { isExternal } = await h.checkMembership(
              author, context.payload.sender.type,
            );
            core.setOutput('is-external', isExternal ? 'true' : 'false');

      # Rename package-component scopes to their canonical PR scopes for
      # non-release PRs. The alias map lives in
      # .github/scripts/labeling/pr-labeler-config.json ("scopeAliases");
      # release PRs (e.g. `release(deepagents): 1.2.0`) are left untouched
      # since their titles are canonical version records. Runs before labeling
      # so title-based labels read the corrected title.
      - name: Rename package component scopes
        id: rename-scope
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const { h } = require('./.github/scripts/labeling/pr-labeler.js').loadAndInit(github, owner, repo, core);

            const pr = context.payload.pull_request;
            if (!pr) {
              console.log('No pull_request in payload; skipping scope rename');
              return;
            }

            const title = pr.title ?? '';
            const renamed = h.canonicalizeTitleScopes(title);
            if (!renamed) {
              console.log(`Nothing to rename for title: "${title}"`);
              return;
            }

            console.log(`Renaming: "${title}" → "${renamed.title}"`);

            try {
              await github.rest.pulls.update({
                owner, repo, pull_number: pr.number, title: renamed.title,
              });
            } catch (error) {
              core.warning(
                `Failed to rename PR #${pr.number} title ` +
                `(${error.status ?? 'unknown'}): ${error.message}. ` +
                `Labeling will continue with the original title.`
              );
              return;
            }

            // Pass corrected title to the labeling step via output;
            // context.payload.pull_request.title is frozen from the
            // webhook event and won't reflect the API update.
            core.setOutput('title', renamed.title);

      - name: Apply PR labels
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          IS_EXTERNAL: ${{ steps.check-membership.outputs.is-external }}
          RENAMED_TITLE: ${{ steps.rename-scope.outputs.title }}
          TOPIC_CLASSIFIER_PROVIDER: ${{ vars.TOPIC_CLASSIFIER_PROVIDER }}
          GROQ_API_KEY: ${{ secrets.GROQ_API_KEY }}
          LANGSMITH_API_KEY: ${{ secrets.LANGSMITH_API_KEY }}
          LANGSMITH_WORKSPACE_ID: ${{ vars.LANGSMITH_WORKSPACE_ID }}
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const { h } = require('./.github/scripts/labeling/pr-labeler.js').loadAndInit(github, owner, repo, core);

            const pr = context.payload.pull_request;
            if (!pr) return;
            const prNumber = pr.number;
            const action = context.payload.action;

            const toAdd = new Set();
            const toRemove = new Set();

            const currentLabels = (await github.paginate(
              github.rest.issues.listLabelsOnIssue,
              { owner, repo, issue_number: prNumber, per_page: 100 },
            )).map(l => l.name ?? '');

            // ── Size + file labels (skip on 'edited' — files unchanged) ──
            if (action !== 'edited') {
              for (const sl of h.sizeLabels) await h.ensureLabel(sl);

              const files = await github.paginate(github.rest.pulls.listFiles, {
                owner, repo, pull_number: prNumber, per_page: 100,
              });

              const { totalChanged, sizeLabel } = h.computeSize(files);
              toAdd.add(sizeLabel);
              for (const sl of h.sizeLabels) {
                if (currentLabels.includes(sl) && sl !== sizeLabel) toRemove.add(sl);
              }
              console.log(`Size: ${totalChanged} changed lines → ${sizeLabel}`);

              for (const label of h.matchFileLabels(files)) {
                toAdd.add(label);
              }

              const topics = await h.getTopicFileLabels(prNumber, files, {
                before: action === 'synchronize' ? context.payload.before : null,
                head: pr.head?.sha, title: pr.title, body: pr.body,
              });
              for (const label of topics) {
                toAdd.add(label);
              }
            }

            // ── Branch-name-based labels ──
            // Branch ref doesn't change for an existing PR, so no removal logic.
            for (const label of h.matchBranchLabels(pr.head?.ref)) {
              toAdd.add(label);
            }

            // ── Title-based type, breaking, package, and integration labels ──
            // Use renamed title if the scope-rename step rewrote it,
            // since pr.title still reflects the pre-update value.
            const title = process.env.RENAMED_TITLE || pr.title || '';
            const { labels: titleLabels } = h.matchTitleLabels(title);
            for (const label of titleLabels) {
              toAdd.add(label);
            }
            for (const label of h.getStaleTitleLabels(title, currentLabels)) {
              toRemove.add(label);
            }

            // ── Internal label (only on open, non-external contributors) ──
            // IS_EXTERNAL is empty string on non-opened events (step didn't
            // run), so this guard is only true for opened + internal.
            if (action === 'opened' && process.env.IS_EXTERNAL === 'false') {
              toAdd.add('org:internal');
            }

            // ── Apply changes ──
            // Ensure all labels we're about to add exist (addLabels returns
            // 422 if any label in the batch is missing, which would prevent
            // ALL labels from being applied).
            for (const name of toAdd) {
              await h.ensureLabel(name);
            }

            for (const name of toRemove) {
              if (toAdd.has(name)) continue;
              try {
                await github.rest.issues.removeLabel({
                  owner, repo, issue_number: prNumber, name,
                });
              } catch (e) {
                if (e.status !== 404) throw e;
              }
            }

            const addList = [...toAdd];
            if (addList.length > 0) {
              await github.rest.issues.addLabels({
                owner, repo, issue_number: prNumber, labels: addList,
              });
            }

            const removed = [...toRemove].filter(r => !toAdd.has(r));
            console.log(`PR #${prNumber}: +[${addList.join(', ')}] -[${removed.join(', ')}]`);

      - name: Apply contributor tier label
        if: github.event.action == 'opened' && steps.check-membership.outputs.is-external == 'true'
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          script: |
            const { owner, repo } = context.repo;
            const { h } = require('./.github/scripts/labeling/pr-labeler.js').loadAndInit(github, owner, repo, core);

            const pr = context.payload.pull_request;
            await h.applyTierLabel(pr.number, pr.user.login);

      - name: Add external label
        if: github.event.action == 'opened' && steps.check-membership.outputs.is-external == 'true'
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          # Use App token so the "labeled" event propagates to downstream
          # workflows (e.g. require_issue_link.yml). Events created by the
          # default GITHUB_TOKEN do not trigger additional workflow runs.
          github-token: ${{ steps.app-token.outputs.token }}
          script: |
            const { owner, repo } = context.repo;
            const { h } = require('./.github/scripts/labeling/pr-labeler.js').loadAndInit(github, owner, repo, core);

            const prNumber = context.payload.pull_request.number;
            await h.ensureLabel('org:external');
            await github.rest.issues.addLabels({
              owner, repo,
              issue_number: prNumber,
              labels: ['org:external'],
            });
            console.log(`Added 'org:external' label to PR #${prNumber}`);

.github/workflows/pr_labeler_backfill.ym:
# Backfill PR labels on all open PRs.
#
# Manual-only workflow that applies the same labels as pr_labeler.yml
# (size, file, title, contributor classification) to existing open PRs.
# Reuses shared logic from .github/scripts/labeling/pr-labeler.js.

name: "🏷️ PR Labeler Backfill"

on:
  workflow_dispatch:
    inputs:
      max_items:
        description: "Maximum number of open PRs to process"
        default: "100"
        type: string

permissions:
  contents: read

jobs:
  backfill:
    runs-on: ubuntu-latest
    permissions:
      contents: read
      pull-requests: write
      issues: write

    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1

      - name: Generate GitHub App token
        id: app-token
        uses: actions/create-github-app-token@64ab729a6294000f5aa4a4bc0b73d1f32bc45510 # v3
        with:
          client-id: ${{ vars.ORG_MEMBERSHIP_APP_CLIENT_ID }}
          private-key: ${{ secrets.ORG_MEMBERSHIP_APP_PRIVATE_KEY }}

      # Fail before the loop, not once per PR. An empty token makes every
      # getContributorInfo() throw, and the per-PR catch would turn a total
      # outage into a wall of warnings. Mirrors pr_labeler.yml.
      - name: Verify App token
        run: |
          if [ -z "${{ steps.app-token.outputs.token }}" ]; then
            echo "::error::GitHub App token generation failed — cannot classify contributors"
            exit 1
          fi

      - name: Backfill labels on open PRs
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          script: |
            const { owner, repo } = context.repo;
            const rawMax = '${{ inputs.max_items }}';
            const maxItems = parseInt(rawMax, 10);
            if (isNaN(maxItems) || maxItems <= 0) {
              core.setFailed(`Invalid max_items: "${rawMax}" — must be a positive integer`);
              return;
            }

            const { config, h } = require('./.github/scripts/labeling/pr-labeler.js').loadAndInit(github, owner, repo, core);

            for (const name of [...h.sizeLabels, ...h.tierLabels]) {
              await h.ensureLabel(name);
            }

            const contributorCache = new Map();
            const fileRules = h.buildFileRules();

            const prs = await github.paginate(github.rest.pulls.list, {
              owner, repo, state: 'open', per_page: 100,
            });

            let processed = 0;
            let updated = 0;
            let failures = 0;
            for (const pr of prs) {
              if (processed >= maxItems) break;
              // Counted before the work, not after it: a PR that throws still
              // consumed an attempt, and leaving it uncounted let a run whose
              // every PR failed (an empty app token, say) walk the whole open
              // backlog while reporting `Processed 0`.
              processed++;
              try {
                const author = pr.user.login;
                const info = await h.getContributorInfo(contributorCache, author, pr.user.type);
                const labels = new Set();

                labels.add(info.isExternal ? 'org:external' : 'org:internal');
                // The merged-PR search failed, so we do not know this author's
                // tier. Leave their tier labels alone rather than reconciling
                // against an incomplete set, and count it as a failure so the
                // run goes red instead of reporting a clean migration.
                if (!info.tierKnown) {
                  failures++;
                  core.warning(
                    `PR #${pr.number}: contributor tier unknown for ${author} — leaving tier labels untouched`,
                  );
                }
                if (info.isExternal && info.mergedCount != null && info.mergedCount >= h.trustedThreshold) {
                  labels.add(h.tierLabelsByTier.trusted);
                } else if (info.isExternal && info.mergedCount === 0) {
                  labels.add(h.tierLabelsByTier.new);
                }

                // Size + file labels
                const files = await github.paginate(github.rest.pulls.listFiles, {
                  owner, repo, pull_number: pr.number, per_page: 100,
                });
                const { sizeLabel } = h.computeSize(files);
                labels.add(sizeLabel);

                for (const label of h.matchFileLabels(files, fileRules)) {
                  labels.add(label);
                }

                // Branch-name labels
                for (const label of h.matchBranchLabels(pr.head?.ref)) {
                  labels.add(label);
                }

                // Title labels
                const { labels: titleLabels } = h.matchTitleLabels(pr.title ?? '');
                for (const tl of titleLabels) labels.add(tl);

                // Ensure all labels exist before batch add
                for (const name of labels) {
                  await h.ensureLabel(name);
                }

                // Remove stale managed labels
                const currentLabels = (await github.paginate(
                  github.rest.issues.listLabelsOnIssue,
                  { owner, repo, issue_number: pr.number, per_page: 100 },
                )).map(l => l.name ?? '');

                const managed = info.tierKnown
                  ? [...h.sizeLabels, ...h.tierLabels]
                  : [...h.sizeLabels];
                const staleTitleLabels = h.getStaleTitleLabels(pr.title ?? '', currentLabels);
                for (const name of currentLabels) {
                  if ((managed.includes(name) || staleTitleLabels.includes(name)) && !labels.has(name)) {
                    try {
                      await github.rest.issues.removeLabel({
                        owner, repo, issue_number: pr.number, name,
                      });
                    } catch (e) {
                      if (e.status !== 404) throw e;
                    }
                  }
                }

                await github.rest.issues.addLabels({
                  owner, repo, issue_number: pr.number, labels: [...labels],
                });
                console.log(`PR #${pr.number} (${author}): ${[...labels].join(', ')}`);
                updated++;
              } catch (e) {
                failures++;
                core.warning(`Failed to process PR #${pr.number}: ${e.message}`);
              }
            }

            console.log(`\nBackfill complete. Scanned ${processed} PRs, updated ${updated}, ${failures} failures. ${contributorCache.size} unique authors.`);
            // Without this the job is green however many PRs threw, and this
            // is the workflow an operator runs to apply the taxonomy to the
            // existing backlog — a false success reads as "migration done".
            // Matches the backfill in sync_priority_labels.yml.
            if (failures > 0) {
              core.setFailed(`${failures} PR(s) failed to process — check warnings above`);
            }

.github/workflows/pr_lint.yml:
# PR title linting.
#
# FORMAT (Conventional Commits 1.0.0):
#
#   <type>(<scope>): <description>
#   [optional body]
#   [optional footer(s)]
#
# Examples:
#     feat(sdk): add multi‐agent support
#     fix(sdk): resolve flag parsing error
#     docs(sdk): update API usage examples
#
# Allowed Types:
#   * feat       — a new feature (MINOR)
#   * fix        — a bug fix (PATCH)
#   * docs       — documentation only changes
#   * style      — formatting, linting, etc.; no code change or typing refactors
#   * refactor   — code change that neither fixes a bug nor adds a feature
#   * perf       — code change that improves performance
#   * test       — adding tests or correcting existing
#   * build      — changes that affect the build system/external dependencies
#   * ci         — continuous integration/configuration changes
#   * chore      — other changes that don't modify source or test files
#   * revert     — reverts a previous commit
#   * release    — prepare a new release
#   * hotfix     — urgent fix that won't trigger a release
#
# Allowed Scope(s) (required):
#   acp, ci, code, daytona, dcode-gha, deepagents, deepagents-acp,
#   deepagents-code, deepagents-talon, deps, deps-dev, evals, examples, harbor, infra, langchain-daytona, langchain-modal,
#   langchain-quickjs, langchain-runloop, langchain-vercel-sandbox, langsmith-sandbox, modal,
#   quickjs, repo, runloop, sdk, talon, vercel
#
# Multiple scopes can be used by separating them with a comma.
#
# Rules:
#   1. The 'Type' must start with a lowercase letter.
#   2. Breaking changes: append "!" after type/scope (e.g., feat(sdk)!: drop x support)
#   3. When releasing (updating the pyproject.toml and uv.lock), the commit message
#      should be: `release(scope): x.y.z` (e.g., `release(deepagents): 1.2.0` with no
#      body, footer, or preceding/following text).
#
# Enforces Conventional Commits format for pull request titles to maintain a clear and
# machine-readable change history.

name: "🏷️ PR Title Lint"

permissions:
  pull-requests: read

on:
  pull_request:
    # `labeled`/`unlabeled` are required so the bypass-label warning comment
    # appears (or gets cleaned up) the moment a maintainer toggles
    # `ci:skip-title-lint`. Without them, the warning would only update on
    # the next title edit or push.
    types: [ opened, edited, synchronize, labeled, unlabeled ]

jobs:
  # Validates that PR title follows Conventional Commits 1.0.0 specification
  lint-pr-title:
    name: "validate format"
    runs-on: ubuntu-latest
    steps:
      - name: "🚫 Reject leading/trailing whitespace"
        env:
          PR_TITLE: ${{ github.event.pull_request.title }}
        run: |
          # The semantic-pull-request action reports a confusing "No release
          # type found" error when the title is otherwise valid but has
          # surrounding whitespace (e.g., " feat(sdk): ..."). Catch that here
          # with a clearer message before delegating to the action.
          trimmed="${PR_TITLE#"${PR_TITLE%%[![:space:]]*}"}"
          trimmed="${trimmed%"${trimmed##*[![:space:]]}"}"
          if [[ "$PR_TITLE" != "$trimmed" ]]; then
            echo "::error::PR title has leading or trailing whitespace: '$PR_TITLE'"
            echo "Edit the PR title to remove surrounding whitespace. Suggested title: '$trimmed'"
            exit 1
          fi
      - name: "🚫 Reject empty scope"
        env:
          PR_TITLE: ${{ github.event.pull_request.title }}
        run: |
          if [[ "$PR_TITLE" =~ ^[a-z]+\(\)[!]?: ]]; then
            echo "::error::PR title has empty scope parentheses: '$PR_TITLE'"
            echo "Either remove the parentheses or provide a scope (e.g., 'fix(sdk): ...')."
            exit 1
          fi
      - name: "✅ Validate Conventional Commits Format"
        uses: amannn/action-semantic-pull-request@48f256284bd46cdaab1048c3721360e808335d50 # v6
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
        with:
          types: |
            feat
            fix
            docs
            style
            refactor
            perf
            test
            build
            ci
            chore
            revert
            release
            hotfix
          scopes: |
            acp
            ci
            code
            dcode-gha
            daytona
            deepagents
            deepagents-acp
            deepagents-code
            deepagents-talon
            deps
            deps-dev
            evals
            examples
            harbor
            infra
            langchain-daytona
            langchain-modal
            langchain-quickjs
            langchain-runloop
            langchain-vercel-sandbox
            langsmith-sandbox
            modal
            quickjs
            repo
            runloop
            sdk
            talon
            vercel
          requireScope: true
          disallowScopes: |
            release
            [A-Z]+
          ignoreLabels: |
            ci:skip-title-lint

  # When a maintainer applies the `ci:skip-title-lint` label to bypass the
  # Conventional Commits check, post a sticky comment so the bypass is visible
  # to reviewers and to release-please consumers (a non-conventional title
  # typically means no changelog entry on merge, unless a
  # `BEGIN_COMMIT_OVERRIDE` block is supplied in the PR description). Removes
  # the comment when the label is taken off.
  warn-on-bypass:
    name: "warn on bypass label"
    runs-on: ubuntu-latest
    permissions:
      pull-requests: write
    # Serialize per-PR. Rapid label toggles or near-simultaneous
    # labeled/synchronize events can otherwise produce two concurrent runs
    # that both observe "no existing sticky" and both call `createComment`,
    # leaving a duplicate warning that the find-first update logic will
    # never reconcile.
    concurrency:
      group: pr-lint-bypass-${{ github.event.pull_request.number }}
      cancel-in-progress: true
    # Run when the bypass label is toggled, or on any other event while the
    # label is currently present (so opened/edited/synchronize keep the
    # comment in sync). The `unlabeled` branch is what triggers the cleanup
    # path — without it, removing the label would leave the warning comment
    # behind until the next title edit or push.
    if: >-
      (github.event.action == 'labeled' && github.event.label.name == 'ci:skip-title-lint') ||
      (github.event.action == 'unlabeled' && github.event.label.name == 'ci:skip-title-lint') ||
      contains(github.event.pull_request.labels.*.name, 'ci:skip-title-lint')
    steps:
      - name: "post or remove bypass-warning comment"
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request?.number;
            // Defensive guard — every supported trigger type carries a PR
            // payload, but a future trigger expansion (or a payload schema
            // drift) should fail with an actionable message rather than a
            // raw `TypeError: cannot read properties of undefined`.
            if (!prNumber) {
              core.setFailed('No PR number in payload — workflow may have triggered on an unexpected event type.');
              return;
            }
            const STICKY_MARKER = '<!-- pr-title-lint-bypass -->';
            const BYPASS_LABEL = 'ci:skip-title-lint';

            async function findStickyComment() {
              const comments = await github.paginate(github.rest.issues.listComments, {
                owner, repo, issue_number: prNumber, per_page: 100,
              });
              return comments.find(c => c.body && c.body.startsWith(STICKY_MARKER));
            }

            // Mirrors `postStickyOrSummary` in release_please_parse_check.yml.
            // Comment write paths can fail for several reasons that should
            // not turn this advisory job red: fork PRs run with restricted
            // tokens, secondary rate limits, transient API errors. Falling
            // back to `core.summary` keeps the bypass visible to a
            // maintainer who can paste it manually.
            async function postStickyOrSummary(commentBody, summaryHeading) {
              try {
                const existing = await findStickyComment();
                if (existing) {
                  if (existing.body !== commentBody) {
                    await github.rest.issues.updateComment({
                      owner, repo, comment_id: existing.id, body: commentBody,
                    });
                    console.log('Updated sticky warning comment');
                  } else {
                    console.log('Sticky warning comment already up to date');
                  }
                } else {
                  await github.rest.issues.createComment({
                    owner, repo, issue_number: prNumber, body: commentBody,
                  });
                  console.log('Posted sticky warning comment');
                }
              } catch (commentErr) {
                core.warning(`Could not post sticky comment (fork PR token, rate limit, or transient API error): ${commentErr.message}`);
                await core.summary
                  .addHeading(summaryHeading)
                  .addRaw('Paste the following into the PR as a comment:')
                  .addCodeBlock(commentBody, 'markdown')
                  .write();
              }
            }

            // Use live labels rather than the payload — the payload reflects
            // pre-event state on `labeled`/`unlabeled`, which would race the
            // sticky comment cleanup.
            let liveLabels;
            try {
              ({ data: liveLabels } = await github.rest.issues.listLabelsOnIssue({
                owner, repo, issue_number: prNumber,
              }));
            } catch (e) {
              throw new Error(`Failed to fetch live labels for PR #${prNumber}: ${e.message}`);
            }
            const labelPresent = liveLabels.some(l => l.name === BYPASS_LABEL);

            if (!labelPresent) {
              // Best-effort cleanup — a transient API failure on the green
              // "label removed" path must NOT flip this check to red.
              try {
                const existing = await findStickyComment();
                if (existing) {
                  await github.rest.issues.deleteComment({
                    owner, repo, comment_id: existing.id,
                  });
                  console.log('Bypass label removed — deleted sticky warning comment');
                }
              } catch (e) {
                core.warning(`Could not clean up sticky comment for PR #${prNumber}: ${e.message}`);
              }
              return;
            }

            const body = [
              STICKY_MARKER,
              '⚠️ **PR title Conventional Commits lint is being bypassed.**',
              '',
              `This PR carries the \`${BYPASS_LABEL}\` label, which tells the lint check to skip Conventional Commits validation on the title.`,
              '',
              '**Why this matters:** release-please parses the squash-merge message (title + body) to generate changelog entries. A non-conventional title typically means **no changelog entry will be generated** for this commit on release, unless a `BEGIN_COMMIT_OVERRIDE` block is supplied in the PR description.',
              '',
              'Reviewers: confirm the bypass is intentional. Remove the label to re-enable the check, or add a `BEGIN_COMMIT_OVERRIDE` block to the PR description so release-please still gets a parseable message.',
            ].join('\n');

            await postStickyOrSummary(
              body,
              'PR title lint bypass active; warning comment could not be posted',
            );

.github/workflows/pr_lint_trailer.yml:
# Pre-merge banned-trailer check.

name: "🏷️ PR trailer lint"

on:
  pull_request:
    types: [ opened, edited, synchronize, reopened ]

permissions:
  pull-requests: write

jobs:
  trailer-check:
    name: "validate PR has no banned trailers"
    runs-on: ubuntu-latest
    # Serialize per-PR. Rapid `edited`/`synchronize` events on a PR open can
    # otherwise produce two concurrent runs that both observe "no existing
    # sticky" and both call `createComment`, leaving a duplicate failure
    # comment that the find-first updater will never reconcile. We queue
    # (cancel-in-progress: false) rather than cancel, so the in-flight run
    # finishes its sticky write before the next event evaluates.
    concurrency:
      group: pr-trailer-lint-${{ github.event.pull_request.number }}
      cancel-in-progress: false
    steps:
      - name: Check PR and commit messages for banned trailer
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        # Bound the comment-write tail so a hung GitHub API call cannot leave
        # the check stuck "in progress" past the runner default. `core.setFailed`
        # is invoked before the sticky write, so the failure status is already
        # recorded if this timeout fires.
        timeout-minutes: 5
        with:
          script: |
            if (!context.payload.pull_request) {
              core.setFailed('No pull_request payload — workflow must run on pull_request events.');
              return;
            }
            const { title, body, number } = context.payload.pull_request;
            // The PR's total commit count, used to detect when GitHub's commit
            // list API returned fewer commits than the PR actually has.
            const prCommitCount = context.payload.pull_request.commits;
            // Normalize line endings — GitHub returns whatever the editor used,
            // and CRLF leaves stray \r chars in offending-line displays.
            const fullBody = (body || '').replace(/\r\n/g, '\n');
            const STICKY_MARKER = '<!-- pr-trailer-lint -->';

            // Mirrors the org ruleset regex on `main`. Keep in lock-step:
            // the live source of truth is the ruleset's `commit_message_pattern.pattern`
            // field at GitHub org settings → Rulesets → `block-anthropic-coauthor`
            // (or whichever ruleset blocks this trailer on `main`).
            // The pattern below is informational; verify against the live ruleset
            // when updating either side, or this check silently passes pushes
            // that the ruleset will then reject (defeating the entire purpose).
            //
            // Case-folding is intentionally narrow (`[Aa]`/`[Bb]`) because the
            // ruleset's pattern is narrow. Do NOT add the `i` flag — that would
            // catch cases the ruleset does not, surfacing false positives the
            // ruleset would let through.
            const BANNED_REGEX = /Co-[Aa]uthored-[Bb]y:.*<noreply@anthropic\.com>/;

            const squashMessage = `${title} (#${number})\n\n${fullBody}`;
            // GitHub's `pulls.listCommits` returns at most 250 commits for a PR
            // and gives no "there were more" signal, so scanning past this is
            // impossible via that endpoint. A PR with more commits is treated as
            // an incomplete scan (see `listPrCommits`) and fails closed.
            const MAX_COMMITS_TO_SCAN = 250;

            async function findStickyComment() {
              const comments = await github.paginate(github.rest.issues.listComments, {
                ...context.repo,
                issue_number: number,
                per_page: 100,
              });
              return comments.find(c => c.body && c.body.startsWith(STICKY_MARKER));
            }

            // Similar shape to `postStickyOrSummary` in
            // release_please_parse_check.yml, with an idempotency guard on
            // update (skip the API call when the body already matches).
            // Comment write paths can fail for several reasons that should not
            // turn this advisory job red on its own: fork PRs run with
            // restricted tokens, secondary rate limits, transient API errors.
            // Fall back to `core.summary` so a maintainer can paste the
            // remediation manually. The check still fails — `setFailed` is
            // invoked before this function, so the failure signal is already
            // recorded by the time the comment write is attempted.
            //
            // The try/catch wraps ONLY the write call so that a bug in
            // `findStickyComment` (e.g., pagination throwing) surfaces with
            // its true cause instead of being misattributed to "fork PR token".
            async function postStickyOrSummary(commentBody, summaryHeading) {
              const existing = await findStickyComment();
              try {
                if (existing) {
                  if (existing.body !== commentBody) {
                    await github.rest.issues.updateComment({
                      ...context.repo,
                      comment_id: existing.id,
                      body: commentBody,
                    });
                  }
                } else {
                  await github.rest.issues.createComment({
                    ...context.repo,
                    issue_number: number,
                    body: commentBody,
                  });
                }
              } catch (commentErr) {
                core.warning(`Could not post sticky comment (fork PR token, rate limit, or transient API error): ${commentErr.message}`);
                await core.summary
                  .addHeading(summaryHeading)
                  .addRaw('Paste the following into the PR as a comment:')
                  .addCodeBlock(commentBody, 'markdown')
                  .write();
              }
            }

            // Collect up to MAX_COMMITS_TO_SCAN commit objects for scanning.
            // `truncated` reports whether commits went unscanned, detected two
            // ways: we hit our own scan ceiling, or the PR's declared commit
            // count (`prCommitCount`) exceeds what the list API handed back
            // (GitHub caps that endpoint at 250). We compare counts rather than
            // trust "no next page", which cannot distinguish exactly-250 from
            // a silently-capped larger PR.
            async function listPrCommits() {
              const commits = [];
              for await (const response of github.paginate.iterator(github.rest.pulls.listCommits, {
                ...context.repo,
                pull_number: number,
                per_page: 100,
              })) {
                for (const commit of response.data) {
                  if (commits.length >= MAX_COMMITS_TO_SCAN) {
                    return { commits, truncated: true };
                  }
                  commits.push(commit);
                }
              }
              return {
                commits,
                truncated: typeof prCommitCount === 'number' && prCommitCount > commits.length,
              };
            }

            function findOffendingLines(source, text) {
              const lines = text.split('\n');
              const matches = [];
              for (let i = 0; i < lines.length; i++) {
                if (BANNED_REGEX.test(lines[i])) {
                  matches.push({ source, line: i + 1, text: lines[i] });
                }
              }
              return matches;
            }

            const offendingLines = findOffendingLines('squash merge message', squashMessage);

            // Fail closed if we cannot enumerate every commit. `listPrCommits`
            // may throw (rate limit, transient API error) or report truncation
            // (the PR has more commits than GitHub's list API returns). Either
            // way we cannot certify the PR clean, so route into the failure
            // branch below — carrying the real error message so the report is
            // not misattributed to PR size.
            let commits = [];
            let truncated = false;
            let listError = null;
            try {
              ({ commits, truncated } = await listPrCommits());
            } catch (listErr) {
              listError = listErr.message;
              truncated = true;
            }
            for (const commit of commits) {
              const sha = (commit.sha || '').slice(0, 12);
              const message = (commit.commit?.message || '').replace(/\r\n/g, '\n');
              offendingLines.push(...findOffendingLines(`commit ${sha}`, message));
            }

            // `!truncated` is load-bearing: an incomplete scan must NOT report
            // clean, because an unscanned commit could carry the trailer the
            // `main` ruleset will reject. Dropping it reopens that hole silently.
            if (offendingLines.length === 0 && !truncated) {
              core.info('No banned trailer in squash-merge message or PR commit messages.');
              // Mark any prior failure comment as resolved. We update rather
              // than delete because `deleteComment` 403s under restricted
              // fork-PR tokens, whereas `updateComment` on a bot-authored
              // comment works in both modes. Wrapped in try/catch because a
              // transient API failure during cleanup must NOT turn a green
              // check into red.
              try {
                const existing = await findStickyComment();
                if (existing) {
                  const resolvedBody = [
                    STICKY_MARKER,
                    '✅ **Trailer fixed.** The previous warning is resolved.',
                  ].join('\n');
                  if (existing.body !== resolvedBody) {
                    await github.rest.issues.updateComment({
                      ...context.repo,
                      comment_id: existing.id,
                      body: resolvedBody,
                    });
                  }
                }
              } catch (cleanupErr) {
                core.warning(`Check passed but could not update prior failure comment to resolved: ${cleanupErr.message}`);
              }
              return;
            }

            const offenseExcerpt = offendingLines
              .map(match => `${match.source}, line ${match.line}: ${match.text}`)
              .join('\n');
            const hasSquashMessageOffense = offendingLines.some(match => match.source === 'squash merge message');
            const hasCommitMessageOffense = offendingLines.some(match => match.source.startsWith('commit '));

            // Three mutually exclusive report modes, selected in priority order:
            //   1. squash-message offense — authoritative under a squash merge,
            //      so this definitively blocks merging to `main`.
            //   2. commit-only offense — dropped by a squash merge but pushed by
            //      a rebase/merge-commit, so it blocks only those merge methods.
            //   3. no offense but the scan was incomplete (truncated or list
            //      error) — fail closed; we cannot certify the PR is clean.
            let titleLine, intro, foundBlock, failureReason;
            if (hasSquashMessageOffense) {
              titleLine = '⚠️ **Banned trailer in PR — would block merging to `main`.**';
              intro = 'The squash-merge message (PR title + description) matches `Co-authored-by: ... <noreply@anthropic.com>`. An organization ruleset on `main` rejects any pushed commit whose message matches that pattern, so the PR cannot be merged until the trailer is removed.';
              foundBlock = offenseExcerpt;
              failureReason = `PR contains banned trailer matching ${BANNED_REGEX}`;
            } else if (hasCommitMessageOffense) {
              titleLine = '⚠️ **Banned trailer in a PR commit message.**';
              intro = 'An individual commit message matches `Co-authored-by: ... <noreply@anthropic.com>`. A squash merge drops individual commit messages, but a rebase or merge-commit pushes them to `main`, where an organization ruleset rejects any commit whose message matches that pattern. Remove the trailer so the PR can be merged by any method.';
              foundBlock = offenseExcerpt;
              failureReason = `PR contains banned trailer matching ${BANNED_REGEX}`;
            } else {
              titleLine = '⚠️ **Banned trailer check could not inspect every PR commit.**';
              intro = listError
                ? `The GitHub API call to list this PR's commits failed, so the workflow could not scan every commit message for the banned Claude Code co-author trailer: ${listError}`
                : `This PR has more than ${MAX_COMMITS_TO_SCAN} commits, so the workflow stopped before it could inspect every commit message for the banned Claude Code co-author trailer.`;
              foundBlock = listError
                ? 'The commit list could not be retrieved; no commit messages were scanned.'
                : `No matching trailer found in the first ${MAX_COMMITS_TO_SCAN} commits, but the PR has more commits than this workflow scans.`;
              failureReason = listError
                ? `Could not list PR commits to scan for banned trailer: ${listError}`
                : `Could not inspect every PR commit for banned trailer (scanned first ${MAX_COMMITS_TO_SCAN} of ${prCommitCount})`;
            }

            const fixLines = [];
            if (hasSquashMessageOffense) {
              fixLines.push('If the trailer appears in the squash merge message, edit the PR description and remove the offending line(s).');
            }
            if (hasCommitMessageOffense) {
              fixLines.push('If the trailer appears in an individual commit, rewrite that commit message to remove the offending line.');
            }
            if (truncated && !listError) {
              fixLines.push(`This workflow scanned only the first ${MAX_COMMITS_TO_SCAN} commits because GitHub's pull request commit API returns at most that many. Ask a maintainer to inspect the remaining commits before merging.`);
            }
            if (listError) {
              fixLines.push('This is usually a transient rate-limit or API error — re-run the check. If it persists, a maintainer should verify the commit messages manually before merging.');
            }

            const commentBody = [
              STICKY_MARKER,
              titleLine,
              '',
              intro,
              '',
              '**Found:**',
              '```',
              foundBlock,
              '```',
              '',
              '### Fix',
              '',
              ...fixLines,
            ].join('\n');

            // Set the failure signal BEFORE the sticky write — if the comment
            // API hangs, the runner-level timeout fires with the failure
            // status already recorded. Reversing the order leaves the check
            // stuck "in progress" instead of red.
            core.setFailed(failureReason);
            await postStickyOrSummary(
              commentBody,
              'Banned trailer in PR; comment could not be posted',
            );

.github/workflows/pr_scope_file_check.ym:
# Pre-merge blocking check for PR title package scopes vs touched package dirs.
#
# Why this exists:
#   PR titles use Conventional Commit scopes, and those scopes drive release notes,
#   package labels, and reviewer expectations. A title like `fix(cli): ...` should
#   not describe a PR whose only package edits live under `libs/code/`. This check
#   compares package scopes from the PR title with package directories from the
#   changed-file list, posts a sticky warning when they disagree, and FAILS the
#   check so the mismatch is fixed before merge.
#
# Bypasses:
#   - `release(...)` PR titles pass only when every changed file matches a
#     release-please generated/version-file pattern. Release-please PRs can touch
#     those files across package dirs.
#   - Apply the `ci:allow-scope-mismatch` label when another mismatch is intentional.
#     The check re-runs on `labeled`/`unlabeled`, leaves an informational sticky
#     note, and passes while the label is present.
#
# To actually gate merges, add this check to the branch's required status checks.
#
# How it stays faithful to existing repo configuration:
#   - Scope -> package and dir -> package mappings are read from
#     .github/scripts/labeling/pr-labeler-config.json by the helper script — see
#     .github/scripts/labeling/check_pr_scope_files.py.
#
# Trust model:
#   - The detector and labeler config run from the PR *base* revision, not the
#     PR head, so a PR cannot edit *those* to self-bypass the gate. Only the PR
#     title (event payload) and changed-file list (API) come from the PR.
#   - This base checkout closes the detector/config edit vector but does not by
#     itself make the gate un-bypassable: under `pull_request` the workflow file
#     itself is taken from the PR head, so a PR that edits this workflow can
#     still neuter the check. Gate integrity therefore also relies on branch
#     protection (this job as a required status check) and review of
#     `.github/workflows/` edits.
#   - The `release(...)` bypass is title-driven, so it rests on the same
#     author-controlled title input — but it cannot be abused because it
#     requires *every* changed file to match a release-please artifact pattern
#     (see `is_release_file`); a single source file re-arms the gate. The
#     detector emits a `::notice::` when the bypass fires so the stood-down gate
#     is visible in the Checks UI rather than silent.
#
# Limitations:
#   - Runs under `pull_request` (not `pull_request_target`), so PRs from forks get
#     the read-only token and the comment is surfaced to the job summary instead.
#     No secrets are exposed to PR-author-controlled code.
#   - The detector and config run from base, so a PR that itself *adds* a new
#     package directory (and its labeler `fileRules`/`scopeToLabel` entries) is
#     checked against the base config that does not yet know that package: a
#     scope/file mismatch for the just-added package dir is not flagged until the
#     rule exists on base. Reading head config instead would reopen the
#     self-bypass the base checkout closes, so this is the deliberate tradeoff;
#     the next PR touching the package is gated normally.

name: "🔍 PR scope file check"

on:
  pull_request:
    # `labeled`/`unlabeled` so applying the bypass label re-runs the check and
    # clears the red without needing a new commit.
    types: [opened, edited, synchronize, reopened, labeled, unlabeled]

permissions:
  contents: read
  pull-requests: write

jobs:
  scope-file-check:
    name: "validate title scope covers package dirs"
    runs-on: ubuntu-latest
    timeout-minutes: 3
    steps:
      - name: "📋 Checkout base revision"
        # Check out the PR *base* (trusted), never the PR head. The detector and
        # labeler config are executed from this tree, so the PR under test cannot
        # edit check_pr_scope_files.py or pr-labeler-config.json to print "[]" and
        # self-bypass the gate — defeating it for the exact PRs it must block. The
        # PR title (event payload) and changed-file list (API) are fed in
        # separately and are authoritative regardless of this checkout.
        #
        # `persist-credentials: false` so the job token is not written into the
        # checkout's git config; the detector needs no git credentials, and the
        # github-script steps receive their own token directly.
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ github.event.pull_request.base.sha }}
          persist-credentials: false

      - name: "🐍 Setup Python 3.11"
        uses: actions/setup-python@6d4fd22b20465ccc0f7354476588e8df7c9ca0e0 # v7.1.0
        with:
          python-version: "3.11"

      - name: "Collect changed files"
        # Use the API rather than `git diff` so the changed-file list is
        # authoritative regardless of checkout depth. Newline-delimited to
        # changed_files.txt, which the detector reads from stdin.
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const fs = require('fs');
            const files = await github.paginate(github.rest.pulls.listFiles, {
              ...context.repo,
              pull_number: context.payload.pull_request.number,
              per_page: 100,
            });
            // listFiles is hard-capped by GitHub at 3000 files regardless of
            // pagination. A truncated list could hide a package dir mismatch or
            // create a false one, so fail closed if the collected count doesn't
            // match the PR's reported total.
            const expected = context.payload.pull_request.changed_files;
            // Without a numeric reported total we cannot verify completeness, so
            // fail closed rather than proceeding on a possibly-truncated list.
            if (typeof expected !== 'number') {
              core.setFailed(`PR payload missing numeric changed_files (got ${JSON.stringify(expected)}); cannot verify the changed-file list is complete. Failing closed.`);
              return;
            }
            if (files.length !== expected) {
              core.setFailed(`Changed-file list is incomplete (${files.length} of ${expected}); cannot determine PR scope/file alignment reliably. Failing closed.`);
              return;
            }
            fs.writeFileSync('changed_files.txt', files.map(f => f.filename).join('\n'));
            core.info(`Collected ${files.length} changed file(s).`);

      - name: "Detect package scope/file mismatch"
        id: detect
        # PR title is passed via env (never interpolated into the script body)
        # to avoid shell injection from PR-author-controlled text.
        env:
          PR_TITLE: ${{ github.event.pull_request.title }}
        run: |
          set -euo pipefail
          # Preferred nested path ships on this PR; until that lands on base,
          # fall back to the flat layout so the gate still enforces.
          detector=".github/scripts/labeling/check_pr_scope_files.py"
          legacy_detector=".github/scripts/check_pr_scope_files.py"
          if [[ ! -f "$detector" && -f "$legacy_detector" ]]; then
            detector="$legacy_detector"
          fi
          if [[ ! -f "$detector" ]]; then
            # The detector does not exist on the base revision: the bootstrapping
            # PR that first introduces this check, or a branch cut from before it
            # existed. There is no trusted gate on base to enforce, so treat as
            # clean. This is not a self-bypass vector: presence is read from
            # trusted base, and an author cannot strip the detector from a base
            # that has it (head edits never change base). An author *can* target
            # an old base that never had it, but gains nothing — that base never
            # gated anything, so there is nothing to evade.
            #
            # The residual risk is operator error, not attack: if the detector is
            # renamed/moved on base without updating the path above, this branch
            # silently disables the gate. Emit a *warning* (not a notice) so the
            # desync surfaces in the Checks UI rather than only the fold-out log.
            echo "::warning::Detector '$detector' absent on base revision; scope/file check is NOT enforcing. Expected only on the bootstrapping PR or a pre-gate branch — otherwise the detector path here may be out of sync with the repo."
            offenders="[]"
          else
            # A config-read error in the detector exits non-zero; under `set -e`
            # the command substitution propagates it and this step fails, so the
            # comment step (default `if: success()`) is skipped — fail closed.
            offenders=$(python "$detector" "$PR_TITLE" < changed_files.txt)
          fi
          # Heredoc form so a multi-line value can never corrupt $GITHUB_OUTPUT.
          {
            echo "offenders<<__SCOPE_FILE_EOF__"
            echo "$offenders"
            echo "__SCOPE_FILE_EOF__"
          } >> "$GITHUB_OUTPUT"
          echo "Detector offenders: $offenders"

      - name: "Comment on package scope/file mismatch"
        # Offenders passed via env (not interpolated into the script body) for
        # the same injection-safety reason as the title above.
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          OFFENDERS: ${{ steps.detect.outputs.offenders }}
        with:
          script: |
            const STICKY_MARKER = '<!-- pr-scope-file-check -->';
            const BYPASS_LABEL = 'ci:allow-scope-mismatch';
            const { title, number, labels } = context.payload.pull_request;

            // Strict, fail-closed parse. The detector always prints a JSON array
            // ("[]" when clean), so empty or non-array output means the detector
            // didn't run as expected — block rather than silently coerce a
            // missing result into "no offenders → pass."
            const raw = process.env.OFFENDERS;
            if (raw === undefined || raw.trim() === '') {
              core.setFailed('Detector produced no output; cannot determine PR scope/file alignment. Failing closed.');
              return;
            }
            let offenders;
            try {
              offenders = JSON.parse(raw);
            } catch (parseErr) {
              core.setFailed(`Detector output was not valid JSON: ${JSON.stringify(raw)} (${parseErr.message})`);
              return;
            }
            if (!Array.isArray(offenders)) {
              core.setFailed(`Detector output was not a JSON array: ${JSON.stringify(raw)}`);
              return;
            }
            for (const offender of offenders) {
              if (!offender || typeof offender !== 'object' || typeof offender.package !== 'string' || !Array.isArray(offender.dirs) || offender.dirs.some(d => typeof d !== 'string')) {
                core.setFailed(`Detector output contained an invalid offender object: ${JSON.stringify(offender)}`);
                return;
              }
            }

            // Constant string comparison against the structured label payload —
            // no PR-author-controlled text reaches a code path.
            const bypassed = (labels || []).some(l => l.name === BYPASS_LABEL);

            // Display-only: this re-parses the title solely to render the
            // scope list in the sticky comment. The pass/fail decision comes
            // entirely from the detector's JSON offenders, not from here. Keep
            // this regex in sync with `_TITLE_RE` in check_pr_scope_files.py.
            const titleScopes = (() => {
              const match = title.match(/^[a-z]+(?:\(([^)]*)\))?!?:\s/);
              if (!match || !match[1]) {
                return [];
              }
              return match[1].split(',').map(s => s.trim()).filter(Boolean);
            })();
            const scopeList = titleScopes.length > 0
              ? titleScopes.map(s => `\`${s}\``).join(', ')
              : '_none parsed_';

            const offenderLines = offenders.map(o => {
              const dirs = o.dirs.map(d => `\`${d}\``).join(', ');
              return `- package label \`${o.package}\` from ${dirs}`;
            }).join('\n');
            const offenderSummary = offenders.map(o => `${o.package} (${o.dirs.join(', ')})`).join(', ');

            async function findStickyComment() {
              const comments = await github.paginate(github.rest.issues.listComments, {
                ...context.repo,
                issue_number: number,
                per_page: 100,
              });
              return comments.find(c => c.body && c.body.startsWith(STICKY_MARKER));
            }

            async function deleteSticky() {
              const existing = await findStickyComment();
              if (existing) {
                await github.rest.issues.deleteComment({ ...context.repo, comment_id: existing.id });
              }
            }

            async function upsertSticky(body) {
              try {
                const existing = await findStickyComment();
                if (existing) {
                  await github.rest.issues.updateComment({ ...context.repo, comment_id: existing.id, body });
                } else {
                  await github.rest.issues.createComment({ ...context.repo, issue_number: number, body });
                }
              } catch (commentErr) {
                // Fork PRs run with a restricted token; surface to the job
                // summary so the mismatch is still visible alongside the red check.
                core.warning(`Could not post sticky comment (fork PR token, rate limit, or transient API error) [status=${commentErr.status ?? 'n/a'}]: ${commentErr.message}`);
                // Guard the summary write too: if it throws (unwritable summary,
                // size limit) it must not escape upsertSticky and preempt the
                // caller's core.setFailed — the red check is the load-bearing signal.
                try {
                  await core.summary
                    .addHeading('PR scope/file mismatch')
                    .addRaw(body)
                    .write();
                } catch (summaryErr) {
                  core.warning(`Could not write job summary fallback [status=${summaryErr.status ?? 'n/a'}]: ${summaryErr.message}`);
                }
              }
            }

            if (offenders.length === 0) {
              // Resolved: clear any stale comment and pass. Wrapped so a cleanup
              // hiccup can't turn a clean result red.
              try {
                await deleteSticky();
              } catch (cleanupErr) {
                core.warning(`Could not clean up prior scope/file-check comment (stale comment may persist on a now-passing PR) [status=${cleanupErr.status ?? 'n/a'}]: ${cleanupErr.message}`);
              }
              core.info('No PR scope/file mismatch detected.');
              return;
            }

            if (bypassed) {
              // Acknowledged as intentional via the bypass label: leave an
              // informational note (not a failure) and pass.
              await upsertSticky([
                STICKY_MARKER,
                `ℹ️ **PR scope/file mismatch acknowledged** via the \`${BYPASS_LABEL}\` label.`,
                '',
                `Title scope(s): ${scopeList}`,
                '',
                'Touched package dir(s) not covered by those scopes:',
                offenderLines,
                '',
                '**Release-please consequence:** if this PR title is bump-worthy (`feat`/`fix`/etc.), release-please scopes by **changed file path**, not the title scope — so it can still open a **separate release PR for every managed component this PR touches**, even when the title names only one package. Prefer splitting into one package-scoped feature/fix PR and one `chore(deps):` PR for cross-package churn.',
                '',
                'Remove the label to re-enable the block.',
                '',
                '📖 [Multi-component fan-out](https://github.com/langchain-ai/deepagents/blob/main/.github/RELEASING.md#multi-component-fan-out)',
              ].join('\n'));
              core.info(`Bypassed via ${BYPASS_LABEL} label.`);
              return;
            }

            await upsertSticky([
              STICKY_MARKER,
              '⛔ **This PR title scope does not match the package directory it changes.**',
              '',
              `Title scope(s): ${scopeList}`,
              '',
              'Touched package dir(s) not covered by those scopes:',
              offenderLines,
              '',
              'This check is **blocking** because the PR title declares one package scope while the changed files live in a different package directory.',
              '',
              '**Release-please consequence:** release-please attributes commits by **file path**, not title scope. A bump-worthy title (`feat`/`fix`/etc.) that touches multiple managed packages opens a **separate release PR per package**. Bypassing this gate does **not** stop that fan-out.',
              '',
              '### To resolve',
              '',
              'Edit the PR title scope so it covers the changed package directory (for example, use `fix(code): ...` for `libs/code/**`), or move the files so they match the declared scope.',
              '',
              'If this is a feature plus incidental cross-package dependency/lock churn, split into:',
              '',
              '1. One feature/fix PR scoped to the single package that owns the user-facing change.',
              '2. One `chore(deps): ...` PR for the cross-package dependency / lockfile churn (`chore` is hidden and does not open release PRs).',
              '',
              '### If intentional',
              '',
              `Apply the \`${BYPASS_LABEL}\` label. The check re-runs and passes with an informational note — confirm you still want a release PR for every managed component the diff touches.`,
              '',
              '📖 [Multi-component fan-out](https://github.com/langchain-ai/deepagents/blob/main/.github/RELEASING.md#multi-component-fan-out)',
            ].join('\n'));
            core.setFailed(`PR title scope(s) ${titleScopes.join(', ') || '(none)'} do not cover touched package dir(s): ${offenderSummary}. Fix the title scope/files, or apply the '${BYPASS_LABEL}' label if intentional.`);

.github/workflows/release_fanout_bypass_:
# Loud advisory when a maintainer acknowledges a release-related fan-out gate
# by applying `ci:allow-lockfile-release` or `ci:allow-scope-mismatch`.
#
# Mirrors the `warn-on-bypass` job in `pr_lint.yml` (for `ci:skip-title-lint`):
# post a sticky that spells out the release-please consequence and lists every
# managed component the PR's changed files touch. Cleanup when the label is
# removed.
#
# This job is advisory: it never fails the check. The load-bearing red / green
# decision still lives in `release_please_scope_check.yml` and
# `pr_scope_file_check.yml`.

name: "⚠️ Release fan-out bypass warning"

on:
  pull_request:
    types: [opened, edited, synchronize, reopened, labeled, unlabeled]

permissions:
  contents: read
  pull-requests: write

jobs:
  warn-on-fanout-bypass:
    name: "warn on release fan-out bypass label"
    runs-on: ubuntu-latest
    timeout-minutes: 3
    # Serialize per-PR so rapid label toggles cannot create duplicate stickies.
    concurrency:
      group: release-fanout-bypass-${{ github.event.pull_request.number }}
      cancel-in-progress: true
    # Run when either bypass label is toggled, or on any other PR event while
    # one of the labels is currently present (so opened/edited/synchronize keep
    # the comment in sync).
    if: >-
      (github.event.action == 'labeled' &&
        (github.event.label.name == 'ci:allow-lockfile-release' ||
         github.event.label.name == 'ci:allow-scope-mismatch')) ||
      (github.event.action == 'unlabeled' &&
        (github.event.label.name == 'ci:allow-lockfile-release' ||
         github.event.label.name == 'ci:allow-scope-mismatch')) ||
      contains(github.event.pull_request.labels.*.name, 'ci:allow-lockfile-release') ||
      contains(github.event.pull_request.labels.*.name, 'ci:allow-scope-mismatch')
    steps:
      - name: "📋 Checkout base revision"
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ github.event.pull_request.base.sha }}
          persist-credentials: false

      - name: "🐍 Setup Python 3.11"
        uses: actions/setup-python@6d4fd22b20465ccc0f7354476588e8df7c9ca0e0 # v7.1.0
        with:
          python-version: "3.11"

      - name: "Collect changed files"
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const fs = require('fs');
            const files = await github.paginate(github.rest.pulls.listFiles, {
              ...context.repo,
              pull_number: context.payload.pull_request.number,
              per_page: 100,
            });
            const expected = context.payload.pull_request.changed_files;
            if (typeof expected !== 'number' || files.length !== expected) {
              core.warning(
                `Changed-file list incomplete or missing total ` +
                `(got ${files.length}, expected ${JSON.stringify(expected)}); ` +
                `component list may be incomplete.`
              );
            }
            fs.writeFileSync('changed_files.txt', files.map(f => f.filename).join('\n'));
            core.info(`Collected ${files.length} changed file(s).`);

      - name: "Detect touched components"
        id: detect
        env:
          PR_TITLE: ${{ github.event.pull_request.title }}
        run: |
          set -euo pipefail
          # Preferred nested path ships on this PR; until that lands on base,
          # fall back to the flat layout so the gate still enforces.
          detector=".github/scripts/release/list_touched_release_components.py"
          legacy_detector=".github/scripts/list_touched_release_components.py"
          if [[ ! -f "$detector" && -f "$legacy_detector" ]]; then
            detector="$legacy_detector"
          fi
          if [[ ! -f "$detector" ]]; then
            echo "::warning::Detector '$detector' absent on base; cannot list components."
            components='[]'
            bump_worthy='false'
          else
            # Title is env-passed into argv, never shell-interpolated into code.
            result=$(python "$detector" "$PR_TITLE" < changed_files.txt)
            components=$(python -c 'import json,sys; print(json.dumps(json.loads(sys.argv[1])["components"]))' "$result")
            bump_worthy=$(python -c 'import json,sys; print("true" if json.loads(sys.argv[1])["bump_worthy"] else "false")' "$result")
          fi
          {
            echo "components<<__COMP_EOF__"
            echo "$components"
            echo "__COMP_EOF__"
            echo "bump_worthy=$bump_worthy"
          } >> "$GITHUB_OUTPUT"

      - name: "post or remove bypass-warning comment"
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          COMPONENTS: ${{ steps.detect.outputs.components }}
          BUMP_WORTHY: ${{ steps.detect.outputs.bump_worthy }}
        with:
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request?.number;
            if (!prNumber) {
              core.setFailed('No PR number in payload — workflow may have triggered on an unexpected event type.');
              return;
            }
            const STICKY_MARKER = '<!-- release-fanout-bypass-warn -->';
            const LABELS = ['ci:allow-lockfile-release', 'ci:allow-scope-mismatch'];

            async function findStickyComment() {
              const comments = await github.paginate(github.rest.issues.listComments, {
                owner, repo, issue_number: prNumber, per_page: 100,
              });
              return comments.find(c => c.body && c.body.startsWith(STICKY_MARKER));
            }

            async function postStickyOrSummary(commentBody, summaryHeading) {
              try {
                const existing = await findStickyComment();
                if (existing) {
                  if (existing.body !== commentBody) {
                    await github.rest.issues.updateComment({
                      owner, repo, comment_id: existing.id, body: commentBody,
                    });
                    console.log('Updated sticky warning comment');
                  } else {
                    console.log('Sticky warning comment already up to date');
                  }
                } else {
                  await github.rest.issues.createComment({
                    owner, repo, issue_number: prNumber, body: commentBody,
                  });
                  console.log('Posted sticky warning comment');
                }
              } catch (commentErr) {
                core.warning(`Could not post sticky comment (fork PR token, rate limit, or transient API error): ${commentErr.message}`);
                await core.summary
                  .addHeading(summaryHeading)
                  .addRaw('Paste the following into the PR as a comment:')
                  .addCodeBlock(commentBody, 'markdown')
                  .write();
              }
            }

            // Use live labels rather than the payload — the payload reflects
            // pre-event state on `labeled`/`unlabeled`, which would race the
            // sticky comment cleanup.
            let liveLabels;
            try {
              ({ data: liveLabels } = await github.rest.issues.listLabelsOnIssue({
                owner, repo, issue_number: prNumber,
              }));
            } catch (e) {
              throw new Error(`Failed to fetch live labels for PR #${prNumber}: ${e.message}`);
            }
            const active = liveLabels
              .map(l => l.name)
              .filter(n => LABELS.includes(n));

            if (active.length === 0) {
              try {
                const existing = await findStickyComment();
                if (existing) {
                  await github.rest.issues.deleteComment({
                    owner, repo, comment_id: existing.id,
                  });
                  console.log('Bypass label(s) removed — deleted sticky warning comment');
                }
              } catch (e) {
                core.warning(`Could not clean up sticky comment for PR #${prNumber}: ${e.message}`);
              }
              return;
            }

            let components = [];
            try {
              const parsed = JSON.parse(process.env.COMPONENTS || '[]');
              if (Array.isArray(parsed)) {
                components = parsed.filter(c => typeof c === 'string');
              }
            } catch (_) {
              components = [];
            }
            const bumpWorthy = process.env.BUMP_WORTHY === 'true';
            const componentList = components.length
              ? components.map(c => `\`${c}\``).join(', ')
              : '_none detected under managed package paths_';
            const labelList = active.map(l => `\`${l}\``).join(', ');

            const body = [
              STICKY_MARKER,
              '⚠️ **A release fan-out gate was bypassed.**',
              '',
              `Active bypass label(s): ${labelList}`,
              '',
              '**Consequence:** release-please will open a **separate release PR for every managed component this PR touches**, because it scopes commits by **changed file path** (not by title scope alone).',
              '',
              `Touched release-please component(s): ${componentList}`,
              '',
              bumpWorthy
                ? 'This PR title is currently **bump-worthy** (`feat`/`fix`/visible type or `!`), so fan-out is live on merge.'
                : 'This PR title does **not** currently look bump-worthy. Fan-out still matters if the squash-merge subject is later rewritten to a bump-worthy type (or a `BEGIN_COMMIT_OVERRIDE` block makes it one).',
              '',
              '### Confirm intentional, or split',
              '',
              'Prefer:',
              '',
              '1. One feature/fix PR scoped to the **single** package that owns the user-facing change.',
              '2. One `chore(deps): ...` PR for cross-package dependency / lockfile churn (`chore` is hidden and does not open release PRs).',
              '',
              'Remove the bypass label(s) to re-enable the blocking checks.',
              '',
              '📖 [Multi-component fan-out](https://github.com/langchain-ai/deepagents/blob/main/.github/RELEASING.md#multi-component-fan-out)',
              '📖 [Lockfile churn fan-out](https://github.com/langchain-ai/deepagents/blob/main/.github/RELEASING.md#lockfile-churn-fan-out)',
              '📖 [Reverting a merged-but-unreleased PR](https://github.com/langchain-ai/deepagents/blob/main/.github/RELEASING.md#reverting-a-merged-but-unreleased-pr)',
            ].join('\n');

            await postStickyOrSummary(
              body,
              'Release fan-out bypass active; warning comment could not be posted',
            );

.github/workflows/release_notes.yml:
# Draft and apply curated release notes for any ready release-please release PR.
# The package under release is derived from the PR head ref, so every component in
# release-please-config.json is covered.
# All automation runs from a trusted `main` checkout (`trusted-source`); the ambient
# GITHUB_TOKEN is read-only for contents. Release PR content is read only through
# GitHub's API at the validated commit SHA and treated as untrusted data; it is
# never checked out or executed. Drafting is a single request to a fixed model API:
# untrusted text is never given filesystem, shell, or network tools, and only the
# selected provider key is present in that process. Repository mutations —
# curated-notes comments, PR-body updates, and a
# non-force Git Data API update to the release-please branch — are performed only by
# specific helper steps that receive a short-lived GitHub App token. (The validate job's
# permission/readiness feedback comments use the default GITHUB_TOKEN.)

name: "📝 Curate release notes"

on:
  pull_request_target:
    types: [ready_for_review]
  issue_comment:
    types: [created]

permissions:
  contents: read

concurrency:
  group: release-notes-${{ github.event.pull_request.number || github.event.issue.number }}
  cancel-in-progress: false

jobs:
  validate:
    name: Validate release-notes command
    # Skip the noise: run only for ready_for_review PR events, or PR comments that
    # mention the bot AND come from a repo insider. The author_association filter
    # stops an external drive-by mention from spawning a run (Actions-minute burn)
    # and mirrors the in-script FEEDBACK_ASSOCIATIONS gate; validateTrigger still
    # re-checks the exact command and write permission, so this only drops comments
    # that could never have triggered an action.
    if: >-
      github.event_name == 'pull_request_target' ||
      (github.event.issue.pull_request &&
        contains(github.event.comment.body, '@release-bot') &&
        contains(fromJSON('["OWNER","MEMBER","COLLABORATOR"]'), github.event.comment.author_association))
    runs-on: ubuntu-latest
    timeout-minutes: 5
    permissions:
      contents: read
      issues: write
      pull-requests: read
    outputs:
      should-run: ${{ steps.validate.outputs.should-run }}
      command: ${{ steps.validate.outputs.command }}
      instructions: ${{ steps.validate.outputs.instructions }}
      number: ${{ steps.validate.outputs.number }}
      component: ${{ steps.validate.outputs.component }}
      version: ${{ steps.validate.outputs.version }}
      head: ${{ steps.validate.outputs.head }}
      branch: ${{ steps.validate.outputs.branch }}
    steps:
      - name: Checkout trusted automation
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: main
          path: trusted-source
          persist-credentials: false

      - name: Validate event, PR, and maintainer permission
        id: validate
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          BOT_LOGIN: ${{ vars.RELEASE_BOT_LOGIN }}
          BOT_ID: ${{ vars.RELEASE_BOT_ID }}
        with:
          script: |
            const { validateTrigger } = require('./trusted-source/.github/scripts/release/release-notes.js');
            const result = await validateTrigger({
              github,
              context,
              core,
              botLogin: process.env.BOT_LOGIN,
              botId: process.env.BOT_ID,
            });
            core.setOutput('should-run', String(result.shouldRun === true));
            for (const key of ['command', 'instructions', 'number', 'component', 'version', 'head', 'branch']) {
              core.setOutput(key, result[key] ?? '');
            }

      # A transient error while validating an insider's manual @release-bot
      # command would otherwise leave only a red job in the Actions tab; surface it
      # on the PR so the maintainer who ran the command knows to retry. Scoped to the
      # manual (issue_comment) path so a transient failure on an unrelated
      # ready_for_review PR does not draw a comment, and best-effort so it can never
      # mask the underlying failure that already reds the job.
      - name: Comment on validation failure
        if: ${{ failure() && github.event_name == 'issue_comment' }}
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            try {
              await github.rest.issues.createComment({
                ...context.repo,
                issue_number: context.payload.issue.number,
                body: 'Could not validate the `@release-bot` command because of a workflow error; see the run logs and try the command again.',
              });
            } catch (error) {
              core.warning(`Could not post the validation-failure comment: ${error instanceof Error ? error.message : String(error)}`);
            }

  draft:
    name: Draft curated release notes
    needs: validate
    if: needs.validate.outputs.should-run == 'true' && needs.validate.outputs.command == 'draft'
    runs-on: ubuntu-latest
    timeout-minutes: 35
    environment: release-bot
    permissions:
      contents: read
    steps:
      - name: Generate release bot token
        id: app-token
        uses: actions/create-github-app-token@64ab729a6294000f5aa4a4bc0b73d1f32bc45510 # v3
        with:
          client-id: ${{ vars.ORG_MEMBERSHIP_APP_CLIENT_ID }}
          private-key: ${{ secrets.ORG_MEMBERSHIP_APP_PRIVATE_KEY }}
          permission-contents: write
          permission-issues: write
          permission-pull-requests: write

      - name: Checkout trusted automation
        id: checkout-trusted
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: main
          path: trusted-source
          persist-credentials: false

      - name: Acknowledge manual command
        id: acknowledge
        if: github.event_name == 'issue_comment'
        continue-on-error: true
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          APP_SLUG: ${{ steps.app-token.outputs.app-slug }}
          BOT_LOGIN: ${{ vars.RELEASE_BOT_LOGIN }}
          BOT_ID: ${{ vars.RELEASE_BOT_ID }}
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          retries: 3
          script: |
            const { acknowledgeCommand } = require('./trusted-source/.github/scripts/release/release-notes.js');
            const reactionId = await acknowledgeCommand({
              github,
              ...context.repo,
              commentId: context.payload.comment.id,
              appSlug: process.env.APP_SLUG,
              login: process.env.BOT_LOGIN,
              id: process.env.BOT_ID,
            });
            core.setOutput('reaction-id', reactionId);

      - name: Set up Node
        uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v6
        with:
          node-version: "24"

      - name: Draft and post curated notes with bounded head-change retries
        id: post
        continue-on-error: true
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          PR_NUMBER: ${{ needs.validate.outputs.number }}
          PR_HEAD: ${{ needs.validate.outputs.head }}
          RELEASE_COMPONENT: ${{ needs.validate.outputs.component }}
          RELEASE_VERSION: ${{ needs.validate.outputs.version }}
          INSTRUCTIONS: ${{ needs.validate.outputs.instructions }}
          APP_SLUG: ${{ steps.app-token.outputs.app-slug }}
          BOT_LOGIN: ${{ vars.RELEASE_BOT_LOGIN }}
          BOT_ID: ${{ vars.RELEASE_BOT_ID }}
          MODEL_SPEC: ${{ vars.RELEASE_BOT_MODEL }}
          MODEL_API_KEY: >-
            ${{ startsWith(vars.RELEASE_BOT_MODEL, 'openai:') && secrets.OPENAI_API_KEY ||
                startsWith(vars.RELEASE_BOT_MODEL, 'anthropic:') && secrets.ANTHROPIC_API_KEY ||
                startsWith(vars.RELEASE_BOT_MODEL, 'google_genai:') && secrets.GOOGLE_API_KEY ||
                '' }}
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          script: |
            const { execFileSync } = require('node:child_process');
            const { draftWithRetries } = require('./trusted-source/.github/scripts/release/release-notes.js');
            try {
              await draftWithRetries({
                github,
                ...context.repo,
                number: Number(process.env.PR_NUMBER),
                expectedHead: process.env.PR_HEAD,
                component: process.env.RELEASE_COMPONENT,
                version: process.env.RELEASE_VERSION,
                runnerTemp: process.env.RUNNER_TEMP,
                instructions: process.env.INSTRUCTIONS ?? '',
                appSlug: process.env.APP_SLUG,
                login: process.env.BOT_LOGIN,
                id: process.env.BOT_ID,
                core,
                draft: ({ input, output }) => {
                  try {
                    execFileSync(process.execPath, ['./trusted-source/.github/scripts/release/draft-release-notes.js'], {
                      env: {
                        MODEL_SPEC: process.env.MODEL_SPEC,
                        MODEL_API_KEY: process.env.MODEL_API_KEY,
                        INPUT_FILE: input,
                        OUTPUT_FILE: output,
                      },
                      stdio: ['ignore', 'ignore', 'pipe'],
                    });
                  } catch (error) {
                    throw new Error(error.stderr?.toString().trim() || 'Release-note drafting process failed');
                  }
                },
              });
            } catch (error) {
              core.setOutput('error', error instanceof Error ? error.message : String(error));
              throw error;
            }

      - name: Mark manual command complete
        if: ${{ github.event_name == 'issue_comment' && steps.acknowledge.outcome == 'success' && steps.post.outcome == 'success' }}
        continue-on-error: true
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          APP_SLUG: ${{ steps.app-token.outputs.app-slug }}
          BOT_LOGIN: ${{ vars.RELEASE_BOT_LOGIN }}
          BOT_ID: ${{ vars.RELEASE_BOT_ID }}
          REACTION_ID: ${{ steps.acknowledge.outputs.reaction-id }}
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          retries: 3
          script: |
            const { completeCommand } = require('./trusted-source/.github/scripts/release/release-notes.js');
            await completeCommand({
              github,
              ...context.repo,
              commentId: context.payload.comment.id,
              reactionId: Number(process.env.REACTION_ID),
              appSlug: process.env.APP_SLUG,
              login: process.env.BOT_LOGIN,
              id: process.env.BOT_ID,
            });

      - name: Comment on drafting failure
        if: ${{ !cancelled() && steps.post.outcome != 'success' }}
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          PR_NUMBER: ${{ needs.validate.outputs.number }}
          PR_HEAD: ${{ needs.validate.outputs.head }}
          APP_SLUG: ${{ steps.app-token.outputs.app-slug }}
          BOT_LOGIN: ${{ vars.RELEASE_BOT_LOGIN }}
          BOT_ID: ${{ vars.RELEASE_BOT_ID }}
          POST_ERROR: ${{ steps.post.outputs.error }}
          CHECKOUT_TRUSTED_OUTCOME: ${{ steps.checkout-trusted.outcome }}
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          script: |
            const number = Number(process.env.PR_NUMBER);
            const details = process.env.POST_ERROR
              || (process.env.CHECKOUT_TRUSTED_OUTCOME !== 'success'
                ? 'Checking out the trusted automation failed; see the workflow logs.'
                : 'The drafting step did not succeed; see the workflow logs.');
            try {
              const { postDraftFailure } = require('./trusted-source/.github/scripts/release/release-notes.js');
              await postDraftFailure({
                github,
                ...context.repo,
                number,
                head: process.env.PR_HEAD,
                appSlug: process.env.APP_SLUG,
                login: process.env.BOT_LOGIN,
                id: process.env.BOT_ID,
                message: details,
              });
            } catch (error) {
              // The trusted checkout can itself fail, leaving trusted-source/ (and the
              // helper module) absent so the require above throws — exactly the case
              // the CHECKOUT_TRUSTED_OUTCOME branch above is written to report. Fall
              // back to a direct comment (no bot-identity check or per-head dedup) so
              // the maintainer still gets PR feedback instead of only a red run.
              core.warning(`Falling back to a direct drafting-failure comment: ${error instanceof Error ? error.message : String(error)}`);
              await github.rest.issues.createComment({
                ...context.repo,
                issue_number: number,
                body: `Automatic release-note drafting failed.\n\n${details}\n\nAfter resolving the issue, a maintainer should run \`@release-bot draft\` again.`,
              });
            }

      - name: Fail when drafting or comment publication failed
        if: ${{ !cancelled() && steps.post.outcome != 'success' }}
        run: |
          echo "::error::Curated release-note drafting failed; see the PR comment and earlier step logs."
          exit 1

  apply:
    name: Apply curated release notes
    needs: validate
    if: needs.validate.outputs.should-run == 'true' && needs.validate.outputs.command == 'apply'
    runs-on: ubuntu-latest
    timeout-minutes: 10
    environment: release-bot
    permissions:
      actions: write
      contents: read

    # Applying moves the release PR head with a GitHub App token, which emits no
    # pull_request event. Dispatch the required check explicitly so the new head
    # never depends on a later comment event to acquire its merge gate.
    steps:
      - name: Generate release bot token
        id: app-token
        uses: actions/create-github-app-token@64ab729a6294000f5aa4a4bc0b73d1f32bc45510 # v3
        with:
          client-id: ${{ vars.ORG_MEMBERSHIP_APP_CLIENT_ID }}
          private-key: ${{ secrets.ORG_MEMBERSHIP_APP_PRIVATE_KEY }}
          permission-contents: write
          permission-issues: write
          permission-pull-requests: write

      - name: Checkout trusted automation
        id: checkout-trusted
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: main
          path: trusted-source
          persist-credentials: false

      - name: Acknowledge manual command
        id: acknowledge
        if: github.event_name == 'issue_comment'
        continue-on-error: true
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          APP_SLUG: ${{ steps.app-token.outputs.app-slug }}
          BOT_LOGIN: ${{ vars.RELEASE_BOT_LOGIN }}
          BOT_ID: ${{ vars.RELEASE_BOT_ID }}
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          retries: 3
          script: |
            const { acknowledgeCommand } = require('./trusted-source/.github/scripts/release/release-notes.js');
            const reactionId = await acknowledgeCommand({
              github,
              ...context.repo,
              commentId: context.payload.comment.id,
              appSlug: process.env.APP_SLUG,
              login: process.env.BOT_LOGIN,
              id: process.env.BOT_ID,
            });
            core.setOutput('reaction-id', reactionId);

      - name: Validate override and prepare changelog/body edits
        id: prepare-apply
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          PR_NUMBER: ${{ needs.validate.outputs.number }}
          PR_HEAD: ${{ needs.validate.outputs.head }}
          APP_SLUG: ${{ steps.app-token.outputs.app-slug }}
          BOT_LOGIN: ${{ vars.RELEASE_BOT_LOGIN }}
          BOT_ID: ${{ vars.RELEASE_BOT_ID }}
          APPLY_STATE: ${{ runner.temp }}/release-notes-apply.json
          CHANGELOG_FILE: ${{ runner.temp }}/release-notes-changelog.md
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          script: |
            const { prepareApply } = require('./trusted-source/.github/scripts/release/release-notes.js');
            try {
              await prepareApply({
                github,
                ...context.repo,
                number: Number(process.env.PR_NUMBER),
                expectedHead: process.env.PR_HEAD,
                changelogFile: process.env.CHANGELOG_FILE,
                stateFile: process.env.APPLY_STATE,
                appSlug: process.env.APP_SLUG,
                login: process.env.BOT_LOGIN,
                id: process.env.BOT_ID,
              });
              core.setOutput('state', process.env.APPLY_STATE);
              core.setOutput('changelog', process.env.CHANGELOG_FILE);
            } catch (error) {
              core.setOutput('error', error instanceof Error ? error.message : String(error));
              throw error;
            }

      - name: Create and publish the apply commit without rewriting history
        id: commit
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          APPLY_STATE: ${{ steps.prepare-apply.outputs.state }}
          CHANGELOG_FILE: ${{ steps.prepare-apply.outputs.changelog }}
          APP_SLUG: ${{ steps.app-token.outputs.app-slug }}
          BOT_LOGIN: ${{ vars.RELEASE_BOT_LOGIN }}
          BOT_ID: ${{ vars.RELEASE_BOT_ID }}
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          script: |
            const { createApplyCommit } = require('./trusted-source/.github/scripts/release/release-notes.js');
            try {
              const result = await createApplyCommit({
                github,
                ...context.repo,
                stateFile: process.env.APPLY_STATE,
                changelogFile: process.env.CHANGELOG_FILE,
                appSlug: process.env.APP_SLUG,
                login: process.env.BOT_LOGIN,
                id: process.env.BOT_ID,
              });
              core.setOutput('applied-head', result.appliedHead);
            } catch (error) {
              // Record the reason so the failure-comment step can surface it on the
              // PR instead of the maintainer having to open the Actions logs.
              core.setOutput('error', error instanceof Error ? error.message : String(error));
              throw error;
            }

      - name: Update PR preview and publish applied metadata
        id: publish
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          APPLY_STATE: ${{ steps.prepare-apply.outputs.state }}
          APPLIED_HEAD: ${{ steps.commit.outputs.applied-head }}
          APP_SLUG: ${{ steps.app-token.outputs.app-slug }}
          BOT_LOGIN: ${{ vars.RELEASE_BOT_LOGIN }}
          BOT_ID: ${{ vars.RELEASE_BOT_ID }}
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          script: |
            const { publishAppliedState } = require('./trusted-source/.github/scripts/release/release-notes.js');
            try {
              await publishAppliedState({
                github,
                ...context.repo,
                stateFile: process.env.APPLY_STATE,
                appliedHead: process.env.APPLIED_HEAD,
                appSlug: process.env.APP_SLUG,
                login: process.env.BOT_LOGIN,
                id: process.env.BOT_ID,
              });
            } catch (error) {
              core.setOutput('error', error instanceof Error ? error.message : String(error));
              throw error;
            }

      - name: Refresh required check on the applied head
        id: refresh-check
        if: ${{ steps.publish.outcome == 'success' }}
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          PR_NUMBER: ${{ needs.validate.outputs.number }}
        with:
          script: |
            try {
              await github.rest.actions.createWorkflowDispatch({
                ...context.repo,
                workflow_id: 'release_notes_check.yml',
                ref: 'main',
                inputs: { pr_number: process.env.PR_NUMBER },
              });
            } catch (error) {
              core.setOutput('error', error instanceof Error ? error.message : String(error));
              throw error;
            }

      - name: Mark manual command complete
        if: ${{ github.event_name == 'issue_comment' && steps.acknowledge.outcome == 'success' && steps.refresh-check.outcome == 'success' }}
        continue-on-error: true
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          APP_SLUG: ${{ steps.app-token.outputs.app-slug }}
          BOT_LOGIN: ${{ vars.RELEASE_BOT_LOGIN }}
          BOT_ID: ${{ vars.RELEASE_BOT_ID }}
          REACTION_ID: ${{ steps.acknowledge.outputs.reaction-id }}
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          retries: 3
          script: |
            const { completeCommand } = require('./trusted-source/.github/scripts/release/release-notes.js');
            await completeCommand({
              github,
              ...context.repo,
              commentId: context.payload.comment.id,
              reactionId: Number(process.env.REACTION_ID),
              appSlug: process.env.APP_SLUG,
              login: process.env.BOT_LOGIN,
              id: process.env.BOT_ID,
            });

      # Only an apply-operation failure should publish this notice. Reaction
      # updates are best-effort and must not turn a successful apply into a
      # misleading apply-failure comment.
      - name: Comment on apply failure
        if: ${{ !cancelled() && (steps.prepare-apply.outcome != 'success' || steps.commit.outcome != 'success' || steps.publish.outcome != 'success' || steps.refresh-check.outcome != 'success') }}
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          PR_NUMBER: ${{ needs.validate.outputs.number }}
          PR_HEAD: ${{ needs.validate.outputs.head }}
          APP_SLUG: ${{ steps.app-token.outputs.app-slug }}
          BOT_LOGIN: ${{ vars.RELEASE_BOT_LOGIN }}
          BOT_ID: ${{ vars.RELEASE_BOT_ID }}
          PREPARE_ERROR: ${{ steps.prepare-apply.outputs.error }}
          COMMIT_ERROR: ${{ steps.commit.outputs.error }}
          PUBLISH_ERROR: ${{ steps.publish.outputs.error }}
          REFRESH_ERROR: ${{ steps.refresh-check.outputs.error }}
          COMMIT_OUTCOME: ${{ steps.commit.outcome }}
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          script: |
            const number = Number(process.env.PR_NUMBER);
            // Steps run prepare-apply -> commit -> publish, each skipping the rest on
            // failure, so this precedence surfaces the first (root-cause) failure.
            const details = process.env.PREPARE_ERROR
              || process.env.COMMIT_ERROR
              || process.env.PUBLISH_ERROR
              || process.env.REFRESH_ERROR
              || `commit=${process.env.COMMIT_OUTCOME || 'skipped'}; see the workflow logs.`;
            try {
              const { postApplyFailure } = require('./trusted-source/.github/scripts/release/release-notes.js');
              await postApplyFailure({
                github,
                ...context.repo,
                number,
                head: process.env.PR_HEAD,
                appSlug: process.env.APP_SLUG,
                login: process.env.BOT_LOGIN,
                id: process.env.BOT_ID,
                message: details,
              });
            } catch (error) {
              // The trusted checkout can itself fail, leaving the helper module absent
              // so the require above throws. Fall back to a direct comment (no
              // bot-identity check or per-head dedup) so the maintainer still gets PR
              // feedback instead of only a red run.
              core.warning(`Falling back to a direct apply-failure comment: ${error instanceof Error ? error.message : String(error)}`);
              await github.rest.issues.createComment({
                ...context.repo,
                issue_number: number,
                body: `Applying curated release notes failed.\n\n${details}`,
              });
            }

.github/workflows/release_notes_check.ym:
# Required merge gate for curated release notes on every release-please component.
# Pull-request runs
# attach the native required status to the PR commit. Comment/manual runs execute
# trusted automation from main and explicitly refresh that status on the validated
# release head.

name: "📝 Curated release notes check"

on:
  pull_request:
    types: [opened, edited, synchronize, reopened, ready_for_review, converted_to_draft, labeled, unlabeled]
  issue_comment:
    types: [created, edited, deleted]
  workflow_dispatch:
    inputs:
      pr_number:
        description: "Release PR number to validate after a release-please sync"
        required: true
        type: string

permissions:
  checks: write
  contents: read
  issues: write
  # The new-entries courtesy comment targets the release PR, whose branch is owned
  # by the release-bot GitHub App installation; issues: write alone intermittently
  # 403s there, so request the pull-requests write scope too.
  pull-requests: write

concurrency:
  group: release-notes-check-${{ github.event.pull_request.number || github.event.issue.number || inputs.pr_number }}
  cancel-in-progress: false
  queue: max

jobs:
  curated-release-notes:
    if: github.event_name != 'issue_comment' || github.event.issue.pull_request
    name: ${{ github.event_name == 'pull_request' && 'curated release notes' || 'Refresh curated release notes check' }}
    runs-on: ubuntu-latest
    timeout-minutes: 15
    steps:
      - name: Checkout trusted validator
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: main
          path: trusted-source
          persist-credentials: false

      - name: Validate current curated release-note state
        id: validate
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          PR_NUMBER: ${{ github.event.pull_request.number || github.event.issue.number || inputs.pr_number }}
          BOT_LOGIN: ${{ vars.RELEASE_BOT_LOGIN }}
          BOT_ID: ${{ vars.RELEASE_BOT_ID }}
        with:
          script: |
            // This workflow's YAML comes from the PR, but the helper is checked out
            // from main. Renaming or moving the helper therefore breaks this require
            // for exactly one merge — the new path does not exist on main until the
            // renaming PR lands, and that PR needs this required check to pass. If
            // you rename it, temporarily accept the old path here too and drop the
            // fallback in a follow-up.
            const { checkCuratedState, isReleaseBranchPr } = require('./trusted-source/.github/scripts/release/release-notes.js');
            const number = Number(process.env.PR_NUMBER);
            if (!Number.isSafeInteger(number) || number <= 0) {
              core.setFailed(`Invalid PR number: ${process.env.PR_NUMBER}`);
              return;
            }

            const { owner, repo } = context.repo;
            const { data: pr } = await github.rest.pulls.get({ owner, repo, pull_number: number });
            if (!isReleaseBranchPr(pr)) {
              core.info('Not a release-please release PR; curated release notes are not required.');
              return;
            }
            let refreshCheck = null;
            if (context.eventName !== 'pull_request') {
              const { data: check } = await github.rest.checks.create({
                owner,
                repo,
                name: 'curated release notes',
                head_sha: pr.head.sha,
                status: 'in_progress',
                output: {
                  title: 'Validating curated release notes',
                  summary: 'Checking the latest curated release-note state.',
                },
              });
              refreshCheck = check.id;
              // Expose the id so the always() finalizer below can close this check
              // if the job is cancelled or times out mid-poll before it completes.
              core.setOutput('refresh_check_id', String(refreshCheck));
            }
            try {
              const result = await checkCuratedState({
                github,
                context,
                core,
                number,
                expectedHead: pr.head.sha,
                login: process.env.BOT_LOGIN,
                id: process.env.BOT_ID,
                initialDraftPollAttempts: context.eventName === 'issue_comment' ? 0 : 72,
              });
              // Name the package and version being validated so refresh runs (whose
              // job and check names are package-agnostic) identify their target in
              // the log and in the refreshed check's output.
              const target = result.component
                ? `the ${result.component} ${result.version} release PR`
                : `PR #${number}`;
              core.info(`Curated release-note state for ${target}: ${result.status}.`);
              if (refreshCheck !== null) {
                // 'not-applicable' means the PR is no longer the release branch, so
                // the gate isn't required — treat it as passing, matching the
                // pull_request path's early green return for non-release PRs.
                const passing = new Set(['bypassed', 'draft', 'passed', 'not-applicable']);
                await github.rest.checks.update({
                  owner,
                  repo,
                  check_run_id: refreshCheck,
                  status: 'completed',
                  conclusion: passing.has(result.status) ? 'success' : 'failure',
                  output: {
                    title: passing.has(result.status)
                      ? `Curated release notes are valid for ${target}`
                      : result.status === 'unapplied'
                        ? `Curated release notes are ready for review for ${target}`
                        : `Curated release notes need attention for ${target}`,
                    summary: result.status === 'unapplied'
                      ? [
                          result.draftCommentUrl
                            ? `Review the [bot-authored draft](${result.draftCommentUrl}), then run:`
                            : 'Review the bot-authored draft, then run:',
                          '',
                          '```',
                          '@release-bot apply',
                          '```',
                        ].join('\n')
                      : `Validation result for ${target}: ${result.status}.`,
                  },
                });
              }
            } catch (error) {
              if (refreshCheck !== null) {
                await github.rest.checks.update({
                  owner,
                  repo,
                  check_run_id: refreshCheck,
                  status: 'completed',
                  conclusion: 'failure',
                  output: {
                    title: 'Curated release-note validation failed',
                    summary: `The validator hit an error talking to GitHub: ${error instanceof Error ? error.message : String(error)}. This is often transient — re-run the check.`,
                  },
                });
              }
              core.setFailed(error instanceof Error ? error.message : String(error));
            }

      # The validate step creates the refresh check as `in_progress` before it
      # polls (up to ~12 min) for the automatic draft. A job timeout or cancellation
      # kills that step before it can conclude the check, leaving a required check
      # spinning forever. Close it here so an interrupted run reads as a re-runnable
      # failure rather than a silent hang. No-ops on the happy path (already
      # completed) and when no refresh check was created (pull_request runs).
      - name: Close an interrupted refresh check
        if: always() && steps.validate.outputs.refresh_check_id != ''
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          REFRESH_CHECK_ID: ${{ steps.validate.outputs.refresh_check_id }}
        with:
          script: |
            const checkRunId = Number(process.env.REFRESH_CHECK_ID);
            const { owner, repo } = context.repo;
            try {
              const { data: check } = await github.rest.checks.get({ owner, repo, check_run_id: checkRunId });
              if (check.status === 'completed') return;
              await github.rest.checks.update({
                owner,
                repo,
                check_run_id: checkRunId,
                status: 'completed',
                conclusion: 'failure',
                output: {
                  title: 'Curated release-note validation was interrupted',
                  summary: 'The validator did not finish — it was likely cancelled or timed out while waiting for the automatic draft. Re-run this check.',
                },
              });
            } catch (error) {
              // Never fail the finalizer itself; the required check stays red either way.
              core.warning(`Could not finalize the interrupted refresh check: ${error instanceof Error ? error.message : String(error)}`);
            }

.github/workflows/release_please_fanout_:
# Post-merge safety net for accidental release-please fan-out.
#
# Why this exists:
#   Pre-merge gates (`release_please_scope_check.yml`, etc.) should catch most
#   multi-component / lockfile-only fan-outs, but bypass labels and race windows
#   still happen. When release-please opens a `release(<component>):` PR for a
#   package whose only unreleased path changes on main are lockfiles, this job
#   sticky-comments that release PR within minutes and fails the advisory check
#   so someone notices before release time.
#
#   Recovery recipes it links:
#     - .github/RELEASING.md#lockfile-churn-fan-out
#     - .github/RELEASING.md#reverting-a-merged-but-unreleased-pr
#
# Triggers:
#   - After the release-please maintenance path has a chance to open/update PRs
#     (`workflow_run` of release-please.yml, completed).
#   - Hourly schedule as a backstop if workflow_run is skipped.
#   - Manual workflow_dispatch.
#
# Not a merge gate. Failing this check does not block main; it is a signal.

name: "🔍 Release-please fan-out watch"

on:
  workflow_run:
    workflows: ["⚠️ (Automated) Release Please"]
    types: [completed]
  schedule:
    # Backstop: catch fan-out even if workflow_run is missed.
    - cron: "17 * * * *"
  workflow_dispatch:

permissions:
  contents: read
  pull-requests: write

concurrency:
  group: release-please-fanout-watch
  cancel-in-progress: true

jobs:
  watch:
    name: "flag lockfile-only open release PRs"
    runs-on: ubuntu-latest
    timeout-minutes: 10
    # workflow_run fires for every conclusion; only act on successful release-
    # please runs (or non-workflow_run triggers).
    if: >
      github.event_name != 'workflow_run' ||
      github.event.workflow_run.conclusion == 'success'
    steps:
      - name: "📋 Checkout main"
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: main
          # Full history so package churn since the prior release is visible.
          # Tags are required separately: the manifest stores versions; the
          # detector resolves them to release tags (`component==version`).
          fetch-depth: 0
          fetch-tags: true
          persist-credentials: false

      - name: "🐍 Setup Python 3.11"
        uses: actions/setup-python@6d4fd22b20465ccc0f7354476588e8df7c9ca0e0 # v7.1.0
        with:
          python-version: "3.11"

      - name: "Detect lockfile-only unreleased components"
        id: detect
        run: |
          set -euo pipefail
          # Prefer nested path; until main has it after this reorg, fall back
          # to the flat layout (this job always checks out main).
          detector=".github/scripts/release/check_open_release_fanout.py"
          legacy_detector=".github/scripts/check_open_release_fanout.py"
          if [[ ! -f "$detector" && -f "$legacy_detector" ]]; then
            detector="$legacy_detector"
          fi
          if [[ ! -f "$detector" ]]; then
            echo "::warning::Detector '$detector' missing; watch is NOT enforcing."
            echo '[]' > offenders.json
          else
            # stderr gets the human summary; stdout is JSON for the next step.
            python "$detector" > offenders.json
          fi
          {
            echo "offenders<<__OFF_EOF__"
            cat offenders.json
            echo "__OFF_EOF__"
          } >> "$GITHUB_OUTPUT"
          echo "Detector offenders: $(cat offenders.json)"

      - name: "Comment on open lockfile-only release PRs"
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          OFFENDERS: ${{ steps.detect.outputs.offenders }}
        with:
          script: |
            const STICKY_MARKER = '<!-- release-please-fanout-watch -->';
            const raw = process.env.OFFENDERS || '';
            if (!raw.trim()) {
              core.setFailed('Detector produced no output; failing closed.');
              return;
            }
            let offenders;
            try {
              offenders = JSON.parse(raw);
            } catch (e) {
              core.setFailed(`Detector output was not valid JSON: ${raw}`);
              return;
            }
            if (!Array.isArray(offenders)) {
              core.setFailed(`Detector output was not an array: ${raw}`);
              return;
            }

            // Look up open release-please PRs by conventional branch name.
            // release-please uses:
            //   release-please--branches--main--components--<component>
            const { owner, repo } = context.repo;
            const openReleasePrs = await github.paginate(github.rest.pulls.list, {
              owner, repo, state: 'open', per_page: 100,
            });
            const byComponent = new Map();
            for (const pr of openReleasePrs) {
              const m = pr.head?.ref?.match(
                /^release-please--branches--main--components--(.+)$/
              );
              if (m) {
                byComponent.set(m[1], pr);
              }
            }

            const flagged = [];
            for (const off of offenders) {
              if (!off || typeof off !== 'object' || typeof off.component !== 'string') {
                core.setFailed(`Invalid offender entry: ${JSON.stringify(off)}`);
                return;
              }
              const pr = byComponent.get(off.component);
              if (!pr) {
                core.info(
                  `Component ${off.component} is lockfile-only unreleased but has no open release PR; skipping comment.`
                );
                continue;
              }
              flagged.push({ off, pr });
            }

            if (flagged.length === 0) {
              core.info('No open lockfile-only release PRs to flag.');
              return;
            }

            async function findSticky(issueNumber) {
              const comments = await github.paginate(github.rest.issues.listComments, {
                owner, repo, issue_number: issueNumber, per_page: 100,
              });
              return comments.find(c => c.body && c.body.startsWith(STICKY_MARKER));
            }

            for (const { off, pr } of flagged) {
              const files = Array.isArray(off.files)
                ? off.files.map(f => `\`${f}\``).join(', ')
                : '_unknown_';
              const body = [
                STICKY_MARKER,
                '⚠️ **Possible accidental release fan-out.**',
                '',
                `Open release PR for \`${off.component}\`, but on \`main\` the only changes under \`${off.path}\` since the last released tag (\`${off.baseline}\`${off.version ? `, version ${off.version}` : ''}) are lockfiles: ${files}.`,
                '',
                'release-please scopes by path and has no "this is just a lockfile" notion — a bump-worthy commit that only churned this package\'s `uv.lock` still opens this release PR.',
                '',
                '### Options',
                '',
                '- **If unintentional:** revert or hide the offending commit (see [Reverting a Merged-but-Unreleased PR](https://github.com/langchain-ai/deepagents/blob/main/.github/RELEASING.md#reverting-a-merged-but-unreleased-pr)); closing this PR alone will not stick.',
                '- **If intentional:** proceed with the release (e.g. deliberate leaf-package security bump).',
                '',
                '📖 [Lockfile churn fan-out](https://github.com/langchain-ai/deepagents/blob/main/.github/RELEASING.md#lockfile-churn-fan-out)',
              ].join('\n');

              try {
                const existing = await findSticky(pr.number);
                if (existing) {
                  if (existing.body !== body) {
                    await github.rest.issues.updateComment({
                      owner, repo, comment_id: existing.id, body,
                    });
                  }
                } else {
                  await github.rest.issues.createComment({
                    owner, repo, issue_number: pr.number, body,
                  });
                }
                core.warning(`Flagged release PR #${pr.number} (${off.component}) as lockfile-only fan-out.`);
              } catch (e) {
                core.warning(`Could not comment on PR #${pr.number}: ${e.message}`);
              }
            }

            core.setFailed(
              `Flagged ${flagged.length} open release PR(s) with lockfile-only unreleased deltas: ` +
              flagged.map(f => f.off.component).join(', ') +
              '. See sticky comments on those PRs and .github/RELEASING.md#lockfile-churn-fan-out.'
            );

.github/workflows/release_please_initial:
# Pre-merge check for new release-please-managed packages.
#
# Why this exists:
#   .release-please-manifest.json stores the latest released version baseline,
#   not the desired first release version. If a new package is added there as
#   0.0.1, release-please treats 0.0.1 as already released and opens the first
#   release PR for 0.0.2. This check blocks that before merge.
#
# Limitations:
#   - Runs under `pull_request` (not `pull_request_target`), so fork PRs get a
#     read-only token and the comment may fall back to the job summary. No PR-
#     author-controlled code runs with elevated permissions.

name: "🔍 Release-please initial baseline check"

on:
  pull_request:
    types: [opened, edited, synchronize, reopened]

permissions:
  contents: read
  pull-requests: write

jobs:
  initial-baseline-check:
    name: "flag bad initial manifest baselines"
    runs-on: ubuntu-latest
    timeout-minutes: 3
    steps:
      - name: "📋 Checkout Code"
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v6
        with:
          persist-credentials: false

      - name: "🐍 Setup Python 3.11"
        uses: actions/setup-python@6d4fd22b20465ccc0f7354476588e8df7c9ca0e0 # v7.1.0
        with:
          python-version: "3.11"

      - name: "Fetch base release metadata"
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          retries: 3
          retry-exempt-status-codes: 400,401,403,404,422
          script: |
            const fs = require('fs');
            const baseSha = context.payload.pull_request.base.sha;

            // A 404 means the file does not exist on the base branch yet (e.g.
            // the PR that first introduces release-please, or a branch cut
            // before these files existed). Treat that as an empty baseline so
            // the detector still runs and every head package is evaluated as
            // new. Any other status (403, 5xx) rethrows and fails the job
            // closed, so a transient API error can never be mistaken for an
            // empty baseline.
            async function readRepoFile(path, ref, fallback) {
              const hasFallback = arguments.length === 3;
              try {
                const { data } = await github.rest.repos.getContent({
                  ...context.repo,
                  path,
                  ref,
                });
                if (Array.isArray(data) || data.type !== 'file') {
                  throw new Error(`${path} at ${ref} is not a file`);
                }
                // getContent only inlines base64 content for files up to 1 MB.
                // A larger file returns encoding 'none' with empty content;
                // decoding that would silently yield an empty baseline, so fail
                // closed here with an accurate message rather than three layers
                // downstream in the Python detector.
                if (data.encoding !== 'base64') {
                  throw new Error(`${path} at ${ref} has unexpected encoding '${data.encoding}' (too large to inline?)`);
                }
                return Buffer.from(data.content, data.encoding).toString('utf8');
              } catch (err) {
                if (err.status === 404 && hasFallback) {
                  core.info(`${path} not found at ${ref}; treating as empty baseline.`);
                  return fallback;
                }
                throw err;
              }
            }

            fs.writeFileSync(
              'base-release-please-config.json',
              await readRepoFile('release-please-config.json', baseSha, '{"packages":{}}'),
            );
            fs.writeFileSync(
              'base-release-please-manifest.json',
              await readRepoFile('.release-please-manifest.json', baseSha, '{}'),
            );
            // Preferred nested path ships on this PR; until that lands on base,
            // fall back to the flat layout so the gate still enforces.
            const detectorCandidates = [
              '.github/scripts/release/check_initial_release_baseline.py',
              '.github/scripts/check_initial_release_baseline.py',
            ];
            let detectorSource;
            let lastDetectorErr;
            for (const candidate of detectorCandidates) {
              try {
                detectorSource = await readRepoFile(candidate, baseSha);
                break;
              } catch (err) {
                if (err.status === 404) {
                  lastDetectorErr = err;
                  continue;
                }
                throw err;
              }
            }
            if (detectorSource === undefined) {
              throw lastDetectorErr ?? new Error(
                `None of ${detectorCandidates.join(', ')} found at ${baseSha}`,
              );
            }
            fs.writeFileSync(
              'base-check-initial-release-baseline.py',
              detectorSource,
            );

      - name: "Detect bad initial manifest baseline"
        id: detect
        run: |
          set -euo pipefail
          offenders=$(python base-check-initial-release-baseline.py \
            base-release-please-config.json \
            base-release-please-manifest.json \
            release-please-config.json \
            .release-please-manifest.json)
          {
            echo "offenders<<__INITIAL_RELEASE_EOF__"
            echo "$offenders"
            echo "__INITIAL_RELEASE_EOF__"
          } >> "$GITHUB_OUTPUT"
          echo "Detector offenders: $offenders"

      - name: "Comment on bad initial manifest baseline"
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          OFFENDERS: ${{ steps.detect.outputs.offenders }}
        with:
          script: |
            const STICKY_MARKER = '<!-- release-please-initial-baseline-check -->';
            const BAD_BASELINE = '0.0.1';
            const RECOMMENDED_BASELINE = '0.0.0';
            const { number } = context.payload.pull_request;

            const raw = process.env.OFFENDERS;
            if (raw === undefined || raw.trim() === '') {
              core.setFailed('Detector produced no output; cannot determine initial manifest baseline status. Failing closed.');
              return;
            }
            let offenders;
            try {
              offenders = JSON.parse(raw);
            } catch (parseErr) {
              core.setFailed(`Detector output was not valid JSON: ${JSON.stringify(raw)} (${parseErr.message})`);
              return;
            }
            if (!Array.isArray(offenders)) {
              core.setFailed(`Detector output was not a JSON array: ${JSON.stringify(raw)}`);
              return;
            }

            async function findStickyComment() {
              const comments = await github.paginate(github.rest.issues.listComments, {
                ...context.repo,
                issue_number: number,
                per_page: 100,
              });
              return comments.find(c => c.body && c.body.startsWith(STICKY_MARKER));
            }

            async function deleteSticky() {
              const existing = await findStickyComment();
              if (existing) {
                await github.rest.issues.deleteComment({ ...context.repo, comment_id: existing.id });
              }
            }

            async function upsertSticky(body) {
              try {
                const existing = await findStickyComment();
                if (existing) {
                  await github.rest.issues.updateComment({ ...context.repo, comment_id: existing.id, body });
                } else {
                  await github.rest.issues.createComment({ ...context.repo, issue_number: number, body });
                }
              } catch (commentErr) {
                core.warning(`Could not post sticky comment (fork PR token, rate limit, or transient API error) [status=${commentErr.status ?? 'n/a'}]: ${commentErr.message}`);
                try {
                  await core.summary
                    .addHeading('Bad initial release-please manifest baseline')
                    .addRaw(body)
                    .write();
                } catch (summaryErr) {
                  core.warning(`Could not write job summary fallback [status=${summaryErr.status ?? 'n/a'}]: ${summaryErr.message}`);
                }
              }
            }

            if (offenders.length === 0) {
              try {
                await deleteSticky();
              } catch (cleanupErr) {
                core.warning(`Could not clean up prior initial-baseline-check comment (stale comment may persist on a now-passing PR) [status=${cleanupErr.status ?? 'n/a'}]: ${cleanupErr.message}`);
              }
              core.info('No new release-please packages use a 0.0.1 manifest baseline.');
              return;
            }

            const list = offenders.map(c => `\`${c}\``).join(', ');
            const body = [
              STICKY_MARKER,
              '⛔ **This PR adds a release-please-managed package with manifest baseline `0.0.1`.**',
              '',
              `Affected: ${list}`,
              '',
              '`.release-please-manifest.json` stores the latest released version, not the desired first release version. A new package entered as `0.0.1` will be treated as already released at `0.0.1`, so release-please will open the first release PR for `0.0.2`.',
              '',
              '### To resolve',
              '',
              `Set the new package manifest entry to \`${RECOMMENDED_BASELINE}\` instead of \`${BAD_BASELINE}\`. Keep the package's own \`pyproject.toml\` and \`_version.py\` at \`0.0.1\` so the first release PR publishes \`0.0.1\`.`,
              '',
              '📖 [Adding a release-please-managed package](https://github.com/langchain-ai/deepagents/blob/main/.github/RELEASING.md#adding-a-release-please-managed-package)',
            ].join('\n');

            await upsertSticky(body);
            core.setFailed(`New release-please package(s) use ${BAD_BASELINE} as the manifest baseline: ${offenders.join(', ')}`);

.github/workflows/release_please_parse_c:
# Pre-merge parse check for release-please.
#
# Why this exists:
#   release-please runs every commit message through @conventional-commits/parser
#   to build the changelog. The parser is grammar-strict and does NOT understand
#   markdown code fences — function calls split across lines (e.g.
#   `register_provider_profile(\n  "openai",\n  ...\n)`) are read as malformed
#   conventional-commit scopes and cause the parser to throw. release-please
#   catches the throw, logs a debug message, and silently drops the commit from
#   the release PR. The drop is invisible until someone notices a missing
#   changelog entry — by which point the commit is already merged.
#
#   This check runs the same parser the same way on the would-be squash-merge
#   message at PR time, blocks merge if it would fail, and posts a sticky
#   comment with a copy-paste-ready BEGIN_COMMIT_OVERRIDE block so the author
#   can self-serve the fix.
#
# How it stays faithful to release-please:
#   - Same parser package: @conventional-commits/parser, exact-pinned (NOT semver
#     range) to match release-please's package.json. Bump in lock-step when
#     release-please bumps. As of release-please 17.6.0 this is 0.4.1:
#     https://github.com/googleapis/release-please/blob/v17.6.0/package.json
#   - Mirrors release-please/src/commit.ts:preprocessCommitMessage — if the body
#     contains BEGIN_COMMIT_OVERRIDE..END_COMMIT_OVERRIDE, only the override is
#     parsed (release-please uses it verbatim, ignoring the rest).
#   - Mirrors release-please/src/commit.ts:splitMessages — release-please splits
#     on BEGIN_NESTED_COMMIT/END_NESTED_COMMIT and on blank-line + conventional-
#     commit prefix regex, then parses each sub-message independently. We do the
#     same and fail if ANY sub-message would fail to parse.
#   - Mirrors GitHub's default squash-merge format: `<title> (#<number>)\n\n<body>`.
#     Assumes the repo squash-merge default is "Pull request title and description".
#   - Mirrors GitHub's squash-merge body wrapping. GitHub reflows every body
#     line longer than 72 characters (greedy word wrap, whitespace collapsed),
#     except lines inside top-level code fences. Fences indented under a list
#     item are wrapped too. A one-line call such as `f(a, b)` can be split into
#     `f(a,` + `b)`, which the parser rejects. Verified against 118 of 120
#     recent squash merges; the misses were bodies changed at merge time.
#
# Limitations:
#   - Runs under `pull_request` (not `pull_request_target`), so PRs from forks
#     get the failing check but no auto-comment. Acceptable: external authors
#     will see the failure and a maintainer can paste the override.
#   - Faithful to release-please's parse step only. Doesn't catch downstream
#     issues like wrong-scope inference or path-filter mismatches.

name: "🔍 Release-please parse check"

on:
  pull_request:
    types: [opened, edited, synchronize, reopened]

permissions:
  pull-requests: write

jobs:
  parse-check:
    name: "validate squash-merge message parses"
    runs-on: ubuntu-latest
    steps:
      - name: Install @conventional-commits/parser
        # Exact pin (NOT a semver range) — must equal release-please's
        # package.json entry. A range would silently drift on minor bumps and
        # the parsers can diverge — exactly the failure mode this check exists
        # to prevent.
        run: |
          mkdir -p /tmp/parse-check
          cd /tmp/parse-check
          npm init -y >/dev/null
          npm install '@conventional-commits/parser@0.4.1'

      - name: Validate conventional-commit parse
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            // Load the parser FIRST, outside the parse try/catch. A
            // MODULE_NOT_FOUND here is an infra error (npm install broke or
            // the package layout changed) — surfacing it as "your commit
            // cannot be parsed" would mislead the author.
            let parser;
            try {
              parser = require('/tmp/parse-check/node_modules/@conventional-commits/parser');
            } catch (loadErr) {
              core.setFailed(`Failed to load @conventional-commits/parser — this is a CI infra error, not a problem with your PR: ${loadErr.message}`);
              return;
            }

            const { title, body, number } = context.payload.pull_request;
            // Normalize line endings — GitHub's API returns whatever the
            // editor used, and CRLF leaves stray \r chars in offending-line
            // displays.
            const fullBody = (body || '').replace(/\r\n/g, '\n');
            const STICKY_MARKER = '<!-- release-please-parse-check -->';

            async function findStickyComment() {
              const comments = await github.paginate(github.rest.issues.listComments, {
                ...context.repo,
                issue_number: number,
                per_page: 100,
              });
              return comments.find(c => c.body && c.body.startsWith(STICKY_MARKER));
            }

            // Defer to pr_lint.yml when the title isn't conventional-commit-
            // shaped at all. Otherwise both checks fire on the same PR and
            // this one's sticky comment is just noisy duplication of the
            // title-lint failure. The parse check exists to catch *body*
            // issues hidden behind an otherwise-valid title; without a valid
            // type prefix, release-please would never reach the body anyway.
            //
            // Intentionally loose: shape-only check. The type/scope allowlist
            // (and validity rules like disallowed uppercase scopes) live in
            // pr_lint.yml — don't tighten this regex to match that allowlist
            // or you'll re-introduce the duplicate-comment problem for titles
            // that are shaped correctly but use a disallowed type/scope.
            const titlePrefixRegex = /^[a-z]+(?:\([^)]*\))?!?: .+/;
            if (!titlePrefixRegex.test(title)) {
              core.info(`Title "${title}" is not conventional-commit-shaped; deferring to pr_lint.yml.`);
              try {
                const existing = await findStickyComment();
                if (existing) {
                  await github.rest.issues.deleteComment({
                    ...context.repo,
                    comment_id: existing.id,
                  });
                }
              } catch (cleanupErr) {
                core.warning(`Could not clean up prior parse-check comment: ${cleanupErr.message}`);
              }
              return;
            }

            async function postStickyOrSummary(commentBody, summaryHeading) {
              try {
                const existing = await findStickyComment();
                if (existing) {
                  await github.rest.issues.updateComment({
                    ...context.repo,
                    comment_id: existing.id,
                    body: commentBody,
                  });
                } else {
                  await github.rest.issues.createComment({
                    ...context.repo,
                    issue_number: number,
                    body: commentBody,
                  });
                }
              } catch (commentErr) {
                // Comment posting can fail for several reasons: fork PRs run
                // with restricted tokens, secondary rate limits, transient API
                // errors, or pagination failures during the lookup. Always
                // surface the would-be comment to the job summary so a
                // maintainer can copy-paste the remediation manually.
                core.warning(`Could not post sticky comment (fork PR token, rate limit, or transient API error): ${commentErr.message}`);
                await core.summary
                  .addHeading(summaryHeading)
                  .addRaw('Paste the following into the PR as a comment:')
                  .addCodeBlock(commentBody, 'markdown')
                  .write();
              }
            }

            // Mirror release-please/src/commit.ts:preprocessCommitMessage. If
            // BEGIN_COMMIT_OVERRIDE..END_COMMIT_OVERRIDE is present in the PR
            // body, release-please uses only that — the rest is irrelevant.
            const overrideHalves = fullBody.split('BEGIN_COMMIT_OVERRIDE');
            const beginMarkerCount = overrideHalves.length - 1;

            // Hard-fail when the body contains more than one literal
            // `BEGIN_COMMIT_OVERRIDE`. release-please's preprocessCommitMessage
            // uses `split('BEGIN_COMMIT_OVERRIDE')[1].split('END_COMMIT_OVERRIDE')[0]`
            // — the FIRST occurrence wins, with no anchoring or escape support.
            // The common trap: prose that mentions the marker name (even
            // inside backticks) plus a real override block later — release-
            // please picks the prose mention, the extracted "override" is
            // garbage, and the commit is silently dropped from the changelog.
            // Refuse to guess which occurrence is "real"; ask the author to
            // dedupe.
            if (beginMarkerCount > 1) {
              const multiMarkerBody = [
                STICKY_MARKER,
                '⚠️ **Multiple `BEGIN_COMMIT_OVERRIDE` markers found in this PR\'s body.**',
                '',
                `Found **${beginMarkerCount}** occurrences. release-please uses the **first** one and treats everything from there to the next \`END_COMMIT_OVERRIDE\` as the changelog message. If the first occurrence is prose (the marker name mentioned in the description, even inside backticks), the extracted override will not parse and your commit will be **silently dropped** from the next release PR.`,
                '',
                '### Fix',
                '',
                'Keep at most one literal `BEGIN_COMMIT_OVERRIDE` in the PR body — the one inside the actual override block, if any. For the rest:',
                '',
                '- Rephrase to avoid the literal string (e.g., "the override marker").',
                '- Or break the literal: `` `BEGIN_<wbr>COMMIT_OVERRIDE` `` renders the same in markdown but is no longer a single token to release-please\'s splitter.',
                '',
                'Save the description; this check will re-run automatically.',
                '',
                '📖 [How to override a commit\'s changelog entry](https://github.com/langchain-ai/deepagents/blob/main/.github/RELEASING.md#overriding-a-merged-commits-changelog-entry)',
              ].join('\n');
              await postStickyOrSummary(
                multiMarkerBody,
                'Multiple BEGIN_COMMIT_OVERRIDE markers; comment could not be posted',
              );
              core.setFailed(`Multiple BEGIN_COMMIT_OVERRIDE markers in PR body (${beginMarkerCount}); release-please uses the first occurrence.`);
              return;
            }

            const overrideMessage = beginMarkerCount === 1
              ? overrideHalves[1].split('END_COMMIT_OVERRIDE')[0].trim()
              : '';

            // Mirror release-please/src/commit.ts:splitMessages. release-please
            // splits the preprocessed message into sub-messages and parses each
            // independently — a body that splits into N pieces where one
            // piece fails is rejected by release-please for that piece, even
            // if the whole-message parse would have looked OK.
            function splitMessages(message) {
              const parts = message.split('BEGIN_NESTED_COMMIT');
              const messages = [parts.shift()];
              for (const part of parts) {
                const [newMessage, ...rest] = part.split('END_NESTED_COMMIT');
                messages.push(newMessage);
                messages[0] = messages[0] + rest.join('END_NESTED_COMMIT');
              }
              const conventionalCommits = messages[0]
                .split(/\r?\n\r?\n(?=(?:feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert)(?:\(.*?\))?: )/)
                .filter(Boolean);
              return [...conventionalCommits, ...messages.slice(1)];
            }

            // Mirror GitHub's squash-merge body wrapping (see header). The
            // override is exempt: release-please reads it from the PR body,
            // not from the commit.
            const WRAP_WIDTH = 72;
            function wrapLine(text) {
              if (text.length <= WRAP_WIDTH) return [text];
              const lines = [];
              let current = '';
              for (const word of text.split(/\s+/).filter(Boolean)) {
                if (!current) {
                  current = word;
                } else if (current.length + 1 + word.length <= WRAP_WIDTH) {
                  current += ` ${word}`;
                } else {
                  lines.push(current);
                  current = word;
                }
              }
              if (current) lines.push(current);
              return lines;
            }
            function wrapLikeGitHub(text) {
              const lines = [];
              let fence = null;
              for (const line of text.split('\n')) {
                if (fence) {
                  lines.push(line);
                  if (line.trimEnd().startsWith(fence) && /^(`+|~+)$/.test(line.trimEnd())) fence = null;
                  continue;
                }
                const opener = line.match(/^(`{3,}|~{3,})/);
                if (opener) {
                  fence = opener[1];
                  lines.push(line);
                  continue;
                }
                lines.push(...wrapLine(line));
              }
              return lines.join('\n');
            }

            const squashMessage = overrideMessage
              ? overrideMessage
              : `${title} (#${number})\n\n${wrapLikeGitHub(fullBody)}`;
            const subMessages = splitMessages(squashMessage);

            // Try parsing each sub-message; first failure wins.
            let parseError = null;
            let failingSubMessage = null;
            let failingIndex = -1;
            for (let i = 0; i < subMessages.length; i++) {
              try {
                parser.parser(subMessages[i]);
              } catch (err) {
                parseError = err;
                failingSubMessage = subMessages[i];
                failingIndex = i;
                break;
              }
            }

            if (parseError === null) {
              core.info(overrideMessage
                ? `Parse OK (using BEGIN_COMMIT_OVERRIDE block; ${subMessages.length} sub-message(s))`
                : `Parse OK (${subMessages.length} sub-message(s))`);
              // Clean up any prior failure comment. Wrapped in try/catch
              // because a transient API failure during cleanup must NOT turn
              // a green parse into a red check.
              try {
                const existing = await findStickyComment();
                if (existing) {
                  await github.rest.issues.deleteComment({
                    ...context.repo,
                    comment_id: existing.id,
                  });
                }
              } catch (cleanupErr) {
                core.warning(`Parse passed but could not clean up prior failure comment: ${cleanupErr.message}`);
              }
              return;
            }

            const errMessage = parseError.message || String(parseError);
            const positionMatch = errMessage.match(/at (\d+):(\d+)/);
            if (!positionMatch) {
              core.warning('Could not extract line:col from parser error — parser error format may have changed. Check failure remains correct, but the offending-line callout in the PR comment will be omitted.');
            }
            const line = positionMatch ? parseInt(positionMatch[1], 10) : null;
            const col = positionMatch ? parseInt(positionMatch[2], 10) : null;
            const failingLines = (failingSubMessage || '').split(/\r?\n/);
            const offending = (line && failingLines[line - 1] !== undefined)
              ? failingLines[line - 1]
              : null;

            const suggested = [
              '<!-- release-please override: parser-safe message used by release-please for changelog generation; the rest of the body is unaffected -->',
              'BEGIN_COMMIT_OVERRIDE',
              `${title} (#${number})`,
              '',
              '<one-paragraph description here, no `name(` followed by a newline>',
              'END_COMMIT_OVERRIDE',
            ].join('\n');

            const sourceLabel = overrideMessage
              ? 'BEGIN_COMMIT_OVERRIDE block in the PR description'
              : `\`<title> (#${number})\\n\\n<body>\` (the would-be squash-merge message)`;

            const subMessageLabel = subMessages.length > 1
              ? ` (sub-message ${failingIndex + 1} of ${subMessages.length} after splitMessages)`
              : '';

            const offendingSection = (line && offending !== null)
              ? `**Offending region** (line ${line}, col ${col} of ${sourceLabel}${subMessageLabel}):\n\n\`\`\`\n${offending}\n\`\`\`\n\n`
              : '';

            const overrideAdvice = overrideMessage
              ? 'Your PR already has a `BEGIN_COMMIT_OVERRIDE` block, but the content inside it does not parse. Edit the override content to be a valid conventional commit message.'
              : `The parser does **not** honor markdown code fences — content inside \` \`\`\` \` blocks is parsed the same as anything else. Bare function calls split across lines (\`name(\` followed by a newline) are a common trigger. GitHub also wraps body lines longer than 72 characters when it squash-merges, so a long one-line call can be split too. Only code fences that start at column 0 are kept as-is; a fence indented under a list item is wrapped. The offending region below shows the wrapped text.\n\n### Fix options\n\n**(a) Reformat the offending content** — keep calls on one line of 72 characters or fewer, move the example to a top-level (not indented) code fence, or trim the example out. Quickest if the rich body is not load-bearing.\n\n**(b) Add a release-please override block** at the end of this PR description. Release-please will use the clean message inside it for changelog generation and ignore the rest. Paste:\n\n\`\`\`\`\n${suggested}\n\`\`\`\`\n\nSave the description; this check will re-run automatically.`;

            const commentBody = [
              STICKY_MARKER,
              '⚠️ **Release-please parser cannot parse this PR\'s would-be squash-merge message.**',
              '',
              'If this PR is merged as-is, the commit will be **silently dropped** from the next release PR — release-please skips commits whose bodies its parser rejects, with no error surfaced until the changelog entry is missing.',
              '',
              '**Parse error:**',
              '```',
              errMessage,
              '```',
              '',
              offendingSection + overrideAdvice,
              '',
              '📖 [How to override a commit\'s changelog entry](https://github.com/langchain-ai/deepagents/blob/main/.github/RELEASING.md#overriding-a-merged-commits-changelog-entry)',
            ].join('\n');

            await postStickyOrSummary(
              commentBody,
              'Parse check failed; comment could not be posted',
            );
            // Use only the first line of the parser error in the failure
            // signal — GitHub renders multi-line ::error:: messages with
            // literal %0A escapes in the check summary.
            core.setFailed(errMessage.split('\n')[0]);

.github/workflows/release_please_scope_c:
# Pre-merge blocking check for release-please scope fan-out.
#
# Why this exists:
#   release-please scopes a commit to a package by the file PATHS it touches —
#   it has no notion of "this file is just a lockfile" or "this dependency bound
#   only exists so another package's feature builds." When a bump-worthy commit
#   (a `feat:`/`fix:` in one package) also touches files under other managed
#   package paths — lockfiles, `pyproject.toml` lower bounds, etc. —
#   release-please attributes the bump-worthy commit to those packages and opens
#   a release PR for each. This is the general fan-out sibling of the
#   empty-commit fan-out that the empty-commit guard in release-please.yml blocks;
#   see "Lockfile churn fan-out" and "Multi-component fan-out" in
#   .github/RELEASING.md.
#
#   This check inspects the PR's title type and changed files at PR time. When a
#   bump-worthy PR either:
#     1. edits real (non-lockfile) files in more than one managed component, or
#     2. changes only a lockfile inside a managed package,
#   it posts a sticky comment naming the affected packages and FAILS the check.
#   When the condition is resolved (or the title isn't bump-worthy) the comment
#   is removed and the check passes.
#
# Escape hatch:
#   Cross-package releases are occasionally legitimate (e.g. a leaf-package
#   security bump, or a deliberate coordinated multi-package bump). Apply the
#   `ci:allow-lockfile-release` label to acknowledge the fan-out and let the PR
#   pass; the `labeled` trigger re-runs the check so the red clears without a
#   new commit. A companion workflow (`release_fanout_bypass_warn.yml`) posts a
#   loud sticky listing the components that will still fan out.
#
# To actually gate merges, add this check to the branch's required status checks.
#
# How it stays faithful to release-please:
#   - Package path -> component map and the bump-worthy type set are both read
#     from release-please-config.json by the helper script — see
#     .github/scripts/release/check_lockfile_release_scope.py for the rationale.
#
# Trust model:
#   - The detector and release-please-config.json run from the PR *base*
#     revision, not the PR head, so a PR cannot edit *those* to self-bypass the
#     gate. Only the PR title (event payload) and changed-file list (API) come
#     from the PR.
#   - This base checkout closes the detector/config edit vector but does not by
#     itself make the gate un-bypassable: under `pull_request` the workflow file
#     itself is taken from the PR head, so a PR that edits this workflow can
#     still neuter the check. Gate integrity therefore also relies on branch
#     protection (this job as a required status check) and review of
#     `.github/workflows/` edits.
#
# Limitations:
#   - Runs under `pull_request` (not `pull_request_target`), so PRs from forks
#     get the read-only token and the comment is surfaced to the job summary
#     instead (same fallback as release_please_parse_check.yml). No secrets are
#     exposed to PR-author-controlled code.
#   - The detector and config run from base, so a PR that itself *adds* a new
#     release-please package is checked against the base config that does not
#     yet know that package: a fan-out into the just-added package path is not
#     flagged until the package exists on base. Reading head config instead
#     would reopen the self-bypass the base checkout closes, so this is the
#     deliberate tradeoff; the next PR touching the package is gated normally.

name: "🔍 Release-please scope check"

on:
  pull_request:
    # `labeled`/`unlabeled` so applying the bypass label re-runs the check and
    # clears the red without needing a new commit.
    types: [opened, edited, synchronize, reopened, labeled, unlabeled]

permissions:
  contents: read
  pull-requests: write

jobs:
  scope-check:
    name: "flag release-please fan-out"
    runs-on: ubuntu-latest
    timeout-minutes: 3
    steps:
      - name: "📋 Checkout base revision"
        # Check out the PR *base* (trusted), never the PR head. The detector and
        # release-please-config.json are executed from this tree, so the PR under
        # test cannot edit check_lockfile_release_scope.py or the config to print
        # empty offenders and self-bypass the gate. The PR title (event payload)
        # and changed-file list (API) are fed in separately and are authoritative
        # regardless of this checkout.
        #
        # `persist-credentials: false` so the job token is not written into the
        # checkout's git config; the detector needs no git credentials, and the
        # github-script steps receive their own token directly.
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ github.event.pull_request.base.sha }}
          persist-credentials: false

      - name: "🐍 Setup Python 3.11"
        uses: actions/setup-python@6d4fd22b20465ccc0f7354476588e8df7c9ca0e0 # v7.1.0
        with:
          python-version: "3.11"

      - name: "Collect changed files"
        # Use the API rather than `git diff` so the changed-file list is
        # authoritative regardless of checkout depth. Newline-delimited to
        # changed_files.txt, which the detector reads from stdin.
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const fs = require('fs');
            const files = await github.paginate(github.rest.pulls.listFiles, {
              ...context.repo,
              pull_number: context.payload.pull_request.number,
              per_page: 100,
            });
            // listFiles is hard-capped by GitHub at 3000 files regardless of
            // pagination. A truncated list would make a package look
            // lockfile-only when its real edits are past the cap (false block)
            // or hide a lockfile past the cap (false pass). Fail closed if the
            // collected count doesn't match the PR's reported total.
            const expected = context.payload.pull_request.changed_files;
            // Without a numeric reported total we cannot verify completeness, so
            // fail closed rather than proceeding on a possibly-truncated list.
            if (typeof expected !== 'number') {
              core.setFailed(`PR payload missing numeric changed_files (got ${JSON.stringify(expected)}); cannot verify the changed-file list is complete. Failing closed.`);
              return;
            }
            if (files.length !== expected) {
              core.setFailed(`Changed-file list is incomplete (${files.length} of ${expected}); cannot determine release scope reliably. Failing closed.`);
              return;
            }
            fs.writeFileSync('changed_files.txt', files.map(f => f.filename).join('\n'));
            core.info(`Collected ${files.length} changed file(s).`);

      - name: "Detect release fan-out"
        id: detect
        # PR title is passed via env (never interpolated into the script body)
        # to avoid shell injection from PR-author-controlled text.
        env:
          PR_TITLE: ${{ github.event.pull_request.title }}
        run: |
          set -euo pipefail
          # Preferred nested path ships on this PR; until that lands on base,
          # fall back to the flat layout so the gate still enforces.
          detector=".github/scripts/release/check_lockfile_release_scope.py"
          legacy_detector=".github/scripts/check_lockfile_release_scope.py"
          if [[ ! -f "$detector" && -f "$legacy_detector" ]]; then
            detector="$legacy_detector"
          fi
          if [[ ! -f "$detector" ]]; then
            # The detector does not exist on the base revision: the bootstrapping
            # PR that first introduces this check, or a branch cut from before it
            # existed. There is no trusted gate on base to enforce, so treat as
            # clean. This is not a self-bypass vector: presence is read from
            # trusted base, and an author cannot strip the detector from a base
            # that has it (head edits never change base). An author *can* target
            # an old base that never had it, but gains nothing — that base never
            # gated anything, so there is nothing to evade.
            #
            # The residual risk is operator error, not attack: if the detector is
            # renamed/moved on base without updating the path above, this branch
            # silently disables the gate. Emit a *warning* (not a notice) so the
            # desync surfaces in the Checks UI rather than only the fold-out log.
            echo "::warning::Detector '$detector' absent on base revision; scope check is NOT enforcing. Expected only on the bootstrapping PR or a pre-gate branch — otherwise the detector path here may be out of sync with the repo."
            result='{"lockfile_only":[],"multi_component":[]}'
          else
            # A config-read error in the detector exits non-zero; under `set -e`
            # the command substitution propagates it and this step fails, so the
            # comment step (default `if: success()`) is skipped — fail closed.
            result=$(python "$detector" "$PR_TITLE" < changed_files.txt)
          fi
          # Heredoc form so a multi-line value can never corrupt $GITHUB_OUTPUT.
          {
            echo "result<<__SCOPE_EOF__"
            echo "$result"
            echo "__SCOPE_EOF__"
          } >> "$GITHUB_OUTPUT"
          echo "Detector result: $result"

      - name: "Comment on release fan-out"
        # Result passed via env (not interpolated into the script body) for
        # the same injection-safety reason as the title above.
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          RESULT: ${{ steps.detect.outputs.result }}
        with:
          script: |
            const STICKY_MARKER = '<!-- release-please-scope-check -->';
            const BYPASS_LABEL = 'ci:allow-lockfile-release';
            const SPLIT_RECIPE = [
              'Split into:',
              '',
              '1. One feature/fix PR scoped to the **single** package that owns the user-facing change (`feat(code): ...` / `fix(cli): ...`).',
              '2. One `chore(deps): ...` PR for the cross-package dependency / lockfile churn (`chore` is hidden and does **not** open release PRs).',
            ].join('\n');
            const RELEASING_LOCKFILE = '📖 [Lockfile churn fan-out](https://github.com/langchain-ai/deepagents/blob/main/.github/RELEASING.md#lockfile-churn-fan-out)';
            const RELEASING_MULTI = '📖 [Multi-component fan-out](https://github.com/langchain-ai/deepagents/blob/main/.github/RELEASING.md#multi-component-fan-out)';
            const { number, labels } = context.payload.pull_request;

            // Strict, fail-closed parse. Prefer the object shape with two arrays.
            // During the bootstrap merge of this workflow (and any time base still
            // has the pre-object detector), the trusted base checkout may print a
            // legacy JSON array of lockfile-only component names ("[]" when clean).
            // Accept that shape so the PR introducing the object detector is not
            // blocked by its own rollout; multi_component is unavailable until
            // the new detector is on base.
            const raw = process.env.RESULT;
            if (raw === undefined || raw.trim() === '') {
              core.setFailed('Detector produced no output; cannot determine release scope. Failing closed.');
              return;
            }
            let result;
            try {
              result = JSON.parse(raw);
            } catch (parseErr) {
              core.setFailed(`Detector output was not valid JSON: ${JSON.stringify(raw)} (${parseErr.message})`);
              return;
            }
            if (Array.isArray(result)) {
              if (result.some(c => typeof c !== 'string')) {
                core.setFailed(`Legacy detector array contained a non-string entry: ${JSON.stringify(raw)}`);
                return;
              }
              core.notice(
                'Detector returned legacy lockfile-only array shape; multi_component fan-out is not enforceable until the object-shaped detector is on the PR base.',
              );
              result = { lockfile_only: result, multi_component: [] };
            } else if (
              !result ||
              typeof result !== 'object' ||
              !Array.isArray(result.lockfile_only) ||
              !Array.isArray(result.multi_component) ||
              result.lockfile_only.some(c => typeof c !== 'string') ||
              result.multi_component.some(c => typeof c !== 'string')
            ) {
              core.setFailed(`Detector output was not a fan-out result object: ${JSON.stringify(raw)}`);
              return;
            }

            const multi = result.multi_component;
            const lockOnly = result.lockfile_only;
            const hasFanout = multi.length > 0 || lockOnly.length > 0;

            // Constant string comparison against the structured label payload —
            // no PR-author-controlled text reaches a code path.
            const bypassed = (labels || []).some(l => l.name === BYPASS_LABEL);

            async function findStickyComment() {
              const comments = await github.paginate(github.rest.issues.listComments, {
                ...context.repo,
                issue_number: number,
                per_page: 100,
              });
              return comments.find(c => c.body && c.body.startsWith(STICKY_MARKER));
            }

            async function deleteSticky() {
              const existing = await findStickyComment();
              if (existing) {
                await github.rest.issues.deleteComment({ ...context.repo, comment_id: existing.id });
              }
            }

            async function upsertSticky(body) {
              try {
                const existing = await findStickyComment();
                if (existing) {
                  await github.rest.issues.updateComment({ ...context.repo, comment_id: existing.id, body });
                } else {
                  await github.rest.issues.createComment({ ...context.repo, issue_number: number, body });
                }
              } catch (commentErr) {
                // Fork PRs run with a restricted token; surface to the job
                // summary so the fan-out is still visible alongside the red check.
                core.warning(`Could not post sticky comment (fork PR token, rate limit, or transient API error) [status=${commentErr.status ?? 'n/a'}]: ${commentErr.message}`);
                // Guard the summary write too: if it throws (unwritable summary,
                // size limit) it must not escape upsertSticky and preempt the
                // caller's core.setFailed — the red check is the load-bearing signal.
                try {
                  await core.summary
                    .addHeading('Release-please fan-out')
                    .addRaw(body)
                    .write();
                } catch (summaryErr) {
                  core.warning(`Could not write job summary fallback [status=${summaryErr.status ?? 'n/a'}]: ${summaryErr.message}`);
                }
              }
            }

            if (!hasFanout) {
              // Resolved (or title not bump-worthy): clear any stale comment and
              // pass. Wrapped so a cleanup hiccup can't turn a clean result red.
              try {
                await deleteSticky();
              } catch (cleanupErr) {
                core.warning(`Could not clean up prior scope-check comment (stale comment may persist on a now-passing PR) [status=${cleanupErr.status ?? 'n/a'}]: ${cleanupErr.message}`);
              }
              core.info('No release-please fan-out detected.');
              return;
            }

            const multiList = multi.map(c => `\`${c}\``).join(', ');
            const lockList = lockOnly.map(c => `\`${c}\``).join(', ');
            const allNames = [...multi, ...lockOnly];

            if (bypassed) {
              // Acknowledged as intentional via the bypass label: leave an
              // informational note (not a failure) and pass.
              const lines = [
                STICKY_MARKER,
                `ℹ️ **Release fan-out acknowledged** via the \`${BYPASS_LABEL}\` label.`,
                '',
                '**Consequence:** release-please will open a **separate release PR for every managed component this PR touches**, because the title is bump-worthy (`feat`/`fix`/etc.) and scoping is by changed file path.',
              ];
              if (multi.length) {
                lines.push('', `Real-file multi-component hit(s): ${multiList}`);
              }
              if (lockOnly.length) {
                lines.push('', `Lockfile-only package hit(s): ${lockList}`);
              }
              lines.push(
                '',
                'Remove the label to re-enable the block. Prefer the split recipe if this was unintentional:',
                '',
                SPLIT_RECIPE,
                '',
                RELEASING_MULTI,
                RELEASING_LOCKFILE,
              );
              await upsertSticky(lines.join('\n'));
              core.info(`Bypassed via ${BYPASS_LABEL} label.`);
              return;
            }

            // Prefer the multi-component message when that is the primary
            // signal; always surface both lists when both apply.
            if (multi.length > 0) {
              const singular = multi.length === 1;
              const lines = [
                STICKY_MARKER,
                '⛔ **This bump-worthy PR touches real files in more than one release-please component.**',
                '',
                `Components with non-lockfile edits: ${multiList}`,
              ];
              if (lockOnly.length) {
                lines.push('', `Also lockfile-only under: ${lockList}`);
              }
              lines.push(
                '',
                `Because the PR title is bump-worthy, release-please will open a **separate release PR** for ${singular ? 'this component' : 'each of these components'} (and any lockfile-only packages above). This check is **blocking**.`,
                '',
                '### To resolve',
                '',
                SPLIT_RECIPE,
                '',
                '### If intentional',
                '',
                `Apply the \`${BYPASS_LABEL}\` label to acknowledge the fan-out. The check re-runs and passes — but that still ships a release PR per touched component.`,
                '',
                RELEASING_MULTI,
                RELEASING_LOCKFILE,
              );
              await upsertSticky(lines.join('\n'));
              core.setFailed(`Multi-component release fan-out for: ${allNames.join(', ')}. Split the PR, or apply the '${BYPASS_LABEL}' label if intentional.`);
              return;
            }

            {
              const singular = lockOnly.length === 1;
              await upsertSticky([
                STICKY_MARKER,
                '⛔ **This PR changes only a lockfile inside one or more release-please-managed packages.**',
                '',
                `Affected: ${lockList}`,
                '',
                `Because the PR title is bump-worthy, release-please will open a **separate release PR** for ${singular ? 'this package' : 'each of these packages'} — even though ${singular ? 'its' : 'their'} only change is a regenerated lockfile. This check is **blocking**.`,
                '',
                '### To resolve',
                '',
                SPLIT_RECIPE,
                '',
                '### If intentional',
                '',
                `Apply the \`${BYPASS_LABEL}\` label (e.g. a deliberate dependency bump shipping as a lockfile-only release). The check re-runs and passes — but that still ships a release PR per listed component.`,
                '',
                RELEASING_LOCKFILE,
              ].join('\n'));
              core.setFailed(`Lockfile-only release fan-out for: ${lockOnly.join(', ')}. Resolve, or apply the '${BYPASS_LABEL}' label if intentional.`);
            }

.github/workflows/reopen_on_assignment.y:
# Reopen PRs that were auto-closed by require_issue_link.yml when the
# contributor was not assigned to the linked issue. When a maintainer
# assigns the contributor to the issue, this workflow finds matching
# closed PRs, verifies the issue link, and reopens them.
#
# Uses the default GITHUB_TOKEN (not a PAT or app token) so that the
# reopen and label-removal events do NOT re-trigger other workflows.
# GitHub suppresses events created by the default GITHUB_TOKEN within
# workflow runs to prevent infinite loops.

name: Reopen PR on Issue Assignment

on:
  issues:
    types: [assigned]

permissions:
  contents: read

jobs:
  reopen-linked-prs:
    runs-on: ubuntu-latest
    permissions:
      actions: write
      pull-requests: write

    steps:
      - name: Find and reopen matching PRs
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const { owner, repo } = context.repo;
            const issueNumber = context.payload.issue.number;
            const assignee = context.payload.assignee.login;

            console.log(
              `Issue #${issueNumber} assigned to ${assignee} — searching for closed PRs to reopen`,
            );

            // Comma-separated labels are OR: closed PRs are not backfilled.
            const q = [
              `is:pr`,
              `is:closed`,
              `author:${assignee}`,
              `label:"auto:missing-issue-link","missing-issue-link"`,
              `repo:${owner}/${repo}`,
            ].join(' ');

            let data;
            try {
              ({ data } = await github.rest.search.issuesAndPullRequests({
                q,
                per_page: 30,
              }));
            } catch (e) {
              throw new Error(
                `Failed to search for closed PRs to reopen after assigning ${assignee} ` +
                `to #${issueNumber} (HTTP ${e.status ?? 'unknown'}): ${e.message}`,
              );
            }

            if (data.total_count === 0) {
              console.log('No matching closed PRs found');
              return;
            }

            console.log(`Found ${data.total_count} candidate PR(s)`);

            // Must stay in sync with the identical pattern in require_issue_link.yml
            const pattern = /(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)\s*#(\d+)/gi;

            for (const item of data.items) {
              const prNumber = item.number;
              const body = item.body || '';
              const matches = [...body.matchAll(pattern)];
              const referencedIssues = matches.map(m => parseInt(m[1], 10));

              if (!referencedIssues.includes(issueNumber)) {
                console.log(`PR #${prNumber} does not reference #${issueNumber} — skipping`);
                continue;
              }

              // Skip if already bypassed
              const labels = item.labels.map(l => l.name);
              if (labels.includes('ci:skip-issue-link') || labels.includes('bypass-issue-check')) {
                console.log(`PR #${prNumber} already has an issue-check bypass label — skipping`);
                continue;
              }

              // Reopen first, remove label second — a closed PR that still has
              // auto:missing-issue-link is recoverable; a closed PR with the label
              // stripped is invisible to both workflows.
              try {
                await github.rest.pulls.update({
                  owner,
                  repo,
                  pull_number: prNumber,
                  state: 'open',
                });
                console.log(`Reopened PR #${prNumber}`);
              } catch (e) {
                if (e.status === 422) {
                  // Head branch deleted — PR is unrecoverable. Notify the
                  // contributor so they know to open a new PR.
                  core.warning(`Cannot reopen PR #${prNumber}: head branch was likely deleted`);
                  try {
                    await github.rest.issues.createComment({
                      owner,
                      repo,
                      issue_number: prNumber,
                      body:
                        `You have been assigned to #${issueNumber}, but this PR could not be ` +
                        `reopened because the head branch has been deleted. Please open a new ` +
                        `PR referencing the issue.`,
                    });
                  } catch (commentErr) {
                    core.warning(
                      `Also failed to post comment on PR #${prNumber}: ${commentErr.message}`,
                    );
                  }
                  continue;
                }
                // Transient errors (rate limit, 5xx) should fail the job so
                // the label is NOT removed and the run can be retried.
                throw e;
              }

              // Remove both lifecycle names only after successful reopen.
              for (const name of ['auto:missing-issue-link', 'missing-issue-link']) {
                try {
                  await github.rest.issues.removeLabel({
                    owner,
                    repo,
                    issue_number: prNumber,
                    name,
                  });
                  console.log(`Removed ${name} from PR #${prNumber}`);
                } catch (e) {
                  if (e.status !== 404) throw e;
                }
              }

              // Minimize stale enforcement comment (best-effort;
              // sync w/ require_issue_link.yml minimize blocks)
              try {
                const marker = '<!-- require-issue-link -->';
                const comments = await github.paginate(
                  github.rest.issues.listComments,
                  { owner, repo, issue_number: prNumber, per_page: 100 },
                );
                const stale = comments.find(c => c.body && c.body.includes(marker));
                if (stale) {
                  await github.graphql(`
                    mutation($id: ID!) {
                      minimizeComment(input: {subjectId: $id, classifier: OUTDATED}) {
                        minimizedComment { isMinimized }
                      }
                    }
                  `, { id: stale.node_id });
                  console.log(`Minimized stale enforcement comment ${stale.id} as outdated`);
                }
              } catch (e) {
                core.warning(`Could not minimize stale comment on PR #${prNumber}: ${e.message}`);
              }

              // Both re-run blocks below need the PR's current head SHA. If
              // this fetch fails we cannot target either re-run, so warn and
              // skip to the next PR.
              let pr;
              try {
                ({ data: pr } = await github.rest.pulls.get({
                  owner, repo, pull_number: prNumber,
                }));
              } catch (e) {
                core.warning(`Could not fetch PR #${prNumber} after reopen (HTTP ${e.status ?? 'unknown'}): ${e.message}`);
                continue;
              }

              // Re-run the failed require_issue_link check so it picks up the
              // new assignment.  The re-run uses the original event payload but
              // fetches live issue data, so the assignment check will pass.
              //
              // Limitation: we look up runs by the PR's current head SHA.  If the
              // contributor pushed new commits while the PR was closed, head.sha
              // won't match the SHA of the original failed run and the query will
              // return 0 results.  This is acceptable because any push after reopen
              // triggers a fresh require_issue_link run against the new SHA.
              try {
                const { data: runs } = await github.rest.actions.listWorkflowRuns({
                  owner, repo,
                  workflow_id: 'require_issue_link.yml',
                  head_sha: pr.head.sha,
                  status: 'failure',
                  per_page: 1,
                });
                if (runs.workflow_runs.length > 0) {
                  await github.rest.actions.reRunWorkflowFailedJobs({
                    owner, repo,
                    run_id: runs.workflow_runs[0].id,
                  });
                  console.log(`Re-ran failed require_issue_link run ${runs.workflow_runs[0].id} for PR #${prNumber}`);
                } else {
                  console.log(`No failed require_issue_link runs found for PR #${prNumber} — skipping re-run`);
                }
              } catch (e) {
                core.warning(`Could not re-run require_issue_link check for PR #${prNumber} (HTTP ${e.status ?? 'unknown'}): ${e.message}`);
              }

              // Re-run CI when the original pull_request run was cancelled by
              // the auto-close. The reopen is performed with GITHUB_TOKEN, so
              // GitHub suppresses the normal pull_request.reopened trigger.
              //
              // Unlike the require_issue_link block above (which always uses
              // reRunWorkflowFailedJobs), a cancelled run has no "failed" jobs
              // in GitHub's classification, so the API choice branches on the
              // observed conclusion.
              try {
                const { data: ciRuns } = await github.rest.actions.listWorkflowRuns({
                  owner, repo,
                  workflow_id: 'ci.yml',
                  head_sha: pr.head.sha,
                  status: 'completed',
                  per_page: 1,
                });

                const staleConclusions = new Set(['cancelled', 'failure', 'timed_out', 'startup_failure']);
                const latestCiRun = ciRuns.workflow_runs[0];
                if (latestCiRun && staleConclusions.has(latestCiRun.conclusion)) {
                  if (latestCiRun.conclusion === 'failure') {
                    await github.rest.actions.reRunWorkflowFailedJobs({
                      owner, repo,
                      run_id: latestCiRun.id,
                    });
                  } else {
                    await github.rest.actions.reRunWorkflow({
                      owner, repo,
                      run_id: latestCiRun.id,
                    });
                  }
                  console.log(`Re-ran CI run ${latestCiRun.id} (${latestCiRun.conclusion}) for PR #${prNumber}`);
                } else if (latestCiRun) {
                  console.log(`Latest CI run ${latestCiRun.id} concluded ${latestCiRun.conclusion} — skipping re-run`);
                } else {
                  console.log(`No completed CI runs found for PR #${prNumber} — skipping re-run`);
                }
              } catch (e) {
                // 404: run was deleted. 422: re-run not permitted (e.g.,
                // workflow disabled, run not eligible). Both are
                // non-recoverable for this PR. Anything else (403/429/5xx)
                // is likely transient or a config issue and should fail the
                // job so the maintainer is alerted.
                if (e.status === 404 || e.status === 422) {
                  core.warning(`Could not re-run CI for PR #${prNumber} (HTTP ${e.status}): ${e.message}`);
                } else {
                  throw e;
                }
              }
            }

.github/workflows/require_issue_link.yml:
# Require external PRs to reference an approved issue (e.g. Fixes #NNN) and
# the PR author to be assigned to that issue. On failure the PR is
# labeled "auto:missing-issue-link", commented on, and closed.
#
# Maintainer override: an org member can reopen the PR or remove
# "auto:missing-issue-link" — both add "ci:skip-issue-link" and reopen.
#
# Dependency: pr_labeler.yml must apply the "org:external" label first. This
# workflow does NOT trigger on "opened" (new PRs have no labels yet, so the
# gate would always skip). Legacy labels remain accepted for closed PRs that
# are outside the open-PR backfill.

name: Require Issue Link

on:
  pull_request_target:
    # NEVER CHECK OUT UNTRUSTED CODE FROM A PR's HEAD IN A pull_request_target JOB.
    # Doing so would allow attackers to execute arbitrary code in the context of your repository.
    types: [edited, reopened, labeled, unlabeled]

# ──────────────────────────────────────────────────────────────────────────────
# Enforcement gate: set to 'true' to activate the issue link requirement.
# When 'false', the workflow still runs the check logic (useful for dry-run
# visibility) but will NOT label, comment, close, or fail PRs.
# ──────────────────────────────────────────────────────────────────────────────
env:
  ENFORCE_ISSUE_LINK: "true"

permissions:
  contents: read

jobs:
  check-issue-link:
    # Run when the "org:external" label is added, on edit/reopen if already labeled,
    # or when "auto:missing-issue-link" is removed (triggers maintainer override check).
    # Skip entirely when the PR already carries "auto:trusted-contributor" or
    # "ci:skip-issue-link". Accept legacy names in all of these paths.
    # Skip merged PRs: editing the title/body or relabeling a merged PR must
    # not re-fire enforcement (label, comment, "close" no-op, failed check).
    # Closed-but-not-merged PRs still flow through so contributors editing the
    # body to add a `Fixes #N` link will be reopened.
    if: >-
      github.event.pull_request.merged == false &&
      !contains(github.event.pull_request.labels.*.name, 'auto:trusted-contributor') &&
      !contains(github.event.pull_request.labels.*.name, 'trusted-contributor') &&
      !contains(github.event.pull_request.labels.*.name, 'ci:skip-issue-link') &&
      !contains(github.event.pull_request.labels.*.name, 'bypass-issue-check') &&
      (
        (
          github.event.action == 'labeled' &&
          contains(fromJSON('["org:external", "external"]'), github.event.label.name)
        ) ||
        (
          (contains(github.event.pull_request.labels.*.name, 'org:external') || contains(github.event.pull_request.labels.*.name, 'external')) &&
          (
            (
              github.event.action == 'unlabeled' &&
              contains(fromJSON('["auto:missing-issue-link", "missing-issue-link"]'), github.event.label.name)
            ) ||
            (github.event.action != 'labeled' && github.event.action != 'unlabeled')
          )
        )
      )
    runs-on: ubuntu-latest
    permissions:
      actions: write
      # `ensureAndAddLabel` creates labels on demand, and label creation is an
      # Issues-scoped endpoint that `pull-requests: write` does not cover.
      issues: write
      pull-requests: write

    steps:
      - name: Check for issue link and assignee
        id: check-link
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request.number;
            const action = context.payload.action;
            const missingLinkLabels = ['auto:missing-issue-link', 'missing-issue-link'];

            // ── Helper: ensure a label exists, then add it to the PR ────────
            async function ensureAndAddLabel(labelName, color) {
              try {
                await github.rest.issues.getLabel({ owner, repo, name: labelName });
              } catch (e) {
                if (e.status !== 404) throw e;
                try {
                  await github.rest.issues.createLabel({ owner, repo, name: labelName, color });
                } catch (createErr) {
                  // 422 = label was created by a concurrent run between our
                  // GET and POST — safe to ignore.
                  if (createErr.status !== 422) throw createErr;
                }
              }
              await github.rest.issues.addLabels({
                owner, repo, issue_number: prNumber, labels: [labelName],
              });
            }

            // ── Helper: check if the user who triggered this event (reopened
            // the PR / removed the label) has write+ access on the repo ───
            // Uses the repo collaborator permission endpoint instead of the
            // org membership endpoint. The org endpoint requires the caller
            // to be an org member, which GITHUB_TOKEN (an app installation
            // token) never is — so it always returns 403.
            async function senderIsOrgMember() {
              const sender = context.payload.sender?.login;
              if (!sender) {
                throw new Error('Event has no sender — cannot check permissions');
              }
              try {
                const { data } = await github.rest.repos.getCollaboratorPermissionLevel({
                  owner, repo, username: sender,
                });
                const perm = data.permission;
                if (['admin', 'maintain', 'write'].includes(perm)) {
                  console.log(`${sender} has ${perm} permission — treating as maintainer`);
                  return { isMember: true, login: sender };
                }
                console.log(`${sender} has ${perm} permission — not a maintainer`);
                return { isMember: false, login: sender };
              } catch (e) {
                if (e.status === 404) {
                  console.log(`Cannot check permissions for ${sender} — treating as non-maintainer`);
                  return { isMember: false, login: sender };
                }
                const status = e.status ?? 'unknown';
                throw new Error(
                  `Permission check failed for ${sender} (HTTP ${status}): ${e.message}`,
                );
              }
            }

            // ── Helper: apply maintainer bypass (shared by both override paths) ──
            async function applyMaintainerBypass(reason) {
              console.log(reason);

              // Remove both names so legacy lifecycle state cannot linger.
              for (const name of missingLinkLabels) {
                try {
                  await github.rest.issues.removeLabel({
                    owner, repo, issue_number: prNumber, name,
                  });
                } catch (e) {
                  if (e.status !== 404) throw e;
                }
              }

              // Reopen before adding bypass label — a failed reopen is more
              // actionable than a closed PR with a bypass label stuck on it.
              if (context.payload.pull_request.state === 'closed') {
                try {
                  await github.rest.pulls.update({
                    owner, repo, pull_number: prNumber, state: 'open',
                  });
                  console.log(`Reopened PR #${prNumber}`);
                } catch (e) {
                  // 422 if head branch deleted; 403 if permissions insufficient.
                  // Bypass labels still apply — maintainer can reopen manually.
                  core.warning(
                    `Could not reopen PR #${prNumber} (HTTP ${e.status ?? 'unknown'}): ${e.message}. ` +
                    `Bypass labels were applied — a maintainer may need to reopen manually.`,
                  );
                }
              }

              // Add ci:skip-issue-link so future triggers skip enforcement
              await ensureAndAddLabel('ci:skip-issue-link', 'e3c3cc');

              // Minimize stale enforcement comment (best-effort; must not
              // abort bypass — sync w/ reopen_on_assignment.yml & step below)
              try {
                const marker = '<!-- require-issue-link -->';
                const comments = await github.paginate(
                  github.rest.issues.listComments,
                  { owner, repo, issue_number: prNumber, per_page: 100 },
                );
                const stale = comments.find(c => c.body && c.body.includes(marker));
                if (stale) {
                  await github.graphql(`
                    mutation($id: ID!) {
                      minimizeComment(input: {subjectId: $id, classifier: OUTDATED}) {
                        minimizedComment { isMinimized }
                      }
                    }
                  `, { id: stale.node_id });
                  console.log(`Minimized stale enforcement comment ${stale.id} as outdated`);
                }
              } catch (e) {
                core.warning(`Could not minimize stale comment on PR #${prNumber}: ${e.message}`);
              }

              core.setOutput('has-link', 'true');
              core.setOutput('is-assigned', 'true');
            }

            // ── Maintainer override: removed "auto:missing-issue-link" label ─────
            if (action === 'unlabeled') {
              const { isMember, login } = await senderIsOrgMember();
              if (isMember) {
                await applyMaintainerBypass(
                  `Maintainer ${login} removed auto:missing-issue-link from PR #${prNumber} — bypassing enforcement`,
                );
                return;
              }
              // Non-member removed the label — re-add it defensively and
              // set failure outputs so downstream steps (comment, close) fire.
              // NOTE: addLabels fires a "labeled" event, but the job-level gate
              // only matches labeled events for "org:external", so no re-trigger.
              console.log(`Non-member ${login} removed auto:missing-issue-link — re-adding`);
              try {
                await ensureAndAddLabel('auto:missing-issue-link', 'd9dce0');
              } catch (e) {
                core.warning(
                  `Failed to re-add auto:missing-issue-link (HTTP ${e.status ?? 'unknown'}): ${e.message}. ` +
                  `Downstream step will retry.`,
                );
              }
              core.setOutput('has-link', 'false');
              core.setOutput('is-assigned', 'false');
              return;
            }

            // ── Maintainer override: reopened PR with "auto:missing-issue-link" ──
            const prLabels = context.payload.pull_request.labels.map(l => l.name);
            if (action === 'reopened' && missingLinkLabels.some(name => prLabels.includes(name))) {
              const { isMember, login } = await senderIsOrgMember();
              if (isMember) {
                await applyMaintainerBypass(
                  `Maintainer ${login} reopened PR #${prNumber} — bypassing enforcement`,
                );
                return;
              }
              console.log(`Non-member ${login} reopened PR — proceeding with check`);
            }

            // ── Fetch live labels (race guard) ──────────────────────────────
            const { data: liveLabels } = await github.rest.issues.listLabelsOnIssue({
              owner, repo, issue_number: prNumber,
            });
            const liveNames = liveLabels.map(l => l.name);
            if (['auto:trusted-contributor', 'trusted-contributor', 'ci:skip-issue-link', 'bypass-issue-check'].some(name => liveNames.includes(name))) {
              console.log('PR has a trusted-contributor or issue-check bypass label — bypassing');
              core.setOutput('has-link', 'true');
              core.setOutput('is-assigned', 'true');
              return;
            }

            const body = context.payload.pull_request.body || '';
            const pattern = /(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)\s*#(\d+)/gi;
            const matches = [...body.matchAll(pattern)];

            if (matches.length === 0) {
              console.log('No issue link found in PR body');
              core.setOutput('has-link', 'false');
              core.setOutput('is-assigned', 'false');
              return;
            }

            const issues = matches.map(m => `#${m[1]}`).join(', ');
            console.log(`Found issue link(s): ${issues}`);
            core.setOutput('has-link', 'true');

            // Check whether the PR author is assigned to at least one linked issue
            const prAuthor = context.payload.pull_request.user.login;
            const MAX_ISSUES = 5;
            const allIssueNumbers = [...new Set(matches.map(m => parseInt(m[1], 10)))];
            const issueNumbers = allIssueNumbers.slice(0, MAX_ISSUES);
            if (allIssueNumbers.length > MAX_ISSUES) {
              core.warning(
                `PR references ${allIssueNumbers.length} issues — only checking the first ${MAX_ISSUES}`,
              );
            }

            let assignedToAny = false;
            for (const num of issueNumbers) {
              try {
                const { data: issue } = await github.rest.issues.get({
                  owner, repo, issue_number: num,
                });
                const assignees = issue.assignees.map(a => a.login.toLowerCase());
                if (assignees.includes(prAuthor.toLowerCase())) {
                  console.log(`PR author "${prAuthor}" is assigned to #${num}`);
                  assignedToAny = true;
                  break;
                } else {
                  console.log(`PR author "${prAuthor}" is NOT assigned to #${num} (assignees: ${assignees.join(', ') || 'none'})`);
                }
              } catch (error) {
                if (error.status === 404) {
                  console.log(`Issue #${num} not found — skipping`);
                } else {
                  // Non-404 errors (rate limit, server error) must not be
                  // silently skipped — they could cause false enforcement
                  // (closing a legitimate PR whose assignment can't be verified).
                  throw new Error(
                    `Cannot verify assignee for issue #${num} (${error.status}): ${error.message}`,
                  );
                }
              }
            }

            core.setOutput('is-assigned', assignedToAny ? 'true' : 'false');

      - name: Add auto:missing-issue-link label
        if: >-
          env.ENFORCE_ISSUE_LINK == 'true' &&
          (steps.check-link.outputs.has-link != 'true' || steps.check-link.outputs.is-assigned != 'true')
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request.number;
            const labelName = 'auto:missing-issue-link';

            // Ensure the label exists (no checkout/shared helper available)
            try {
              await github.rest.issues.getLabel({ owner, repo, name: labelName });
            } catch (e) {
              if (e.status !== 404) throw e;
              try {
                await github.rest.issues.createLabel({
                  owner, repo, name: labelName, color: 'd9dce0',
                });
              } catch (createErr) {
                if (createErr.status !== 422) throw createErr;
              }
            }

            await github.rest.issues.addLabels({
              owner, repo, issue_number: prNumber, labels: [labelName],
            });

      - name: Remove auto:missing-issue-link label and reopen PR
        if: >-
          env.ENFORCE_ISSUE_LINK == 'true' &&
          steps.check-link.outputs.has-link == 'true' && steps.check-link.outputs.is-assigned == 'true'
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request.number;
            const missingLinkLabels = ['auto:missing-issue-link', 'missing-issue-link'];

            // Reopen before removing either label so a failed reopen remains
            // discoverable by both recovery workflows.
            const labels = context.payload.pull_request.labels.map(l => l.name);
            if (context.payload.pull_request.state === 'closed' && missingLinkLabels.some(name => labels.includes(name))) {
              await github.rest.pulls.update({
                owner,
                repo,
                pull_number: prNumber,
                state: 'open',
              });
              console.log(`Reopened PR #${prNumber}`);
            }

            for (const name of missingLinkLabels) {
              try {
                await github.rest.issues.removeLabel({
                  owner, repo, issue_number: prNumber, name,
                });
              } catch (error) {
                if (error.status !== 404) throw error;
              }
            }

            // Minimize stale enforcement comment (best-effort;
            // sync w/ applyMaintainerBypass above & reopen_on_assignment.yml)
            try {
              const marker = '<!-- require-issue-link -->';
              const comments = await github.paginate(
                github.rest.issues.listComments,
                { owner, repo, issue_number: prNumber, per_page: 100 },
              );
              const stale = comments.find(c => c.body && c.body.includes(marker));
              if (stale) {
                await github.graphql(`
                  mutation($id: ID!) {
                    minimizeComment(input: {subjectId: $id, classifier: OUTDATED}) {
                      minimizedComment { isMinimized }
                    }
                  }
                `, { id: stale.node_id });
                console.log(`Minimized stale enforcement comment ${stale.id} as outdated`);
              }
            } catch (e) {
              core.warning(`Could not minimize stale comment on PR #${prNumber}: ${e.message}`);
            }

      - name: Post comment, close PR, and fail
        if: >-
          env.ENFORCE_ISSUE_LINK == 'true' &&
          (steps.check-link.outputs.has-link != 'true' || steps.check-link.outputs.is-assigned != 'true')
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request.number;
            const hasLink = '${{ steps.check-link.outputs.has-link }}' === 'true';
            const isAssigned = '${{ steps.check-link.outputs.is-assigned }}' === 'true';
            const marker = '<!-- require-issue-link -->';

            let lines;
            if (!hasLink) {
              lines = [
                marker,
                '**This PR has been automatically closed** because it does not link to an approved issue.',
                '',
                'All external contributions must reference an approved issue or discussion. Please:',
                '1. Find or [open an issue](https://github.com/' + owner + '/' + repo + '/issues/new/choose) describing the change',
                '2. Wait for a maintainer to approve and assign you',
                '3. Add `Fixes #<issue_number>`, `Closes #<issue_number>`, or `Resolves #<issue_number>` to your PR description and the PR will be reopened automatically',
                '',
                '*Maintainers: reopen this PR or remove the `auto:missing-issue-link` label to bypass this check.*',
              ];
            } else {
              lines = [
                marker,
                '**This PR has been automatically closed** because you are not assigned to the linked issue.',
                '',
                'Opening a PR is **not** an indication that it will be accepted. This process exists so maintainers can confirm a change is aligned with the project direction *before* you invest time implementing it. Please:',
                '1. Comment on the linked issue explaining the approach you would like to take and why — include enough detail for a maintainer to evaluate the design. Do **not** post a drive-by "please assign me" comment with no substance; those will be ignored.',
                '2. Wait for a maintainer to assign you. Once assigned, your PR will be reopened automatically.',
                '',
                '*Maintainers: reopen this PR or remove the `auto:missing-issue-link` label to bypass this check.*',
              ];
            }

            const body = lines.join('\n');

            // Deduplicate: check for existing comment with the marker
            const comments = await github.paginate(
              github.rest.issues.listComments,
              { owner, repo, issue_number: prNumber, per_page: 100 },
            );
            const existing = comments.find(c => c.body && c.body.includes(marker));

            if (!existing) {
              await github.rest.issues.createComment({
                owner,
                repo,
                issue_number: prNumber,
                body,
              });
              console.log('Posted requirement comment');
            } else if (existing.body !== body) {
              await github.rest.issues.updateComment({
                owner,
                repo,
                comment_id: existing.id,
                body,
              });
              console.log('Updated existing comment with new message');
            } else {
              console.log('Comment already exists — skipping');
            }

            // Close the PR
            if (context.payload.pull_request.state === 'open') {
              await github.rest.pulls.update({
                owner,
                repo,
                pull_number: prNumber,
                state: 'closed',
              });
              console.log(`Closed PR #${prNumber}`);
            }

            // Cancel all other in-progress and queued workflow runs for this PR
            const headSha = context.payload.pull_request.head.sha;
            for (const status of ['in_progress', 'queued']) {
              const runs = await github.paginate(
                github.rest.actions.listWorkflowRunsForRepo,
                { owner, repo, head_sha: headSha, status, per_page: 100 },
              );
              for (const run of runs) {
                if (run.id === context.runId) continue;
                try {
                  await github.rest.actions.cancelWorkflowRun({
                    owner, repo, run_id: run.id,
                  });
                  console.log(`Cancelled ${status} run ${run.id} (${run.name})`);
                } catch (err) {
                  console.log(`Could not cancel run ${run.id}: ${err.message}`);
                }
              }
            }

            const reason = !hasLink
              ? 'PR must reference an issue using auto-close keywords (e.g., "Fixes #123").'
              : 'PR author must be assigned to the linked issue.';
            core.setFailed(reason);

.github/workflows/ripgrep_timeout_commen:
# Posts a sticky PR comment when a ripgrep install in `_test.yml` gave up, so a
# reviewer can see that the affected legs ran without ripgrep. Two steps produce
# the marker artifact: the bounded install on an ordinary PR (hit its timeout)
# and the unbounded strict install on a release PR (failed and was bypassed
# under `ci:skip-ripgrep`). The comment wording distinguishes the two.
#
# Trigger — `workflow_run` of ci.yml, completed, rather than `pull_request`:
# a `pull_request` run from a fork gets a read-only token and cannot comment.
# This workflow runs in the base repository's context, so it holds the
# `issues: write` needed to post. That token must never be handed to
# PR-authored code:
#
#   DO NOT add `actions/checkout` (or any step that runs code from the PR)
#   to this workflow. It reads artifact *names* through the API only, never
#   artifact contents, and the comment body is fully static.
#
# Not a merge gate. This posts a comment; it never blocks anything.

name: "🔍 Ripgrep timeout warning"

on:
  workflow_run:
    workflows: ["🔧 CI"]
    types: [completed]

# `issues: write` covers createComment/updateComment/deleteComment — PR
# conversation comments are the issues API. `pull-requests: read` covers
# `pulls.get` and `pulls.list` for resolving the PR number.
permissions:
  actions: read
  contents: read
  issues: write
  pull-requests: read

concurrency:
  # Keyed on the head SHA, not the branch: two CI runs for different commits
  # must not cancel each other, or the surviving run can be discarded by the
  # stale-SHA guard below and no comment is ever managed.
  group: ripgrep-timeout-comment-${{ github.event.workflow_run.head_sha }}
  cancel-in-progress: true

jobs:
  manage-comment:
    # A cancelled or startup-failed run produces no artifacts, which is
    # indistinguishable from "no timeout" and would wrongly delete a valid
    # warning. Only act on runs that actually reached a conclusion.
    if: >-
      github.event.workflow_run.event == 'pull_request' &&
      (github.event.workflow_run.conclusion == 'success' ||
      github.event.workflow_run.conclusion == 'failure')
    runs-on: ubuntu-latest
    timeout-minutes: 3
    steps:
      - name: Manage PR warning comment
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const marker = '<!-- ripgrep-install-timeout -->';
            const { owner, repo } = context.repo;
            const run = context.payload.workflow_run;

            // `workflow_run.pull_requests` is empty for fork PRs, and
            // `listPullRequestsAssociatedWithCommit` often fails to resolve a
            // commit that lives in the fork. Resolving by head ref works for
            // both same-repo and fork PRs, so it is the primary lookup.
            let prNumber = run.pull_requests?.[0]?.number;
            if (!prNumber) {
              const candidates = await github.paginate(
                github.rest.pulls.list,
                {
                  owner,
                  repo,
                  state: 'open',
                  head: `${run.head_repository.owner.login}:${run.head_branch}`,
                  per_page: 100,
                },
              );
              prNumber = candidates.find(c => c.head.sha === run.head_sha)?.number;
            }

            const artifacts = await github.paginate(
              github.rest.actions.listWorkflowRunArtifacts,
              { owner, repo, run_id: run.id, per_page: 100 },
            );
            const timeoutArtifacts = artifacts.filter(
              artifact => !artifact.expired && artifact.name.startsWith('ripgrep-timeout-'),
            );

            if (!prNumber) {
              // A PR that was closed or had its head branch deleted between
              // CI completing and this workflow firing resolves to nothing —
              // that is a normal race, not a broken mechanism, and there is
              // no conversation left to warn. The `::warning::` annotation in
              // the CI run itself is the record of the timeout.
              const message = `CI run ${run.id} has no resolvable pull request.`;
              if (timeoutArtifacts.length > 0) {
                core.warning(`${message} A ripgrep timeout goes unreported; the artifacts are ${timeoutArtifacts.map(a => a.name).join(', ')}.`);
              } else {
                core.info(`${message} No timeout to report.`);
              }
              return;
            }

            // Guards against a re-run of an old CI run posting a warning for a
            // commit the PR has already moved past.
            const { data: pullRequest } = await github.rest.pulls.get({
              owner,
              repo,
              pull_number: prNumber,
            });
            if (pullRequest.head.sha !== run.head_sha) {
              core.info(`Ignoring stale CI run ${run.id}; PR #${prNumber} now points at ${pullRequest.head.sha}.`);
              return;
            }

            // Which failure mode the comment describes is decided by the PR
            // kind, not by the label. On a release PR the only producer of
            // these artifacts is the strict step's bypass path, which has no
            // timeout -- so claiming "took more than two minutes" there would
            // be false. Matches `_test.yml`'s release-PR predicate; keep the
            // two in step (`test_ci_workflow.py` asserts they agree).
            const isReleasePullRequest =
              pullRequest.head.ref.startsWith('release-please--') ||
              pullRequest.title.startsWith('release(');
            // The label only decides one sentence: whether the merge will carry
            // the bypass into the publish run. A failed read leaves it false,
            // which downgrades that sentence to "could not confirm" rather than
            // asserting either outcome.
            let hasBypassLabel = false;
            try {
              const labels = await github.paginate(
                github.rest.issues.listLabelsOnIssue,
                { owner, repo, issue_number: prNumber, per_page: 100 },
              );
              hasBypassLabel = labels.some(label => label.name === 'ci:skip-ripgrep');
            } catch (error) {
              core.warning(
                `Could not read labels for PR #${prNumber} ` +
                  `(status ${error.status ?? 'unknown'}: ${error.message}); ` +
                  'treating ci:skip-ripgrep as unconfirmed.',
              );
            }

            const comments = await github.paginate(
              github.rest.issues.listComments,
              { owner, repo, issue_number: prNumber, per_page: 100 },
            );
            // Matched on the marker AND the bot login: matching the marker
            // alone lets a PR author pre-post the marker and capture the
            // sticky-comment slot — the update/delete call then fails (or
            // the warning stays user-owned and editable), so the genuine
            // timeout warning is never managed. If the posting identity ever
            // changes, update this login; a missed match only means one extra
            // comment, while a hijacked slot means no warning at all.
            const existing = comments.find(
              comment => comment.user?.login === 'github-actions[bot]' &&
                (comment.body ?? '').startsWith(marker),
            );

            if (timeoutArtifacts.length === 0) {
              if (existing) {
                try {
                  await github.rest.issues.deleteComment({
                    owner,
                    repo,
                    comment_id: existing.id,
                  });
                  core.info('Removed the obsolete ripgrep timeout warning comment.');
                } catch (error) {
                  if (error.status !== 404) throw error;
                  core.info('Comment was already removed.');
                }
              }
              return;
            }

            // Artifact names carry the package, OS, and Python version, so the
            // comment can name the affected legs instead of hedging.
            const legs = timeoutArtifacts
              .map(artifact => artifact.name.replace(/^ripgrep-timeout-/, ''))
              .sort();
            const runUrl = `${context.serverUrl}/${owner}/${repo}/actions/runs/${run.id}`;
            const body = isReleasePullRequest
              ? [
                  marker,
                  '**Notice: the strict ripgrep install failed and was bypassed.**',
                  '',
                  'Installation failed on these release-PR test runners:',
                  '',
                  ...legs.map(leg => `- \`${leg}\``),
                  '',
                  'Those runners continued without ripgrep. The real-binary grep tests were skipped there, including the symlink containment check.',
                  '',
                  hasBypassLabel
                    ? 'If the `ci:skip-ripgrep` label is still on this PR when it merges, the publish run is dispatched with `dangerous-skip-ripgrep-check=true`. A repeat install failure there is then tolerated, and the rg-gated artifact tests skip instead of failing the release.'
                    : 'The `ci:skip-ripgrep` label could not be read on this PR. If it is absent at merge time, the publish run enforces the strict install and an install failure there fails the release.',
                  '',
                  `Merge only if the install failure is transient. Remove the label and re-run CI to restore ripgrep coverage. [View the CI run](${runUrl})`,
                ].join('\n')
              : [
                  marker,
                  '**Warning: ripgrep did not install in time.**',
                  '',
                  'Installation took more than two minutes on these test runners:',
                  '',
                  ...legs.map(leg => `- \`${leg}\``),
                  '',
                  'Those runners ran without ripgrep. The real-binary grep tests were skipped there, including the symlink containment check. `grep` on the filesystem backend used the Python fallback, which is slower and does not skip `.gitignore`d or hidden files, so some results differ.',
                  '',
                  'Release PRs, merge-queue runs, and the release workflow do not use this timeout. They fail if ripgrep does not install.',
                  '',
                  `No action is needed to merge. Re-run CI to get ripgrep coverage. [View the CI run](${runUrl})`,
                ].join('\n');

            if (existing) {
              await github.rest.issues.updateComment({
                owner,
                repo,
                comment_id: existing.id,
                body,
              });
              core.info('Updated the ripgrep timeout warning comment.');
            } else {
              await github.rest.issues.createComment({
                owner,
                repo,
                issue_number: prNumber,
                body,
              });
              core.info('Created the ripgrep timeout warning comment.');
            }

.github/workflows/sync_priority_labels.y:
# Sync priority labels from linked issues to PRs.
#
# Triggers:
# 1. PR opened/edited — parse issue links, copy priority label from issue(s)
# 2. Issue labeled/unlabeled — find open PRs that reference the issue, update
# 3. Manual dispatch — backfill open PRs (up to max_items)
#
# Priority labels are mutually exclusive on a PR. When a PR links to multiple
# issues with different priorities, the highest wins
# (priority:urgent > priority:high > priority:backlog).
#
# Only urgent and high propagate. Triage and backlog leave linked PRs
# without a priority label. Retired `p0`-`p4` labels are stripped
# from PRs rather than mapped to a new priority. See .github/LABELS.md.

name: Sync Priority Labels

on:
  # pull_request_target is safe here: we never check out or execute the
  # PR's code — only read the PR body and manage labels.
  # NEVER CHECK OUT UNTRUSTED CODE FROM A PR's HEAD IN A pull_request_target JOB.
  # Doing so would allow attackers to execute arbitrary code in the context of your repository.
  pull_request_target:
    types: [opened, edited]
  issues:
    types: [labeled, unlabeled]
  workflow_dispatch:
    inputs:
      max_items:
        description: "Maximum number of open PRs to process"
        default: "200"
        type: string

permissions:
  contents: read

# Serialize per PR (on PR events), per issue (on issue events), or
# globally (backfill). Note: two different issues that both link to the
# same PR may still race; both jobs re-derive the full correct state, so
# last-writer-wins converges.
concurrency:
  group: >-
    ${{ github.workflow }}-${{
      github.event_name == 'pull_request_target'
        && format('pr-{0}', github.event.pull_request.number)
        || github.event_name == 'issues'
        && format('issue-{0}', github.event.issue.number)
        || 'backfill'
    }}
  cancel-in-progress: ${{ github.event_name != 'workflow_dispatch' }}

jobs:
  # ── PR opened/edited: copy priority from linked issue(s) ──────────────
  sync-from-issue:
    if: github.event_name == 'pull_request_target'
    runs-on: ubuntu-latest
    permissions:
      pull-requests: write
      issues: write
    steps:
      - name: Sync priority label to PR
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          retries: 3
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request.number;
            const body = context.payload.pull_request.body || '';

            const PRIORITY_LABELS = ['priority:urgent', 'priority:high', 'priority:backlog'];
            // Only urgent and high propagate. Triage and backlog stay on issues;
            // a PR carrying backlog from an earlier run is stripped.
            const PROPAGATED_PRIORITY_LABELS = ['priority:urgent', 'priority:high'];
            // Retired names are stripped from PRs; remove once no open item has one.
            const STALE_PRIORITY_LABELS = ['p0', 'p1', 'p2', 'p3', 'p4'];
            const REMOVABLE_PRIORITY_LABELS = [...PRIORITY_LABELS, ...STALE_PRIORITY_LABELS];
            const LINK_RE = /(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)\s*#(\d+)/gi;

            // ── Helpers ──

            function parseIssueNumbers(text) {
              return [...new Set(
                [...text.matchAll(LINK_RE)].map(m => parseInt(m[1], 10)),
              )];
            }

            async function getIssueLabels(num) {
              try {
                const { data } = await github.rest.issues.get({
                  owner, repo, issue_number: num,
                });
                return data.labels.map(l => l.name);
              } catch (e) {
                if (e.status === 404) return null;
                throw e;
              }
            }

            function highestPriority(labelSets) {
              let best = null;
              for (const labels of labelSets) {
                if (!labels) continue;
                const idx = PRIORITY_LABELS.findIndex(p => labels.includes(p));
                if (idx !== -1 && (best === null || idx < best)) best = idx;
              }
              return best;
            }

            async function getPrLabelNames(num) {
              return (await github.paginate(
                github.rest.issues.listLabelsOnIssue,
                { owner, repo, issue_number: num, per_page: 100 },
              )).map(l => l.name);
            }

            async function removeLabel(num, name) {
              try {
                await github.rest.issues.removeLabel({
                  owner, repo, issue_number: num, name,
                });
                console.log(`Removed '${name}' from PR #${num}`);
              } catch (e) {
                if (e.status !== 404) throw e;
              }
            }

            async function ensureLabel(name) {
              try {
                await github.rest.issues.getLabel({ owner, repo, name });
              } catch (e) {
                if (e.status !== 404) throw e;
                try {
                  await github.rest.issues.createLabel({
                    // Inline the priority prefix color from pr-labeler-config.json
                    // because this workflow has no repository checkout.
                    // pr-labeler.test.js checks membership in the configured palette.
                    owner, repo, name, color: 'eba58b',
                  });
                } catch (createErr) {
                  if (createErr.status !== 422) throw createErr;
                }
              }
            }

            async function syncPrLabels(prNum, targetLabel) {
              const prLabels = await getPrLabelNames(prNum);

              // Remove stale priority labels
              for (const p of REMOVABLE_PRIORITY_LABELS) {
                if (prLabels.includes(p) && p !== targetLabel) {
                  await removeLabel(prNum, p);
                }
              }

              if (!targetLabel) return;
              if (prLabels.includes(targetLabel)) {
                console.log(`PR #${prNum} already has '${targetLabel}'`);
                return;
              }

              await ensureLabel(targetLabel);
              await github.rest.issues.addLabels({
                owner, repo, issue_number: prNum, labels: [targetLabel],
              });
              console.log(`Applied '${targetLabel}' to PR #${prNum}`);
            }

            // ── Main ──

            const issueNumbers = parseIssueNumbers(body);
            if (issueNumbers.length === 0) {
              console.log('No issue links found in PR body');
              return;
            }
            console.log(`Found linked issues: ${issueNumbers.map(n => '#' + n).join(', ')}`);

            const labelSets = await Promise.all(issueNumbers.map(getIssueLabels));
            const best = highestPriority(labelSets);
            const winner = best !== null ? PRIORITY_LABELS[best] : null;
            const targetLabel = PROPAGATED_PRIORITY_LABELS.includes(winner) ? winner : null;

            if (targetLabel) {
              console.log(`Highest priority across linked issues: ${targetLabel}`);
            } else {
              console.log('No priority labels found on linked issues');
            }

            await syncPrLabels(prNumber, targetLabel);

  # ── Issue labeled/unlabeled: propagate to PRs that link to it ─────────
  # The retired `p0`-`p4` names stay in the trigger during the label
  # migration: removing one from an issue must still clear the stale copy a
  # linked PR may carry. Drop them from the list once no open item has one.
  sync-to-prs:
    if: >-
      github.event_name == 'issues' &&
      contains(
        fromJSON('["priority:urgent","priority:high","priority:backlog","p0","p1","p2","p3","p4"]'),
        github.event.label.name
      )
    runs-on: ubuntu-latest
    permissions:
      pull-requests: write
      issues: write
    steps:
      - name: Propagate priority label to linked PRs
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          retries: 3
          script: |
            const { owner, repo } = context.repo;
            const issueNumber = context.payload.issue.number;
            const action = context.payload.action;

            const PRIORITY_LABELS = ['priority:urgent', 'priority:high', 'priority:backlog'];
            // Only urgent and high propagate. Triage and backlog stay on issues;
            // a PR carrying backlog from an earlier run is stripped.
            const PROPAGATED_PRIORITY_LABELS = ['priority:urgent', 'priority:high'];
            // Retired names are stripped from PRs; remove once no open item has one.
            const STALE_PRIORITY_LABELS = ['p0', 'p1', 'p2', 'p3', 'p4'];
            const REMOVABLE_PRIORITY_LABELS = [...PRIORITY_LABELS, ...STALE_PRIORITY_LABELS];
            const LINK_RE = /(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)\s*#(\d+)/gi;

            console.log(`Issue #${issueNumber} ${action} with '${context.payload.label.name}'`);

            // ── Helpers ──

            function parseIssueNumbers(text) {
              return [...new Set(
                [...text.matchAll(LINK_RE)].map(m => parseInt(m[1], 10)),
              )];
            }

            async function getIssueLabels(num) {
              try {
                const { data } = await github.rest.issues.get({
                  owner, repo, issue_number: num,
                });
                return data.labels.map(l => l.name);
              } catch (e) {
                if (e.status === 404) return null;
                throw e;
              }
            }

            function highestPriority(labelSets) {
              let best = null;
              for (const labels of labelSets) {
                if (!labels) continue;
                const idx = PRIORITY_LABELS.findIndex(p => labels.includes(p));
                if (idx !== -1 && (best === null || idx < best)) best = idx;
              }
              return best;
            }

            async function getPrLabelNames(num) {
              return (await github.paginate(
                github.rest.issues.listLabelsOnIssue,
                { owner, repo, issue_number: num, per_page: 100 },
              )).map(l => l.name);
            }

            async function removeLabel(num, name) {
              try {
                await github.rest.issues.removeLabel({
                  owner, repo, issue_number: num, name,
                });
                console.log(`Removed '${name}' from PR #${num}`);
              } catch (e) {
                if (e.status !== 404) throw e;
              }
            }

            async function ensureLabel(name) {
              try {
                await github.rest.issues.getLabel({ owner, repo, name });
              } catch (e) {
                if (e.status !== 404) throw e;
                try {
                  await github.rest.issues.createLabel({
                    // Inline the priority prefix color from pr-labeler-config.json
                    // because this workflow has no repository checkout.
                    // pr-labeler.test.js checks membership in the configured palette.
                    owner, repo, name, color: 'eba58b',
                  });
                } catch (createErr) {
                  if (createErr.status !== 422) throw createErr;
                }
              }
            }

            async function syncPrLabels(prNum, targetLabel) {
              const prLabels = await getPrLabelNames(prNum);

              for (const p of REMOVABLE_PRIORITY_LABELS) {
                if (prLabels.includes(p) && p !== targetLabel) {
                  await removeLabel(prNum, p);
                }
              }

              if (!targetLabel) {
                console.log(`No priority label remaining for PR #${prNum}`);
                return;
              }
              if (prLabels.includes(targetLabel)) {
                console.log(`PR #${prNum} already has '${targetLabel}'`);
                return;
              }

              await ensureLabel(targetLabel);
              await github.rest.issues.addLabels({
                owner, repo, issue_number: prNum, labels: [targetLabel],
              });
              console.log(`Applied '${targetLabel}' to PR #${prNum}`);
            }

            // ── Find open PRs that reference this issue ──
            // GitHub search treats the quoted number as a substring match
            // across title, body, and comments — low issue numbers (e.g. #1)
            // may return false positives. The specificLinkRe filter below
            // prunes them, but legitimate PRs could be pushed out of the
            // result page for very popular low numbers.

            const specificLinkRe = new RegExp(
              `(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)\\s*#${issueNumber}\\b`,
              'i',
            );

            let prs;
            try {
              const result = await github.rest.search.issuesAndPullRequests({
                q: `repo:${owner}/${repo} is:pr is:open "${issueNumber}"`,
                per_page: 100,
              });
              prs = result.data.items;
            } catch (e) {
              if (e.status === 422) {
                core.warning(`Search for PRs linking to #${issueNumber} returned 422 — skipping`);
                return;
              }
              throw e;
            }

            const linkedPRs = prs.filter(pr => specificLinkRe.test(pr.body || ''));
            if (linkedPRs.length === 0) {
              console.log(`No open PRs link to issue #${issueNumber}`);
              return;
            }
            console.log(`Found ${linkedPRs.length} PR(s) linking to #${issueNumber}: ${linkedPRs.map(p => '#' + p.number).join(', ')}`);

            // Pre-fetch the triggering issue's labels (post-event state)
            const triggeringLabels = await getPrLabelNames(issueNumber);

            // ── Resolve and sync each linked PR ──

            let failures = 0;
            for (const pr of linkedPRs) {
              try {
                // A PR may link to multiple issues — re-derive the correct
                // priority by checking all linked issues.
                const allIssueNumbers = parseIssueNumbers(pr.body || '');

                const labelSets = await Promise.all(
                  allIssueNumbers.map(num =>
                    num === issueNumber
                      ? Promise.resolve(triggeringLabels)
                      : getIssueLabels(num),
                  ),
                );

                const best = highestPriority(labelSets);
                const winner = best !== null ? PRIORITY_LABELS[best] : null;
                const targetLabel = PROPAGATED_PRIORITY_LABELS.includes(winner) ? winner : null;
                await syncPrLabels(pr.number, targetLabel);
              } catch (e) {
                failures++;
                core.warning(`Failed to sync PR #${pr.number}: ${e.message}`);
              }
            }

            if (failures > 0) {
              core.setFailed(`${failures} PR(s) failed to sync — check warnings above`);
            }

  # ── Manual backfill: sync priority labels on open PRs (up to max_items)
  backfill:
    if: github.event_name == 'workflow_dispatch'
    runs-on: ubuntu-latest
    permissions:
      pull-requests: write
      issues: write
    steps:
      - name: Backfill priority labels on open PRs
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          retries: 3
          script: |
            const { owner, repo } = context.repo;
            const rawMax = '${{ inputs.max_items }}';
            const maxItems = parseInt(rawMax, 10);
            if (isNaN(maxItems) || maxItems <= 0) {
              core.setFailed(`Invalid max_items: "${rawMax}" — must be a positive integer`);
              return;
            }

            const PRIORITY_LABELS = ['priority:urgent', 'priority:high', 'priority:backlog'];
            // Only urgent and high propagate. Triage and backlog stay on issues;
            // a PR carrying backlog from an earlier run is stripped.
            const PROPAGATED_PRIORITY_LABELS = ['priority:urgent', 'priority:high'];
            // Retired names are stripped from PRs; remove once no open item has one.
            const STALE_PRIORITY_LABELS = ['p0', 'p1', 'p2', 'p3', 'p4'];
            const REMOVABLE_PRIORITY_LABELS = [...PRIORITY_LABELS, ...STALE_PRIORITY_LABELS];
            const LINK_RE = /(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)\s*#(\d+)/gi;

            // ── Helpers ──

            function parseIssueNumbers(text) {
              return [...new Set(
                [...text.matchAll(LINK_RE)].map(m => parseInt(m[1], 10)),
              )];
            }

            async function getIssueLabels(num) {
              try {
                const { data } = await github.rest.issues.get({
                  owner, repo, issue_number: num,
                });
                return data.labels.map(l => l.name);
              } catch (e) {
                if (e.status === 404) return null;
                throw e;
              }
            }

            function highestPriority(labelSets) {
              let best = null;
              for (const labels of labelSets) {
                if (!labels) continue;
                const idx = PRIORITY_LABELS.findIndex(p => labels.includes(p));
                if (idx !== -1 && (best === null || idx < best)) best = idx;
              }
              return best;
            }

            async function getPrLabelNames(num) {
              return (await github.paginate(
                github.rest.issues.listLabelsOnIssue,
                { owner, repo, issue_number: num, per_page: 100 },
              )).map(l => l.name);
            }

            async function removeLabel(num, name) {
              try {
                await github.rest.issues.removeLabel({
                  owner, repo, issue_number: num, name,
                });
              } catch (e) {
                if (e.status !== 404) throw e;
              }
            }

            async function ensureLabel(name) {
              try {
                await github.rest.issues.getLabel({ owner, repo, name });
              } catch (e) {
                if (e.status !== 404) throw e;
                try {
                  await github.rest.issues.createLabel({
                    // Inline the priority prefix color from pr-labeler-config.json
                    // because this workflow has no repository checkout.
                    // pr-labeler.test.js checks membership in the configured palette.
                    owner, repo, name, color: 'eba58b',
                  });
                } catch (createErr) {
                  if (createErr.status !== 422) throw createErr;
                }
              }
            }

            // ── Main ──

            const prs = await github.paginate(github.rest.pulls.list, {
              owner, repo, state: 'open', per_page: 100,
            });

            let processed = 0;
            let updated = 0;
            let failures = 0;

            for (const pr of prs) {
              if (processed >= maxItems) break;
              processed++;

              try {
                const issueNumbers = parseIssueNumbers(pr.body || '');
                if (issueNumbers.length === 0) continue;

                const labelSets = await Promise.all(issueNumbers.map(getIssueLabels));
                const best = highestPriority(labelSets);
                const winner = best !== null ? PRIORITY_LABELS[best] : null;
                const targetLabel = PROPAGATED_PRIORITY_LABELS.includes(winner) ? winner : null;

                const prLabels = await getPrLabelNames(pr.number);
                const currentPriority = PRIORITY_LABELS.find(p => prLabels.includes(p)) || null;

                // Stale names are checked separately from `currentPriority`,
                // which only knows the current taxonomy. A PR carrying `p2`
                // and nothing else made `currentPriority` and `targetLabel`
                // both null, so the equality below skipped the removal loop
                // and the retired label survived — in the one job whose
                // purpose is to strip it.
                const stale = STALE_PRIORITY_LABELS.filter(p => prLabels.includes(p));

                if (currentPriority === targetLabel && !stale.length) {
                  console.log(`PR #${pr.number}: already correct (${targetLabel || 'none'})`);
                  continue;
                }

                // Remove stale priority labels
                for (const p of REMOVABLE_PRIORITY_LABELS) {
                  if (prLabels.includes(p) && p !== targetLabel) {
                    await removeLabel(pr.number, p);
                  }
                }

                // Apply correct label
                if (targetLabel) {
                  await ensureLabel(targetLabel);
                  await github.rest.issues.addLabels({
                    owner, repo, issue_number: pr.number, labels: [targetLabel],
                  });
                }

                // `stale` is reported on its own: in the retired-label case
                // both `currentPriority` and `targetLabel` are null, which
                // would otherwise log the misleading `(none) → null`.
                const from = currentPriority ?? (stale.length ? stale.join(', ') : '(none)');
                console.log(`PR #${pr.number}: ${from} → ${targetLabel ?? '(removed)'}`);
                updated++;
              } catch (e) {
                failures++;
                core.warning(`Failed to process PR #${pr.number}: ${e.message}`);
              }
            }

            console.log(`\nBackfill complete. Scanned ${processed} PRs, updated ${updated}, ${failures} failures.`);
            if (failures > 0) {
              core.setFailed(`${failures} PR(s) failed to process — check warnings above`);
            }

.github/workflows/tag-external-issues.ym:
# Automatically tag issues as "org:external" or "org:internal" based on whether
# the author is a member of the langchain-ai GitHub organization, and
# apply contributor tier labels to external contributors based on their
# merged PR history.
#
# PR classification is in pr_labeler.yml to avoid race conditions with
# concurrent label workflows.
#
# Setup Requirements:
# 1. Create a GitHub App with permissions:
#    - Repository: Issues (write)
#    - Organization: Members (read)
# 2. Install the app on your organization and this repository
# 3. Add the repository credentials:
#    - Variable ORG_MEMBERSHIP_APP_CLIENT_ID: Your app's Client ID
#    - Secret ORG_MEMBERSHIP_APP_PRIVATE_KEY: Your app's private key
#
# The GitHub App token is required to check private organization membership.
# Without it, the workflow will fail.
#
# Contributor tier thresholds and label colors are in
# .github/scripts/labeling/pr-labeler-config.json

name: Tag External Issues

on:
  issues:
    types: [opened]
  workflow_dispatch:
    inputs:
      max_items:
        description: "Maximum number of open issues to process"
        default: "100"
        type: string

permissions:
  contents: read

concurrency:
  group: ${{ github.workflow }}-${{ github.event.issue.number || github.run_id }}
  cancel-in-progress: true

jobs:
  tag-external:
    if: github.event_name == 'issues'
    runs-on: ubuntu-latest
    permissions:
      contents: read
      issues: write

    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1

      - name: Generate GitHub App token
        id: app-token
        uses: actions/create-github-app-token@64ab729a6294000f5aa4a4bc0b73d1f32bc45510 # v3
        with:
          client-id: ${{ vars.ORG_MEMBERSHIP_APP_CLIENT_ID }}
          private-key: ${{ secrets.ORG_MEMBERSHIP_APP_PRIVATE_KEY }}

      - name: Check if contributor is external
        if: steps.app-token.outcome == 'success'
        id: check-membership
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          script: |
            const { owner, repo } = context.repo;
            const { h } = require('./.github/scripts/labeling/pr-labeler.js').loadAndInit(github, owner, repo, core);

            const author = context.payload.sender.login;
            const { isExternal } = await h.checkMembership(
              author, context.payload.sender.type,
            );
            core.setOutput('is-external', isExternal ? 'true' : 'false');

      - name: Apply contributor tier label
        if: steps.check-membership.outputs.is-external == 'true'
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          # GITHUB_TOKEN is fine here — no downstream workflow chains
          # off tier labels on issues (unlike PRs where App token is
          # needed for require_issue_link.yml).
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const { h } = require('./.github/scripts/labeling/pr-labeler.js').loadAndInit(github, owner, repo, core);

            const issue = context.payload.issue;
            // auto:new-contributor is only meaningful on PRs, not issues
            await h.applyTierLabel(issue.number, issue.user.login, { skipNewContributor: true });

      - name: Add external/internal label
        if: steps.check-membership.outputs.is-external != ''
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const issue_number = context.payload.issue.number;

            const { h } = require('./.github/scripts/labeling/pr-labeler.js').loadAndInit(github, owner, repo, core);

            const label = '${{ steps.check-membership.outputs.is-external }}' === 'true'
              ? 'org:external' : 'org:internal';
            await h.ensureLabel(label);
            await github.rest.issues.addLabels({
              owner, repo, issue_number, labels: [label],
            });
            console.log(`Added '${label}' label to issue #${issue_number}`);

  backfill:
    if: github.event_name == 'workflow_dispatch'
    runs-on: ubuntu-latest
    permissions:
      contents: read
      issues: write

    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1

      - name: Generate GitHub App token
        id: app-token
        uses: actions/create-github-app-token@64ab729a6294000f5aa4a4bc0b73d1f32bc45510 # v3
        with:
          client-id: ${{ vars.ORG_MEMBERSHIP_APP_CLIENT_ID }}
          private-key: ${{ secrets.ORG_MEMBERSHIP_APP_PRIVATE_KEY }}

      - name: Backfill labels on open issues
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          script: |
            const { owner, repo } = context.repo;
            const rawMax = '${{ inputs.max_items }}';
            const maxItems = parseInt(rawMax, 10);
            if (isNaN(maxItems) || maxItems <= 0) {
              core.setFailed(`Invalid max_items: "${rawMax}" — must be a positive integer`);
              return;
            }

            const { config, h } = require('./.github/scripts/labeling/pr-labeler.js').loadAndInit(github, owner, repo, core);

            const tierLabels = [h.tierLabelsByTier.trusted];
            for (const name of tierLabels) {
              await h.ensureLabel(name);
            }

            const contributorCache = new Map();
            const issues = await github.paginate(github.rest.issues.listForRepo, {
              owner, repo, state: 'open', per_page: 100,
            });

            let processed = 0;
            let failures = 0;
            for (const issue of issues) {
              if (processed >= maxItems) break;
              if (issue.pull_request) continue;

              // Counted before the work, not after it: an issue that throws
              // still consumed an attempt. Leaving it uncounted lets a run
              // whose every issue failed walk the whole open backlog while
              // reporting `Processed 0`. Matches pr_labeler_backfill.yml.
              processed++;

              try {
                const author = issue.user.login;
                const info = await h.getContributorInfo(contributorCache, author, issue.user.type);

                const labels = [info.isExternal ? 'org:external' : 'org:internal'];
                // Tier unknown (the merged-PR search failed) — see the same
                // guard in pr_labeler_backfill.yml. Reconciling against an
                // incomplete set would strip `auto:trusted-contributor`.
                if (!info.tierKnown) {
                  failures++;
                  core.warning(
                    `Issue #${issue.number}: contributor tier unknown for ${author} — leaving tier labels untouched`,
                  );
                }
                if (info.isExternal && info.mergedCount != null && info.mergedCount >= h.trustedThreshold) {
                  labels.push(h.tierLabelsByTier.trusted);
                }

                // Ensure all labels exist before batch add
                for (const name of labels) {
                  await h.ensureLabel(name);
                }

                // Remove stale tier labels
                const currentLabels = (await github.paginate(
                  github.rest.issues.listLabelsOnIssue,
                  { owner, repo, issue_number: issue.number, per_page: 100 },
                )).map(l => l.name ?? '');
                for (const name of currentLabels) {
                  if (info.tierKnown && tierLabels.includes(name) && !labels.includes(name)) {
                    try {
                      await github.rest.issues.removeLabel({
                        owner, repo, issue_number: issue.number, name,
                      });
                    } catch (e) {
                      if (e.status !== 404) throw e;
                    }
                  }
                }

                await github.rest.issues.addLabels({
                  owner, repo, issue_number: issue.number, labels,
                });
                console.log(`Issue #${issue.number} (${author}): ${labels.join(', ')}`);
              } catch (e) {
                failures++;
                core.warning(`Failed to process issue #${issue.number}: ${e.message}`);
              }
            }

            console.log(`\nBackfill complete. Processed ${processed} issues, ${failures} failures. ${contributorCache.size} unique authors.`);
            // Without this the job is green however many issues threw, and
            // this is the workflow an operator runs to apply the taxonomy to
            // the existing backlog — a false success reads as "migration
            // done". Matches the backfill in pr_labeler_backfill.yml.
            if (failures > 0) {
              core.setFailed(`${failures} issue(s) failed to process — check warnings above`);
            }

.github/workflows/waiting_on_author.yml:
# Close issues and PRs ten days after a maintainer applies `auto:waiting-on-author`,
# or legacy `waiting-on-author`, unless the original author explicitly replies.
# The timeout is measured from the latest label event, so unrelated activity
# never resets it. Maintainers can therefore ask their question before or after
# applying the label.
#
# This workflow records author responses from conversation comments
# (`issue_comment`, which covers issues and PR conversations), review-thread
# replies (`pull_request_review_comment`), and submitted reviews
# (`pull_request_review`). Pushing commits does not clear the label: a
# maintainer must decide whether the change addressed their question.
# Bot-authored items, draft PRs, and anything carrying `ci:keep-open` or legacy
# `do-not-close` are never closed.
#
# The follow-up workflow runs under `workflow_run` in the base-branch context,
# which grants a write token for fork PRs. It validates the response against the
# GitHub API before mutating a label; neither workflow checks out or executes PR
# code.

name: Waiting On Author

on:
  issue_comment:
    types: [created]
  pull_request_review:
    types: [submitted]
  pull_request_review_comment:
    types: [created]
  schedule:
    - cron: "0 */6 * * *"
  workflow_dispatch:

permissions:
  contents: read

# Key the concurrency group by issue/PR number for author-activity events so an
# author's reply is never discarded behind an unrelated comment or the
# scheduled scan; scheduled/dispatch runs share one group.
concurrency:
  group: ${{ github.workflow }}-${{ github.event.issue.number || github.event.pull_request.number || 'scheduled' }}
  cancel-in-progress: false

jobs:
  # This job always runs with the workflow's read-only token — fork-origin
  # events could not be granted write anyway — so it cannot remove a label
  # itself. It records only immutable identifiers for the trusted
  # `workflow_run` consumer, which re-fetches and verifies everything.
  record-author-response:
    if: >-
      github.repository == 'langchain-ai/deepagents' &&
      contains(
        fromJSON('["issue_comment", "pull_request_review", "pull_request_review_comment"]'),
        github.event_name
      )
    runs-on: ubuntu-latest
    timeout-minutes: 5

    steps:
      - name: Record response identifier
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const response = {
              eventName: context.eventName,
              responseId:
                context.payload.comment?.id ?? context.payload.review?.id,
              pullNumber: context.payload.pull_request?.number,
            };

            if (!response.responseId) {
              core.setFailed(`No response ID found for ${context.eventName}`);
              return;
            }

            const fs = require('fs');
            fs.writeFileSync(
              `${process.env.RUNNER_TEMP}/author-response.json`,
              JSON.stringify(response),
            );

      - name: Upload response identifier
        uses: actions/upload-artifact@cf430e030ddbb5b0abf93d22962f4752f3646cd9 # v7
        with:
          name: author-response
          path: ${{ runner.temp }}/author-response.json
          if-no-files-found: error
          retention-days: 1

  close-expired-items:
    if: >-
      github.repository == 'langchain-ai/deepagents' &&
      (github.event_name == 'schedule' || github.event_name == 'workflow_dispatch')
    runs-on: ubuntu-latest
    timeout-minutes: 10
    permissions:
      issues: write
      pull-requests: write

    steps:
      - name: Close issues and PRs awaiting an author response
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const { owner, repo } = context.repo;
            // Accept existing lifecycle state until legacy labels are migrated.
            const waitingOnAuthorLabels = new Set(['auto:waiting-on-author', 'waiting-on-author']);
            // Preserve exemptions applied before the taxonomy migration.
            const bypassLabels = new Set(['ci:keep-open', 'do-not-close']);
            const timeoutMs = 10 * 24 * 60 * 60 * 1000;
            const closeMessage =
              'This item has been automatically closed because we have not received a response from the original author. Please comment with any additional information if you would like us to reopen it.';

            // Mirrored inline in waiting_on_author_reply.yml; keep both in step.
            function findLatestLabelEvent(events) {
              return events
                .filter(
                  (event) =>
                    event.event === 'labeled' &&
                    waitingOnAuthorLabels.has(event.label?.name) &&
                    event.created_at,
                )
                .sort((a, b) => Date.parse(b.created_at) - Date.parse(a.created_at))[0];
            }

            async function authorRespondedAfter(item, labelTime) {
              const responseByAuthor = (response) =>
                response.user?.type !== 'Bot' &&
                response.user?.login === item.user.login &&
                Date.parse(response.created_at ?? response.submitted_at) > labelTime;

              const comments = await github.paginate(github.rest.issues.listComments, {
                owner,
                repo,
                issue_number: item.number,
                since: new Date(labelTime).toISOString(),
                per_page: 100,
              });
              if (comments.some(responseByAuthor)) return true;

              if (!item.pull_request) return false;

              const [reviewComments, reviews] = await Promise.all([
                github.paginate(github.rest.pulls.listReviewComments, {
                  owner,
                  repo,
                  pull_number: item.number,
                  per_page: 100,
                }),
                github.paginate(github.rest.pulls.listReviews, {
                  owner,
                  repo,
                  pull_number: item.number,
                  per_page: 100,
                }),
              ]);
              return reviewComments.some(responseByAuthor) || reviews.some(responseByAuthor);
            }

            // The API combines multiple labels with AND, so query each name
            // separately and process items carrying both labels only once.
            const items = new Map();
            for (const label of waitingOnAuthorLabels) {
              const matches = await github.paginate(github.rest.issues.listForRepo, {
                owner,
                repo,
                state: 'open',
                labels: label,
                per_page: 100,
              });
              for (const item of matches) items.set(item.number, item);
            }

            for (const item of items.values()) {
              if (
                item.user?.type === 'Bot' ||
                item.labels.some((label) => bypassLabels.has(label.name))
              ) {
                continue;
              }

              if (item.pull_request) {
                const pullRequest = (
                  await github.rest.pulls.get({
                    owner,
                    repo,
                    pull_number: item.number,
                  })
                ).data;
                if (pullRequest.draft) continue;
              }

              const events = await github.paginate(github.rest.issues.listEvents, {
                owner,
                repo,
                issue_number: item.number,
                per_page: 100,
              });
              const latestLabelEvent = findLatestLabelEvent(events);

              if (!latestLabelEvent) {
                core.warning(
                  `No waiting-on-author label event found for #${item.number}; leaving it open.`,
                );
                continue;
              }

              if (Date.now() - Date.parse(latestLabelEvent.created_at) < timeoutMs) {
                continue;
              }

              // Re-fetch the item and event history immediately before mutating
              // it so a newly applied label cannot inherit an older timeout.
              const currentItem = (
                await github.rest.issues.get({
                  owner,
                  repo,
                  issue_number: item.number,
                })
              ).data;
              if (
                currentItem.state !== 'open' ||
                !currentItem.labels.some((label) => waitingOnAuthorLabels.has(label.name)) ||
                currentItem.labels.some((label) => bypassLabels.has(label.name))
              ) {
                continue;
              }

              const currentEvents = await github.paginate(
                github.rest.issues.listEvents,
                {
                  owner,
                  repo,
                  issue_number: item.number,
                  per_page: 100,
                },
              );
              const currentLabelEvent = findLatestLabelEvent(currentEvents);

              if (
                !currentLabelEvent ||
                currentLabelEvent.created_at !== latestLabelEvent.created_at
              ) {
                console.log(`waiting-on-author was reapplied to #${item.number}; skipping.`);
                continue;
              }

              const labelTime = Date.parse(currentLabelEvent.created_at);
              if (await authorRespondedAfter(currentItem, labelTime)) {
                for (const label of currentItem.labels) {
                  if (!waitingOnAuthorLabels.has(label.name)) continue;
                  try {
                    await github.rest.issues.removeLabel({
                      owner,
                      repo,
                      issue_number: item.number,
                      name: label.name,
                    });
                  } catch (error) {
                    if (error.status !== 404) throw error;
                  }
                }
                console.log(
                  `Removed waiting-on-author from #${item.number} after an author reply.`,
                );
                continue;
              }

              // The author-response check above ran before the mutations below,
              // so a reply landing between them would be closed over — and the
              // follow-up workflow skips closed items, so nothing would clear
              // the label afterward. Re-fetch once at the mutation boundary and
              // treat any changed state (reply, close, relabel, ci:keep-open,
              // or a PR flipped to draft) as a signal to leave the item alone.
              // `updated_at` moves on anyone's activity, not just the author's,
              // so this is deliberately coarse: a false positive only defers
              // closure to the next scheduled run. It is not a complete guard
              // either — activity that leaves `updated_at` untouched (review-
              // thread replies may not bump it) still slips through the window.
              const finalItem = (
                await github.rest.issues.get({
                  owner,
                  repo,
                  issue_number: item.number,
                })
              ).data;
              if (
                finalItem.state !== 'open' ||
                finalItem.updated_at !== currentItem.updated_at ||
                !finalItem.labels.some((label) => waitingOnAuthorLabels.has(label.name)) ||
                finalItem.labels.some((label) => bypassLabels.has(label.name))
              ) {
                console.log(`#${item.number} changed during the scan; skipping.`);
                continue;
              }

              if (finalItem.pull_request) {
                const finalPullRequest = (
                  await github.rest.pulls.get({
                    owner,
                    repo,
                    pull_number: item.number,
                  })
                ).data;
                if (finalPullRequest.draft) {
                  console.log(`#${item.number} became a draft during the scan; skipping.`);
                  continue;
                }
              }

              await github.rest.issues.createComment({
                owner,
                repo,
                issue_number: item.number,
                body: closeMessage,
              });
              await github.rest.issues.update({
                owner,
                repo,
                issue_number: item.number,
                state: 'closed',
              });
              console.log(`Closed #${item.number} after ten days without a response.`);
            }

.github/workflows/waiting_on_author_repl:
# Clear both waiting-on-author label names after a recorded author reply.
#
# `workflow_run` executes this definition from the default branch and receives
# a write-capable token for fork-origin events. The artifact is untrusted input:
# this workflow uses it only as an event-kind selector plus an ID pair that the
# GitHub API cross-validates (a review ID that does not belong to the given PR
# number 404s), then fetches the comment or review and the current item directly
# from GitHub and re-verifies authorship before removing a label.
# It never checks out or executes contributor-controlled code.

name: Clear Waiting On Author After Author Reply

on:
  workflow_run:
    # `workflow_run` consumers always run from the default branch, so runs of
    # the producer that were in flight when this rename merged still report the
    # old name. Drop "Needs Response" once no such run can be pending.
    workflows: ["Waiting On Author", "Needs Response"]
    types: [completed]

permissions:
  contents: read

concurrency:
  group: ${{ github.workflow }}-${{ github.event.workflow_run.id }}
  cancel-in-progress: false

jobs:
  remove-label:
    if: >-
      github.repository == 'langchain-ai/deepagents' &&
      github.event.workflow_run.conclusion == 'success' &&
      contains(
        fromJSON('["issue_comment", "pull_request_review", "pull_request_review_comment"]'),
        github.event.workflow_run.event
      )
    runs-on: ubuntu-latest
    timeout-minutes: 5
    permissions:
      actions: read
      issues: write
      pull-requests: write

    steps:
      - name: Download response identifier
        uses: actions/download-artifact@9000827ccba6bdab643e8b6fd33ac0654aef8333 # v8
        with:
          name: author-response
          path: response
          run-id: ${{ github.event.workflow_run.id }}
          github-token: ${{ github.token }}

      - name: Verify author response and remove label
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const fs = require('fs');
            const response = JSON.parse(
              fs.readFileSync('response/author-response.json', 'utf8'),
            );
            const { owner, repo } = context.repo;
            // Accept existing lifecycle state until legacy labels are migrated.
            const waitingOnAuthorLabels = new Set(['auto:waiting-on-author', 'waiting-on-author']);

            function numberFromUrl(url, resource) {
              const match = new URL(url).pathname.match(
                new RegExp(`/${resource}/(\\d+)$`),
              );
              return match ? Number(match[1]) : undefined;
            }

            let item;
            let responseData;
            let responseTime;
            let issueNumber;

            if (response.eventName === 'issue_comment') {
              responseData = (
                await github.rest.issues.getComment({
                  owner,
                  repo,
                  comment_id: response.responseId,
                })
              ).data;
              issueNumber = numberFromUrl(responseData.issue_url, 'issues');
              responseTime = responseData.created_at;
            } else if (response.eventName === 'pull_request_review_comment') {
              responseData = (
                await github.rest.pulls.getReviewComment({
                  owner,
                  repo,
                  comment_id: response.responseId,
                })
              ).data;
              issueNumber = numberFromUrl(
                responseData.pull_request_url,
                'pulls',
              );
              responseTime = responseData.created_at;
            } else if (
              response.eventName === 'pull_request_review' &&
              Number.isInteger(response.pullNumber)
            ) {
              responseData = (
                await github.rest.pulls.getReview({
                  owner,
                  repo,
                  pull_number: response.pullNumber,
                  review_id: response.responseId,
                })
              ).data;
              issueNumber = response.pullNumber;
              responseTime = responseData.submitted_at;
            } else {
              core.warning('Ignoring an artifact with an unsupported response.');
              return;
            }

            if (!issueNumber || !responseTime) {
              core.warning('Ignoring a response with no item number or timestamp.');
              return;
            }

            item = (
              await github.rest.issues.get({
                owner,
                repo,
                issue_number: issueNumber,
              })
            ).data;

            if (
              item.state !== 'open' ||
              !item.labels.some((label) => waitingOnAuthorLabels.has(label.name)) ||
              item.user.type === 'Bot' ||
              responseData.user.type === 'Bot' ||
              responseData.user.login !== item.user.login
            ) {
              console.log(`Response on #${issueNumber} is not eligible.`);
              return;
            }

            // Do not clear a label that was applied after this response. The
            // event history is the source of truth rather than the untrusted
            // artifact or a race-prone current-label-only check.
            const events = await github.paginate(github.rest.issues.listEvents, {
              owner,
              repo,
              issue_number: issueNumber,
              per_page: 100,
            });
            // Mirrors findLatestLabelEvent in waiting_on_author.yml; keep in step.
            const latestLabelEvent = events
              .filter(
                (event) =>
                  event.event === 'labeled' &&
                  waitingOnAuthorLabels.has(event.label?.name) &&
                  event.created_at,
              )
              .sort((a, b) => Date.parse(b.created_at) - Date.parse(a.created_at))[0];

            if (!latestLabelEvent) {
              core.warning(
                `No waiting-on-author label event found for #${issueNumber}; leaving it intact.`,
              );
              return;
            }

            if (Date.parse(responseTime) <= Date.parse(latestLabelEvent.created_at)) {
              console.log(
                `Response on #${issueNumber} predates its current waiting-on-author label.`,
              );
              return;
            }

            for (const label of item.labels) {
              if (!waitingOnAuthorLabels.has(label.name)) continue;
              try {
                await github.rest.issues.removeLabel({
                  owner,
                  repo,
                  issue_number: issueNumber,
                  name: label.name,
                });
              } catch (error) {
                if (error.status !== 404) throw error;
                console.log(`${label.name} was already absent from #${issueNumber}.`);
              }
            }

            console.log(`Removed waiting-on-author from #${issueNumber}.`);
